/* 平成27年委員会データ（自動生成・分割ファイル） */
window.SHINAGAWA_DB.years.h27.committeeSessions.push(...[{"id":"h27-20151201-6","meetingId":"h27-cm12","date":"2015年12月1日","dateIso":"2015-12-01","committee":"区民委員会","time":"午前１０時００分～午後 １時２５分","status":"正式会議録","sourceType":"formal","overview":"区民委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を45件整理しています。","topics":[{"id":"topic-01","title":"外国人おもてなし語学ボランティア育成講座","agenda":"外国人おもてなし語学ボランティア育成講座","exchanges":[{"speaker":"南委員","kind":"質問・要望","question":"８０名応募というふうに言われたのですけれども、その募集の仕方はどういうふうになっているのか、教えてほしいと求めました。","respondent":"河内協働・国際担当課長","answer":"これは英会話教室の受講者の応募状況に応じてまた考えていきたいと考えていますので、「等」といたしております。広報など、さまざまなものを通じまして、一般公募する場合には募集してまいりたいという考えです。","id":"exchange-001"},{"speaker":"南委員","kind":"意見","question":"それなりのもっと大きないろいろな意味での効果が出ると思うのでいいと思うのですけれども、だから、１２０名を超えた場合にどういうふうにするのか。","respondent":"河内協働・国際担当課長","answer":"各回６０名の定員のお話ですが、こちらの事業につきましては、都と連携事業ということで、都からの講師が派遣されてまいります。６０名という定員は都からの講師を活用するという意味で、今後、検討していきたいと考えています。","id":"exchange-002"},{"speaker":"藤原委員","kind":"確認","question":"確認なのですけれども、なぜ外国人おもてなし語学という形でやって英語だったのですか。東南アジアという意味で考えるならばという思いがあったので、なぜ英語だったのですかということが１点。","respondent":"河内協働・国際担当課長","answer":"それから３つ目の国別ですが、１６９カ国と聞いておりますが、全ての国に対して対応することはなかなか困難です。は英語というふうに考えておりまして、これは今後の展開の考え方ですが、今後考えていきたいというふうに思っているところです。","id":"exchange-003"},{"speaker":"藤原委員","kind":"質問・要望","question":"確認させていただいて、外国から見て上位に上がるのが、日本の安全で安心というところがよく出るではないですか。その連携がどういうふうになっていくのか、それとオリンピック・パラリンピックを担当している課長の両方からお話をいただきたいのですけれども。","respondent":"河内協働・国際担当課長、小川オリンピック・パラリンピック準備課長","answer":"オリンピック・パラリンピック準備課との連携です。何人、連携をして考えたところで、オリンピック・パラリンピックの成功に向けて尽力していきたいというふうに考えている次第です。これはそもそも東京都が先行して昨年度より実施している事業でございまして、また、品川区のボランティアの育成にもつながるというものです。","id":"exchange-004"},{"speaker":"松永委員","kind":"質問","question":"私は、都との連携で、品川区はどのくらいの予算を使われる予定なのかお伺いしたいと思います。例えば学校、スクール形式の講師が１人で６０人バッとやるのか、その内容を詳しくご回答を。","respondent":"河内協働・国際担当課長","answer":"１人が外国人役、１人が案内役になりまして、外国人の目線がどのようなところに動くのかというところの練習をすることになります。そういった講座を行いまして、おもてなしのボランティアにつきまして育成を図るという内容です。","id":"exchange-005"},{"speaker":"松永委員","kind":"質問","question":"先ほどの南委員の質問とかぶるかわからないのですが、普通の「This is a pen」とか、ある程度の知識というのはどのくらいなのか。例えば、ある程度の英語力があれば誰でも受けられるように今後なっていくのか、その辺を伺いたいと思います。","respondent":"河内協働・国際担当課長","answer":"英検２級、ＴＯＥＩＣ５００点以上というところになっておりますが、英語による簡単な日常会話ができるレベルというふうな表現も出ております。コミュニケーション力など、広く役立てていただきながら、多くの方にご参加いただくようなスキームになっております。","id":"exchange-006"},{"speaker":"たけうち委員","kind":"質問","question":"どうですか」とかというふうにやるのか、その枠組みというのですか、取組みがあるのかどうかということが１つ。英会話講座はやっているというふうにお聞きしたのですが、そういうものがあるかどうか、それを２つ。","respondent":"河内協働・国際担当課長","answer":"それから２点目、今後の区の取組みです。区といたしましては、今、都と連携ですが、同様な育成の取組みにつきまして、今後、取り組んでいきたいというような考えでおるところです。","id":"exchange-007"},{"speaker":"渡部副委員長","kind":"質問","question":"たけうち委員が伺ったようなところで聞きたかったところがあって、都との連携事業ということは、実際その辺はどうなのか。都のほうの委託でしょうから、さまざまな勉強をされているような方が、もしそういう資格があるのだったら受けたいと思ってくるのではないか。","respondent":"河内協働・国際担当課長","answer":"この講座を開始いたしまして、３カ月間の２区間を今、募集してやっているというような情報が入っております。今後の予定ですが、５年後になると思いますが、参加していただきたいというふうに考えております。","id":"exchange-008"},{"speaker":"渡部副委員長","kind":"質問・要望","question":"門は開いておいてあげてほしいなと。ある程度の定員等も必要かもしれませんけれども、何か門戸を開いてできるような仕組みを区としてつくっていただければと要望して終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-009"},{"speaker":"田中委員","kind":"質問","question":"道案内等の手助けをするボランティアの育成講座ということで、福祉的な手助けに対しての講座も開かれているのでしょうか。障害を持った外国の方に対しての対応とかもこの中にも含まれているのかということを質問させていただくよう求めました。","respondent":"河内協働・国際担当課長","answer":"助けられないところは人を呼んでくるなりする。福祉的な専門的なところではないかもしれませんけれども、そういった側面が出てきたら、当然ながらやっていくような形を想定している講座です。","id":"exchange-010"},{"speaker":"田中委員","kind":"質問","question":"そういった場合のロールプレイングもなさっているということでよろしいか尋ねました。","respondent":"河内協働・国際担当課長","answer":"詳細についてまだ完全に把握しきっている状況ではありませんので、趣旨的にはそのようなところを、困っている方をお助けするというような性質のものです。","id":"exchange-011"}]},{"id":"topic-02","title":"「マスコット防犯ＰＲ活動事業」協定書調印式","agenda":"「マスコット防犯ＰＲ活動事業」協定書調印式","exchanges":[{"speaker":"たけうち委員","kind":"質問","question":"去年からスタートということで、去年の内容もわからないですけれども、協定書の調印というのは、毎年やられるのか。いわゆるマスコミとかもお声をかけてどんどん来て取り上げてもらおうということが１つ大事なところかと思うのですが、その辺があれば説明を求めました。","respondent":"濱田生活安全担当課長","answer":"昨年、先ほど説明いたしましたが、これは大きな二本立てです。そういう予定です。","id":"exchange-012"},{"speaker":"たけうち委員","kind":"意見","question":"今、去年の７事業者を聞いたら、それぞれ個別にいろいろなホームページ等で出ていたものが記憶にあったので、非常にすごい取組みだなと思います。では、ぜひ期待していますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-013"},{"speaker":"藤原委員","kind":"質問","question":"やっているのですね、もう。質問を変えて、ちょっとストレートな質問になってしまうかもしれないのですけれども、効果があるというふうに思っていますか。","respondent":"濱田生活安全担当課長","answer":"しなぼうというのは、ご存じのように、子どもたちにもそういったことで啓発になると思います。まち、いわゆる商店とか町会等、ここでコラボすることによって、商店と町会等の活性化等にもつながると私は考えております。","id":"exchange-014"},{"speaker":"藤原委員","kind":"質問","question":"いい意味で活用していくかということをお伺いしたいのと、もう１つは、結論から言うと言ってくださいまして安心しまして。２３区、今の時点で気持ちがあるぐらい効果があるのだということを、改めてその辺の答弁をいただければ幸いに思いますけれども。","respondent":"堀越地域振興部長、濱田生活安全担当課長","answer":"それから、先ほど、生活安全担当課長が答弁しましたけれども、しなぼうは、子ども１１０番の家といいますか、いろいろ全区的な取組みがあります。それから親御さんをはじめ浸透してきているという部分もありますので… これは昭和６１年に、そんなに古いので、あまり効果はないのかと私は正直思っていました。戻った際には、こういった施策はいい施策だということで、広く進めたいと思います。","id":"exchange-015"},{"speaker":"藤原委員","kind":"質問","question":"お二人の答弁を伺って、ちょっと現実になってお金のことなのですけれども、このマスコットにお金的な契約という部分はどうなっているのでしょうか。いわゆる契約ですから、これはボランティアなのか、それとも１マスコットに幾らお支払いするのか、その辺の予算を説明するよう求めました。","respondent":"濱田生活安全担当課長","answer":"現在、相互扶助の関係ということで、予算等はここには何もつけてございません。","id":"exchange-016"},{"speaker":"松永委員","kind":"質問","question":"このマスコットが、今回は１１あるということなのですが、そのほかにもいろいろあると思うのです。来年もまだ登録というか、また随時こうやって、こういうものをやりますというような案内で増やしていく予定はあるのかお伺いしたいと思います。","respondent":"濱田生活安全担当課長","answer":"１つのある商店会のほうで、１つの商店会だけが今、保留という形になっています。は全部、今回参加です。","id":"exchange-017"},{"speaker":"南委員","kind":"質問・要望","question":"どういうことなのかを教えていただきたいのと、昨年度は７事業者と２６とおっしゃった、その２６が何だったのかを改めて確認したいのですけれども。いろいろ７事業者が名乗りを上げておられましたけれども、２６という数字を言ったような気がしているので、お願いします。","respondent":"濱田生活安全担当課長","answer":"それと、２６の数字は、平成２６年度です。平成２６年度は７事業者ということです。","id":"exchange-018"}]},{"id":"topic-03","title":"マイナンバー「通知カード」の送付等","agenda":"マイナンバー「通知カード」の送付等","exchanges":[{"speaker":"南委員","kind":"質問・要望","question":"繰り返してしまうのですけれども、業務委託というか、正規の職員以外の方も触れるのかどうかということを確認したいと思います。１２月になりましたから、いろいろなことで住民票の異動とかもあると思うので、その辺についてどうなのかを伺いたいと思います。","respondent":"井浦戸籍住民課長","answer":"申請書に順次個人番号を書いていただくという形で始まってまいりますので、情報安全をしっかりと図っていくというところで準備を進めてあります。","id":"exchange-019"},{"speaker":"南委員","kind":"質問","question":"来年以降についてはまだ始まったばかりですからあれですけれども、その辺、どういうふうに考えておられるかを１点知りたいと思いました。誤配達が２件あったということで、丁寧に郵便局で対応されたということなのですけれども、この誤配達してしまった理由は何だったのか尋ねました。","respondent":"井浦戸籍住民課長","answer":"１日３００件を交付するという体制を構築していますので、６００人来てしまったので６００人で対応するというようなことは考えてございません。もう１件は、正当受取人様に丁寧にご説明を申し上げて、ご理解をいただいたところです。","id":"exchange-020"},{"speaker":"南委員","kind":"質問・要望","question":"走ってしまったわけですから、必要なところは必要な手を打つという、そこのところをもう１回再確認をしたいと思います。なるほどなと伺って、しっかりとやっていくということが求められるところなので、改めて大事かと思いました。","respondent":"井浦戸籍住民課長","answer":"通知カードの対応につきましても、１２月１日から委託での窓口対応ということも導入しまして、職員のしっかりとした対応体制。その関係で、必要になった方については、再交付ということで対応することを考えてあります。","id":"exchange-021"},{"speaker":"南委員","kind":"確認","question":"だからこそ質問するのですけれども、個人番号がわかるような、そういう仕事内容になっているのですか。安心感というところも含めて、やはり区のしっかりした、何のための取扱者登録なのかと思うので、その点について確認したいです。","respondent":"井浦戸籍住民課長","answer":"民間事業者による委託の部分につきましても、法律で規定されておりまして、職員と同様の守秘義務のもとに適正に取り扱っているところです。","id":"exchange-022"},{"speaker":"南委員","kind":"意見","question":"私はこれは個人情報セキュリティを守るというふうに言いながら、そうではないのではないかというふうにすごく実感してけしからぬことだと思います。その点だけ言って終わりにしますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-023"},{"speaker":"たけうち委員","kind":"確認","question":"いわゆる区なり国の関係者が出向いていって説得するとか、そういうことはないということが１つ確認です。〔「６００円」と呼ぶ者あり〕。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-024"},{"speaker":"たけうち委員","kind":"質問","question":"１００％をやるには、日本全国ですから、結構な時間がかかってしまうと思うのです。この３点。","respondent":"井浦戸籍住民課長","answer":"受取拒否の方の対応ですが、通知カードがないと不便であるということであれば、再交付ということで対応するものです。既存の一般証明写真用の撮影機との２００円の差ですが、１点は、お見込みのとおりです。","id":"exchange-025"},{"speaker":"たけうち委員","kind":"質問","question":"その辺は、わかる範囲で結構なので、見通しはどうなのか尋ねました。","respondent":"井浦戸籍住民課長","answer":"委員がご指摘のとおり、国の予算措置の中ですので、国からは、将来的なものについては示されてございませんが、国が説明で標準的にＱ＆Ａで申し上げているところにつきましては、現在、無料ですので、どうぞ申請なさってくださいというスタンスです。","id":"exchange-026"},{"speaker":"田中委員","kind":"質問・要望","question":"現状などを教えていただきたいことと、あと、このときもＤＶ被害加害者の情報はどう対応していくのでしょうか。ＤＶの加害者の方の追及は本当にすごいので、ちゃんと委託業者の方たちは、その情報を共有できているのかということとかを尋ねました。","respondent":"井浦戸籍住民課長","answer":"他区で例がありますが、番号の変更の申請をご案内いたしまして、番号変更という形で対応するということで考えてあります。２点目のＤＶ被害者への対応状況ですが、６３人、４５世帯の方に対応したところです。","id":"exchange-027"},{"speaker":"田中委員","kind":"確認","question":"確認なのですけれども、委託業者の方は、ＤＶ被害者、加害者の方がみえられた場合とか、そういう関係の場合には対応しないということですか。ＤＶ担当の方が担当する。","respondent":"井浦戸籍住民課長","answer":"法律的には、民間委託の方でも対応は事務的にできますが、品川区としましては、ＤＶの専属班がお聞きする、橋渡しをしていただくということで考えてあります。","id":"exchange-028"},{"speaker":"藤原委員","kind":"質問・要望","question":"全ての方にちゃんと届けていただきたいという思いで質問しますが、この方たちに対しては、１,２１９件が全部引越しされているのですね。数字的には、１,２１９件あて所なしで戻ってきて、イコール１,２１９件の方は全員が引越しされているということで間違いなのか尋ねました。","respondent":"井浦戸籍住民課長","answer":"そのとおりです。１,２１９件すべてについて、新しい住所地について国に住所情報を送付しまして、改めて国から通知カードが送られることになってあります。","id":"exchange-029"},{"speaker":"松永委員","kind":"質問・要望","question":"確認をさせていただきたいのですけれども、第二庁舎の臨時交付窓口という開設で、これはいつまでやられるのか。確認したいと求めました。","respondent":"井浦戸籍住民課長","answer":"臨時交付窓口ですが、平成２８年１月から３月末まで開設いたしまして、４月以降につきましては、現在、開設する方向で予算当局に提案しています。開設時間につきましては、区の営業時間と同じでございまして、８時半から１７時１５分、日曜日も開設する予定です。","id":"exchange-030"}]},{"id":"topic-04","title":"都市型観光プランの策定","agenda":"都市型観光プランの策定","exchanges":[{"speaker":"田中委員","kind":"質問","question":"３枚目の２－３、今後のしながわ観光の課題に書かれている区民による“もてなし力”の向上のおもてなし力について具体的に説明を求めました。","respondent":"間部文化観光課長","answer":"先ほど、いわゆるおもてなしということは何かと言ったときに、このまちに来られた方が気持ちよく過ごしていただくことということで捉えております。免税の一括カウンターも含めてですけれども、外国人の方であれば、そういうような環境が整っているようなことを認識しています。","id":"exchange-031"},{"speaker":"田中委員","kind":"質問","question":"今の一括のものだとものではないですか。ここに書かれているのは区民による“もてなし力”の向上なので、区民がやるもてなし力とは一体何なのかということを説明するよう求めました。","respondent":"間部文化観光課長","answer":"これは日本人、外国人問わずなのですけれども、いいところをご案内していただく。ここでは６月にお祭りがありますよというご案内とともに、例えば、そういうようなちょっとした案内をしていただくということで考えているところです。","id":"exchange-032"},{"speaker":"たけうち委員","kind":"質問","question":"こんなことがと、我々がちょっと気付かないような、こんなものが「えっ」というようなことをもしかしたら発見されるのかなと。日常生活というのですか、そしてそれをどう載せていくのか、もしくは何かやられたのかということを説明するよう求めました。","respondent":"間部文化観光課長","answer":"外国人の目線での検討ということだと思いますけれども、検討委員会を含めて、これもインバウンド関係に携わっている方が入っていただいております。お声を取り入れて行っているですので、直接的ではありませんけれども、間接的にはお聞きしているです。","id":"exchange-033"},{"speaker":"たけうち委員","kind":"質問・要望","question":"今後の要望ですけれども、この間、山北町へ行ったときにも、山北町の担当者がおっしゃっていたと思うのです。まち歩きの中で活かされていくようなことも期待したいと思うので、ぜひそういう面も入れていただければと思う。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-034"},{"speaker":"南委員","kind":"質問・要望","question":"自治体ですから、仕分けというのですか、教えていただきたいと思っています。庁内で１１課にヒアリングをして、２９団体に聞き取りをしているという、その辺についても考え方を伺いたいと思います。","respondent":"間部文化観光課長","answer":"４カ国語でつくっていますけれども、今後も観光客の動向を見ながら、いろいろな多言語に広げていきたいというふうに考えております。浅草でもいろいろなグッズが売られていますので、そういう面では、１つでも２つでも発掘ができるように努力していきたいと思っています。","id":"exchange-035"},{"speaker":"藤原委員","kind":"質問・要望","question":"そういう意味で質問させていただきたいのですけれども、私もそのとおりだと思うのですけれども、品川区はまず商店街です。と出ていたのですけれども、この都市観光と人口増加、住んでいる方の増加をどういうふうに考えているか、まず教えていただけますか。","respondent":"間部文化観光課長","answer":"都市型観光と人口の件ですけれども、やはり品川区に魅力があるから人口が増えている、これは１つあると思います。買い物等、交通も便利だということで評価されて、私は増えているものだと思っています。","id":"exchange-036"},{"speaker":"藤原委員","kind":"質問・要望","question":"保育園はどうする、待機児童はどうするのかというものも出まして、今向かっているわけではないですか。このプラン策定には入れていただきたいと思う、さっきおっしゃっていたけれども、その辺について尋ねました。","respondent":"間部文化観光課長","answer":"そういうものを開発することによって、そこで起業される方なども増えていくと、品川区が元気になるのは間違いがないと考えています。気持ちだとか、そういった部分も含めて観光という観点ではレガシーと捉えて活用していきたい、このように考えてあります。","id":"exchange-037"},{"speaker":"渡辺委員","kind":"提案","question":"ですから、責任だとか、リーダーシップのところでの見解も大前提として地域の方が主役であるという点から確認をさせてほしいと求めました。あるいは施策が出てきたときに理念としてあるべきかと思うのですが、その辺、お話を伺えればと思いますとの意見を述べました。","respondent":"間部文化観光課長","answer":"当然、私たちも当然リーダーシップを発揮していかなければいけないですし、その根拠となるのがこういうプランなのかというふうに認識をしています。パブリックコメントも含めて、いろいろな方の意見を取り入れてつくっていきたい、このように考えているところです。","id":"exchange-038"},{"speaker":"渡辺委員","kind":"質問","question":"今、行政の役割と理念のところを伺いました。ちょっと抽象的になってしまいますが、この辺のご決意だけ最後に、行政がリーダーシップかなという思いがあったので尋ねました。","respondent":"間部文化観光課長","answer":"まさに私も広域連携は重要だと思っています。いろいろな形で広域連携を図っていくことが活発化の機運を高める上でも重要だと思っていますので、できる限りの連携はしていきたいと思います。","id":"exchange-039"},{"speaker":"渡部副委員長","kind":"質問・要望","question":"早急に私たち区民委員会のメンバーにも素案を提出いただけますでしょうかという要望と、先に目を通したいという要望がありますので、お願いします。第４回があって、３月にはもう策定されるということですので、いかがか尋ねました。","respondent":"間部文化観光課長","answer":"今、委員からお話がありました閉会中の対応につきましては、正副と協議して決めていきたいと思います。","id":"exchange-040"}]},{"id":"topic-05","title":"しながわみやげコンペティション","agenda":"しながわみやげコンペティション","exchanges":[{"speaker":"南委員","kind":"意見","question":"ほかの商店街や、あるいは地域のお店の方々のコンペティションに対する認識が、その辺どういうふうに見たらいいのかと。その辺、どういうふうに見たらいいのか、あったらお話しくださいとの意見を述べました。","respondent":"間部文化観光課長","answer":"従来からこういうおみやげ物を取り扱うことが多いということと、やっぱりガイドの推薦で申請がかなり多かったということであります。自らというよりは、ガイドの推薦などがかなり今回は多かったということで、ちょっと偏りがあったのかなと思います。","id":"exchange-041"},{"speaker":"南委員","kind":"質問・要望","question":"日常的につくっておられて販売をしている、どこも大体そういうことで、うちの目玉商品みたいなことでエントリーされるのか。大変恐縮なのですけれども、初歩的なところを教えていただきたいのですが、そこも含めて教えてほしいと求めました。","respondent":"間部文化観光課長","answer":"１４人ほど審査員がいたのですが、全てで１位ということで、かなりいいなという形でありました。〔「今日、持ってきていないの」と呼ぶ者あり〕 やはりここに載ることによって、いろいろなＰＲ効果があります。ここに来たらこんなおみやげかあるというような取り上げ方を私たちもしていこうと思っていますので、そのような効果があるかと思います。","id":"exchange-042"},{"speaker":"たけうち委員","kind":"質問","question":"そういうふうにして販売することについてはオーケーかどうかということと、その他の(2)番で、どんなことを考えているのか尋ねました。","respondent":"間部文化観光課長","answer":"新たな認定制度ということで、今回こういう形で３年分の６８点が載ったものをつくっていくのですけれども、お店がなくなったものなどがあります。","id":"exchange-043"},{"speaker":"たけうち委員","kind":"確認","question":"わかりました。非常にそれはいいことだと思うのですけれども、そこの整理といいますか、考え方の整理という部分をもう１回確認したい。","respondent":"間部文化観光課長","answer":"観光協会を通じて、審査員の方も据えて、適正な手続をもって応援しているということでやっているところです。これも１つの観光資源ということで、観光振興の一助になればという思いでやっておりますので、今後ともその理念でやっていきたいと思います。","id":"exchange-044"},{"speaker":"渡辺委員","kind":"質問","question":"１個拠点をつくることで、今後こういうランク付けとか、一歩興味関心を引く仕掛けというのは大いにされるべきだと思うのです。その辺は大胆にチャレンジ精神をもってされるべきと思いますので、決意だけ伺えればと思います。","respondent":"間部文化観光課長","answer":"このおみやげも含めて観光行政、やる気のある事業者を支援していくのはとても大事だと思いますので、そういう視点で今後とも一生懸命やっていきたいと思います。","id":"exchange-045"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/878133?Template=document&Id=2740#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=6&TermStart=2015-01-01&TermEnd=2015-12-31"}],"sourceMeta":{"pages":0,"characters":47615,"voices":126}},{"id":"h27-20151201-7","meetingId":"h27-cm12","date":"2015年12月1日","dateIso":"2015-12-01","committee":"厚生委員会","time":"午前１０時００分～午後 ０時１６分","status":"正式会議録","sourceType":"formal","overview":"厚生委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を38件整理しています。","topics":[{"id":"topic-01","title":"の(1)、（仮称）品川区立障害児者総合支援施設の建設","agenda":"の(1)、（仮称）品川区立障害児者総合支援施設の建設","exchanges":[{"speaker":"いながわ委員","kind":"質問","question":"何点かお伺いしたいことがあるのですけれども、このレジュメの１の(2)、ここだけなのですか。でき上がっていないからどういうものができるのか、非常に暗さを連想させてしまう診療室がそこにあるというのはどうなのか、その辺を説明するよう求めました。","respondent":"中山障害者福祉課長","answer":"そういうようなことも考えていきたいと思っていますが、そうしたところを、出られるようなスペースとして活用してまいりたいと思っています。逆に、あまり日差しが強いよりも、少し落ち着いた雰囲気になるのではないかと考えているところです。","id":"exchange-001"},{"speaker":"いながわ委員","kind":"質問・要望","question":"では中を見てみようといったときに、その辺はしっかりと打ち合わせや、工期途中でチェックをしていくなどをやってほしいと求めました。やはり地域の都市景観に合ったような建物になるように、しっかりやってほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-002"},{"speaker":"新妻委員","kind":"質問・要望","question":"前回から少しこの設計が変わったということで、この間、利用者、また各種団体の方への説明などもあったと思いますが、各種団体の方へのご説明がどのようにされてきたのかという流れと、今後、これがどのような形で利用者に説明がされていくのかということを、確認をさせてほしいと求めました。","respondent":"中山障害者福祉課長","answer":"それから、９月７日、地元の町会を対象とした説明会を行いました。１１月５日に保護者向けの説明会ということで、この間、開催してきております。","id":"exchange-003"},{"speaker":"新妻委員","kind":"質問・要望","question":"今後また、そのような説明会は随時行われていきますでしょうか。利用される障害のある方、またその保護者への説明を丁寧に行ってほしいと求めましたが、いかがか尋ねました。","respondent":"中山障害者福祉課長","answer":"すみませんでした、答弁漏れでした。１０月２８日に行いました説明会の中でも、説明をしてほしいという声はございましたので、また対象を広げた説明会をしていきたいと考えています。","id":"exchange-004"},{"speaker":"のだて委員","kind":"提案","question":"がらっといろいろ変わっているので、それについてどういうふうに変えたのかということを、もう少し詳しくご説明ほしいと求めました。提案者も、その辺の考えなどがどういうふうに変わったのかということを、教えてほしいと求めました。","respondent":"中山障害者福祉課長","answer":"心地よさや、障害のある方がここに通って落ち着くような空間づくりを考えたときに、このような形になってきたところです。区からの要望も含めて取り入れてもらい、今、こうしたところで落ち着いているところです。","id":"exchange-005"},{"speaker":"のだて委員","kind":"質問","question":"詳しくお聞きしたいのですけれども、今回の設計では見当たらないのですけれども、その辺がどうなったのか。それから、在宅介護支援センターというのは、お年寄り対象ということなのか尋ねました。","respondent":"中山障害者福祉課長","answer":"障害者も、今後、６５歳以上になると、介護保険に移られる方もいらっしゃいますし、障害者の高齢化は一つ大きな課題となっております。同じスペースに入ることで、双方の連携が進んでいけばと考えているところです。","id":"exchange-006"},{"speaker":"のだて委員","kind":"質問・要望","question":"それから、３階で、個室とグループ部屋があるのですけれども、この階には、個室は何部屋あるのかの確認です。設備とか、機械のスペースなのかもしれませんが、確認です。","respondent":"中山障害者福祉課長","answer":"３階のグループ部屋と個室ですけれども、ここは児童の発達支援センターということで、療育に通ってくる子どもの療育の場ということになります。","id":"exchange-007"},{"speaker":"のだて委員","kind":"確認","question":"主なところだけ書いてあるということですけれども、そうすると、個室と書いてある数だけ個室があると考えてよろしいのかという確認です。６階に全体の管理事務所が置かれているのですけれども、全体を管理するうえで６階に持ってきたというところを、少しお聞かせほしいと求めました。","respondent":"中山障害者福祉課長","answer":"全体管理室を６階に持ってきたことは、２４時間利用者がいるところが４階と５階になっているので、そこに近いということ。上にいくほど床面積が狭くなるということがありますので、そういった全体の調整の中で、６階に職員のリビングルームを移させていただいたところです。","id":"exchange-008"},{"speaker":"のだて委員","kind":"意見","question":"スケジュールですけれども、設計に時間がかかるということで、開設が平成３１年４月まで延びたということですけれども、当初の設計期間よりも、やはり障害者の綿密な設計をするために時間が延びたのか、もう少し詳しくお聞かせほしいと求めました。","respondent":"中山障害者福祉課長","answer":"当初の予定では、今年度中に実施設計までできるのではないかと、こちらとしては考えていたところではあります。ものによっては２年近く、そういったことを考えると、当初の障害者福祉課の考えが甘かったかとは思っているところです。","id":"exchange-009"},{"speaker":"のだて委員","kind":"質問・要望","question":"利用される方も、これだけ総合的に利用できるところが、地域の拠点としてできるということは、大変に喜んでいることだと思いますので、これ以上延びることがないように、できるだけ早く開設できるようにやっていってほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-010"},{"speaker":"石田（秀）委員","kind":"提案","question":"提案者と、先日、約５０億円くらいのところがありました。ぜひ、そこら辺の心配をよく提案者の方ともお話をしていただいて、詰めていただければと考えていますとの意見を述べました。","respondent":"中山障害者福祉課長","answer":"ＲＣ造にいく可能性もあるということで、施設整備課とも、この間話をしてきたところです。先行きのことで、とにかく平成３１年４月オープンがずれることがないように、精いっぱい努力していきたいと考えています。","id":"exchange-011"},{"speaker":"若林委員","kind":"質問","question":"もう一つ、ここは海抜があまり高くないところですよね、２ｍないくらいですか。立会川の水門が２.６１ｍでしたか、この３点くらい、お願いします。","respondent":"中山障害者福祉課長","answer":"区立の障害者施設ということになりますので、いざ災害が起こったときには、こちらは福祉避難所や二次避難所的な対応をとることになると思います。こうしたものは、これからまた考えていって、開設までにはしっかりとした計画もつくっていければと考えています。","id":"exchange-012"},{"speaker":"若林委員","kind":"質問・要望","question":"２点目のお互いの理解については、私たちは会派として全員で伺って、説明も伺いました。私は２回見させていただいて、ぜひ最大限に活用してほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-013"}]},{"id":"topic-02","title":"の(2)、大崎高齢者多世代交流支援施設の運営事業者の公募","agenda":"の(2)、大崎高齢者多世代交流支援施設の運営事業者の公募","exchanges":[{"speaker":"のだて委員","kind":"確認","question":"どういうものになるのか、お聞きしたいのですけれども、株式会社でもいいのかということです。基本的に設計とかかわって決めてきたと思いますけれども、この施設については、そういった設計とのかかわり方はないのかという確認です。","respondent":"松山高齢者地域支援課長","answer":"ご質問の１点目です。２点目の、一部のソフトの運営の業務内容につきまして運営事業者の公募を行いまして、そちらの公募で選定された事業者に委託をするものです。","id":"exchange-014"},{"speaker":"のだて委員","kind":"意見","question":"株式会社がやっていくということになると、継続的なサービスを行っていくという意味では、株式会社にするというのはよくないと考えています。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-015"},{"speaker":"横山委員","kind":"提案","question":"１点だけ、お伺いします。具体的な提案は事業者からということがあると思いますけれども、どのようにお考えなのか、説明を求めました。","respondent":"松山高齢者地域支援課長","answer":"業務内容の、高齢者を含む多世代交流に関する業務ですけれども、区といたしましては、継続的に交流を行うようなイベントや講座を、例えば何回以上実施するというような形を委託してまいりたいと考えております。","id":"exchange-016"},{"speaker":"横山委員","kind":"意見","question":"区としての具体的なそういったサービスの回数ですとか、こういった形で、というお答えを、今、いただきました。その辺の意味だったのですけれども、申しわけありません、もう一度お願いいたしますとの意見を述べました。","respondent":"松山高齢者地域支援課長","answer":"そちらの施設内で発信できれば、それが地域に広がっていくというような考え方は、区全体としては持っております。地域の特性というものもありますので、それに合った多世代交流の仕方というものは、それぞれがつくっていくものだと考えております。","id":"exchange-017"},{"speaker":"横山委員","kind":"質問","question":"地域の特性に合わせてということで、平塚橋のほうは、子どもと高齢者が集えるようなオープンスペースなどのお話を、以前いただいたと思います。大崎に関しては、地域特性を、どのように捉えていらっしゃるのか尋ねました。","respondent":"松山高齢者地域支援課長","answer":"大崎も、平塚橋と同様に、地域交流スペースは、当然設けております。地域のご利用される団体の皆様のご意見をいただきながら、今後、つくっていくという形にしていきたいと考えています。","id":"exchange-018"},{"speaker":"石田（秀）委員","kind":"提案","question":"教えていただきたいのですが、多世代交流に関する業務というのは、多分いろいろ提案をしてくださいということだと思います。こういうことをやりたいと、プロポーザルでそういう提案まで求めているのか、どうなのかということを教えていただきたいとの意見を述べました。","respondent":"松山高齢者地域支援課長","answer":"こちらのほうとしては、参加費の具体的なところまでは、区としては求めてはおりませんが、基本的な条件や料金設定は区が考えるべきであるとして、委託なので、許可や利用条件は区のほうで考えていきたいと考えています。","id":"exchange-019"},{"speaker":"石田（秀）委員","kind":"提案","question":"それを一つ提案してもらうことによって、どういうふうに大きくしていくかということも、それは提案をしていただく中でやったほうがいいと思うのです。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-020"}]},{"id":"topic-03","title":"本日は、地域包括ケアシステムのうち、医療と介護の連携","agenda":"本日は、地域包括ケアシステムのうち、医療と介護の連携","exchanges":[{"speaker":"新妻委員","kind":"質問・要望","question":"患者が救急車で運ばれた際、ご本人の身元の確認できるというお話があったのですが、ここをもう少し詳しく教えてほしいと求めました。どういうシステムになっていて、情報がわかるのかという確認をさせてほしいと求めました、お願いいたします。","respondent":"川島健康課長、永尾高齢者福祉課長","answer":"診療科目は何かといったようなお問い合わせに対して、医者を紹介して、ぜひかかりつけ医として活用していただきたいという事業の内容になります。それから、患者情報の共有につきましては… 品川区の特色である在宅介護支援システムということで、在宅介護支援センターのほうの相談内容と区のワーカーのほうの相談内容が全部つながっているというところから、すぐに身元等もわかるという状況になっております。","id":"exchange-021"},{"speaker":"横山委員","kind":"質問","question":"何点かお伺いします。そちらからお願いします。","respondent":"川島健康課長","answer":"例えば港区との連携は、検討会の中では、これから進めていかなければならない課題だと考えています。すばらしい取り組みだと思っているのですが、そういった話の持ちかけも、まだこれからの課題とさせていただきたいと思います。","id":"exchange-022"},{"speaker":"横山委員","kind":"質問","question":"近隣区へのシステムの拡大というところは、これから検討されているということでお伺いいたしました。モデル実施の部分に関しましては、まずは品川区内でスタートされるということで、順次他区にも持ちかけていくということなのか尋ねました。","respondent":"川島健康課長","answer":"区内の病院と診療所で幾つかでやって、それを区内全域に広げてから、周りに広めていくような形を、今、描いているところです。一堂に会していろいろな説明会などはあるのですが、やはり大田区と品川区という括りで、東京都のほうが捉えているところが多い現状です。","id":"exchange-023"},{"speaker":"横山委員","kind":"質問・要望","question":"こちらは、要望だけします。細かいところはワーキンググループで行っていきたいというご要望なども出ているというお話でしたけれども、今後、どのようにお考えか尋ねました。","respondent":"川島健康課長","answer":"今までの取り組みは、今おっしゃったような研修会のようなものを開催する必要性は、当然あると考えております。既に独自にいろいろな機関のほうでも検討を始めていると聞いておりますので、この検討部会の中、団体連絡会の中で検討を続けているものです。","id":"exchange-024"},{"speaker":"横山委員","kind":"質問・要望","question":"さまざまな多職種の方に見える化といいますか、情報提供していくというリーダーシップを発揮していただけたらと考えています。要望で終わらせていただきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-025"},{"speaker":"のだて委員","kind":"質問・要望","question":"現場の声や課題、もう少し詳しく語れるところあれば、教えてほしいと求めました。それとあわせて、区の考えている課題となっている部分、これも教えてほしいと求めました。","respondent":"川島健康課長","answer":"「訪問介護ステーションで２４時間対応をしているところ、それから薬局で２４時間対応をしているところはどこか知りたい」という話です。先ほどの５、区の今後の目標のこの三つに尽きると思いますので、こちらを目指してやっていきたいと考えています。","id":"exchange-026"},{"speaker":"のだて委員","kind":"質問・要望","question":"この会議体等でも、どうまとめていくかという話をされていると思いますけれども、しっかりと連携を取ってやっていってほしいと求めました。これはどういう形で減っていくことになるのか、イメージができなかったので、ご説明ほしいと求めました。","respondent":"川島健康課長","answer":"例えば、ご自身も病院、診療所にかかられたとき、初診のときに、いろいろ聞き取りに時間がかかったりとか、待ち時間が多かったりすると思いますが、例えばご自身の情報を持って病院などにかかられたら、初診の時間が迅速に済むといった意味合いです。","id":"exchange-027"},{"speaker":"のだて委員","kind":"質問","question":"その中で、そういったところで、この会議体の中でどういったお話がされたかということ。それから、区が在宅医療全てを行っていくことがいいのかという、区の考えをお聞きしたいと思います。","respondent":"川島健康課長","answer":"在宅診療ありきというのが区の姿勢ということではなくて、現状、増えてきている中で、どう対処するかという課題の検討を、今、しているという認識です。","id":"exchange-028"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"現場の会議の中でも、そういう意見は出ているのかどうか、聞かせいただきたい。それから医療の現場の実態の声、そこら辺のところを、もう少しリアルな形でお知らせいただけたらと思っています。","respondent":"川島健康課長","answer":"区でどのような形で支援できるか、どうしていくかということは、少し難しい課題かと考えています。今、おっしゃっていた在宅療養を支援する仕組みというのも、形としてはあるのですが、あまり機能していない状況にあるのかと考えています。","id":"exchange-029"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"本当に行き場所がなくて、一日２万円で１カ月６０万円というような差額ベッドが当たり前という、そんな状況になっています。そこら辺のところは、区のほうからも厚生労働省なりに、声として挙げていただきたいと思っています。","respondent":"川島健康課長","answer":"さまざま検討する中で、現実的に課題として感じている部分をしっかり吸い上げて、施策に反映させていただきたいと考えております。課題を抽出しまして、それをしっかり検討して、よりよい地域医療ができるような形を実現させていきたいと考えております。","id":"exchange-030"},{"speaker":"石田（秀）委員","kind":"質問","question":"介護認定の会議は週１回くらいやっているのでしょうか、毎日ですか、それくらい人がいるということではないですか。そういう方をどういうふうにしていくのかというと、会議体の数もどこで情報を取るかといったら、そういう数も出てくるわけではないか尋ねました。","respondent":"川島健康課長","answer":"例えば柏市のほうが、そういった先進自治体の取り組みもいろいろと勉強して、よりよいものにしていきたいと考えております。ケアの仕方を、そういったものも見ながら、よりよい地域包括ケアシステムの構築に結びつくかということを研究させていただきたいと考えております。","id":"exchange-031"},{"speaker":"石田（秀）委員","kind":"質問","question":"５年生存されたらこれくらいとか、１０年このままだったらこのくらいとか、そういういろいろなパターンがある。そういうパターン分けのようなものは、もうできているのか尋ねました。","respondent":"川島健康課長","answer":"今の、いわゆる人それぞれのライフサイクルというか、パターン分けという部分、そこまで厳密にできているわけではないところです。地域包括ケアシステムだというようなお考えのお話もお聞きしますので、分類して種分けするのはなかなか難しいような課題かと考えています。","id":"exchange-032"},{"speaker":"石田（秀）委員","kind":"質問","question":"行政が全部把握できないとなると、そういうものをお願いしてやってもらうことになるわけではないですか。そこら辺の強化については、これは区からも強く言っていいような気がしますけれども、そこら辺はどうお考えなのか尋ねました。","respondent":"川島健康課長","answer":"それぞれの職員や医者自身のレベルアップの取り組みは、勉強会を開催したり、そういった部分でパワーアップを促していくような取り組みをしていきたいと考えております。","id":"exchange-033"},{"speaker":"石田（秀）委員","kind":"質問","question":"もう１点、こうなったらきてほしいと言われているけれども、大分聞きます。そして、伺うと、開業医であっても、全体を含めると、８割くらいは品川区にいないと。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-034"},{"speaker":"いながわ委員","kind":"質問・要望","question":"品川区の地域医療連携の今後の予定の中の、地域医療資源検索システム導入とあります。これは積極的にどんどん進めていただきたいのですが、いろいろな部分を落としていくものなのか、システム的なことを説明するよう求めました。","respondent":"川島健康課長","answer":"このシステムは、インターネットに接続できる環境でしたら、パスワードとログインＩＤを入力して参照できるような形のものになります。ですので、情報の範囲は限られるのですけれども、インターネット接続できる環境があれば使えるというものになります。","id":"exchange-035"},{"speaker":"いながわ委員","kind":"意見","question":"これに関しても、やはりホットスポットがあるみたいですね、何ｍ円というのか。いいのではないかと思うのですが、まだこれからなのでわからないと思うのですけれども、何かあればお願いしますとの意見を述べました。","respondent":"川島健康課長","answer":"それを考えていて、医師会のほうでも、どの地図を使えばいいかということを、今、検討しているように聞いております。全て反映できるわけではありませんけれども、よりよいものにしたいと考えていますので、ご意見をいただければと思います。","id":"exchange-036"},{"speaker":"若林委員","kind":"質問・要望","question":"最終的に、先ほどの行政視察を踏まえてという見解が、いながわ委員からもありましたが、ぜひそれを検討してほしいと求めました。認知症のところで新妻委員のご質問にも、どういうふうに思われているのか、お聞きしたいと思います。","respondent":"川島健康課長、永尾高齢者福祉課長","answer":"私の説明が少し足りなかったかもしれないのですけれども、今の医療資源検索システムのもとになる医療連携関係機関名簿というものがありましたが、介護の方にも活用していただけるようにしていきたいと考えております。 介護の側の連携ができ上がって、そことドッキングできることを、将来的には考えています。多職種連携の今一番課題ですので、その連携の会議等の中で、考えているところです。","id":"exchange-037"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"よくご存じのように、２４時間訪問介護事業者でやるとなると、看護師を雇用しなければならないではないですか。会議の中で議題にも挙げていただきたいし、２４時間訪問介護なども含めた介護と医療の連携を考えていらっしゃるとか、教えていただきたい。","respondent":"永尾高齢者福祉課長","answer":"国のほうでも、そこを一体的にしようということで、今、報酬改訂の時期などを一致させようということで動いています。国の包括ケアシステムの構築での検討の推移なども見ながら、国からおりてきたら、これから検討していかなければいけないかと考えています。","id":"exchange-038"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/841532?Template=document&Id=3434#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=7&TermStart=2015-01-01&TermEnd=2015-12-31"}],"sourceMeta":{"pages":0,"characters":40480,"voices":96}},{"id":"h27-20151201-8","meetingId":"h27-cm12","date":"2015年12月1日","dateIso":"2015-12-01","committee":"建設委員会","time":"午前１０時００分～午後 ２時４３分","status":"正式会議録","sourceType":"formal","overview":"建設委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を71件整理しています。","topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"地球温暖化防止の対策は、世界中で今、大事な重要事項になっているわけですけれども、目的というところで、「品川区内の環境に関する取り組みを広くＰＲし」とありますけれども、特に品川区として一番ＰＲしたい点というのはどんな点なのか、もう少し詳しく伺えればと思います。","respondent":"三ツ橋環境課長","answer":"今回、先ほどパネル展示を３テーマと申し上げましたけれども、こちらのパネル展示におきまして、ＰＲしたい点と考えております。以上です。","id":"exchange-001"},{"speaker":"安藤委員","kind":"質問","question":"もう少しパネル展示３テーマというところで、特にこういったところを品川区で取り組んでいるということをＰＲしたいというようなところがありましたら、もう少し教えてほしいと求めました。","respondent":"三ツ橋環境課長","answer":"今回、３テーマにつきましては、しながわエコリンクが、今年度から品川区として実施いたしました環境マネジメントシステムについてのご紹介です。それと、エコ・クッキングの選手権について説明をしております。","id":"exchange-002"},{"speaker":"安藤委員","kind":"質問・要望","question":"ちょっと関連してお伺いしますけれども、例えば野球の方とかいらっしゃるかもしれないのですけれども、そちらはどういう団体を考えているのか。説明会をやるということでしたけれども、そこへの周知方法や説明会の対象に、そういった関係団体の方がなっているのか、伺います。","respondent":"多並公園課長","answer":"より丁寧な工事の進め方を周知する必要があるだろうということで、実際の段取りを踏まえて、地元にご説明をする形になります。計画のスケジュールを説明させていただいた後に、今のような形でご説明するということで、より丁寧な説明をする観点で。","id":"exchange-003"},{"speaker":"安藤委員","kind":"確認","question":"ちょっと確認なのですが、ご案内することになっているのか、ちょっとそこだけ確認させてください。これに関して、問題ないのかどうかというのは、問題ないと思うのですけれども、それをちょっと改めて確認したいと求めました。","respondent":"多並公園課長","answer":"団体の方々が説明会の対象か、もちろん説明会の対象ですけれども、お話しに行くこととなります。今後は汚染されている物質を全て取り除いて、整備する形になりますので、安全なご利用の形態になるものです。","id":"exchange-004"},{"speaker":"安藤委員","kind":"質問・要望","question":"そういった代用のトイレということも合わせて、設置も要望してきたのですけれども、そういったトイレの計画について伺いたいと思います。そういった要望をしたいのですが、計画はあるのか尋ねました。","respondent":"多並公園課長","answer":"より皆様がご利用いただけるようにフラット化について鋭意検討して、今後検討を進めていきたいという内容が、ここに示すものです。新たに設置していく予定で、仮設トイレを考えておりまして、一定の期間仮設トイレでいきたいです。","id":"exchange-005"},{"speaker":"安藤委員","kind":"確認","question":"それとちょっと幾つか確認なのですが、現状ではないと伺っているので、きちんと給水所になるわけですから。フラット化しつつも水槽は残していくみたいな、そういう話で、今捉えたのですが、それでいいのでしょうかということをお伺いします。","respondent":"多並公園課長","answer":"もちろん最終的にこの西大井広場を計画する際に、マンホールトイレと言われているものもバックアップのためにつくっていきたいと考えています。検討しておりまして、こういう広場としてお使いできるような形にしたいというのが、今の考えです。","id":"exchange-006"},{"speaker":"西本委員","kind":"確認","question":"水はけのいいものにかえられるのでしょうかということ。それから、裏面のほうで見ると、この改修するというのは、どの辺まで言っているのか尋ねました。","respondent":"多並公園課長","answer":"この北側の、この立会通りを挟んだ北側の部分が３０年度という形で、この広場については順次改修をしていきたいと考えているところです。","id":"exchange-007"},{"speaker":"西本委員","kind":"質問・要望","question":"利便性の高いように、結構老朽化が進んでいるので、この際いろいろ改修をしていただきたいというふうに思っております。そうすると、一般のご利用の方との住み分けとかというのは、もっとできるようになっているのか尋ねました。","respondent":"多並公園課長","answer":"今保育課で予定しているのがあって、屋外遊技場として設定、指定したいということで聞いております。利用団体の方とよくお話ししながら、そこの西大井広場の新たな利用の仕方については、一緒に考えていく形になるかと思います。","id":"exchange-008"},{"speaker":"西本委員","kind":"意見","question":"具体的に使うとなったときには、住み分けがきっちりとできていないと、やはりトラブルのもとになってしまうと思うのです。１２月１４日でやると思うのですけれども、子供たちがどういうふうに遊ぶのとか、その件についてとの意見を述べました。","respondent":"多並公園課長","answer":"保育部門とよく連携しながら、もちろんしっかり考えながら、進めて行きたいと思っているところです。","id":"exchange-009"},{"speaker":"筒井委員","kind":"質問・要望","question":"お子さまも使われることですし、あと水にも影響が出ないように、この鉛の除去の工事は、しっかりと進めていただきたいと考えています。水銀とか検出されたと思うのですけれども、この西大井広場公園は、もともと何に使われていたのか尋ねました。","respondent":"多並公園課長","answer":"その後、会社の名前が変更していって、現在の名前で言うと三菱重工が、ずっと昭和４７年までお持ちで、工場がもともとありました。その後に、昭和４７年に東京都がその三菱重工から土地を買いまして、その後５３年に品川区が土地を買って、現在に至るです。","id":"exchange-010"},{"speaker":"筒井委員","kind":"質問","question":"品川区には、そういった場所、どのぐらいあるのでしょうか。特に工場の跡地だったと思いますが。","respondent":"三ツ橋環境課長","answer":"３,０００平米以上ですと、今の現段階ではできませんので、よろしくお願いいたします。","id":"exchange-011"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"これは要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-012"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"管理するそこの段階で公園課としての要望というのは、そういうのは、ある程度。そこを最小限に抑えられるような、公園課としてのそれに対しての要望を必ず入れておいてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-013"},{"speaker":"つる委員","kind":"確認","question":"先ほどの鉛のところなのですけれども、ちょっと前回、ご報告いただいたときに確認していなくて。一応念のための確認で、そういう認識でいいかどうか、確認したいと求めました。","respondent":"多並公園課長","answer":"それがまず地歴の話です。委員のお話のとおり、おのおの舗装をしていますので、これからもしっかり管理をすることが重要だというところと考えているところです。","id":"exchange-014"},{"speaker":"安藤委員","kind":"質問","question":"具体的に何を想定しているのでしょうか、救護所とかなのでしょうか、お伺いします。そういったルールはどうなるのかとか、ボール使用などのルールなどは、どういうふうなお考えなのかというのをお伺いいたします。","respondent":"多並公園課長","answer":"先ほども説明しましたが、そこに柱のような形で遊具を設置しておりまして、平常時は平常時の利用をしていただきながら。もともとのコンセプトをそういうふうにしておりまして、地元のご説明というのも、そういう形で説明しながら現在まで進めているところです。","id":"exchange-015"},{"speaker":"安藤委員","kind":"質問・要望","question":"ちょっと紹介していただきたいのと、今度また工事説明会が１７日にあるということなのですけれども、その対象者と周知方法についてもお伺いします。「ほかの愛犬家の方々と交流できる場とか、遊ばせる場というのがなかなかなくて、ちょっと残念だ」という話も伺っているのです。","respondent":"多並公園課長","answer":"今度１２月に行う説明会の件ですけれども、町会に回覧板という形で説明会の周知を図りながら、あと個別に。その地域での考え方とか流れがありますので、その状況に応じた対応というのが、私としては考えているところになります。","id":"exchange-016"},{"speaker":"安藤委員","kind":"質問・要望","question":"やはり並列でいったほうがいいと思うので、配付の範囲もぜひ教えていただきたいと考えていますが、そこら辺もお伺いします。どういう場面で、どういうルートで、そこら辺をちょっと１点伺いたいと思います。","respondent":"多並公園課長、鈴木（誠）防災課長、曽田災害対策担当部長兼危機管理担当部長","answer":"先ほどの近隣の方に約３００枚、３００戸に配付するような形で、今後もこのような形で進めていきたいと思うところです。今の私たちの考えとしては… 消防と自衛隊のヘリが中心になると思いますが、資材それから物資、それと人員の搬送というのが主な内容になるかというふうに考えています。… 第１師団の隷下部隊であります第１連隊の、品川では１中隊ですけれども、１中隊の部隊がこちらに来ると。","id":"exchange-017"},{"speaker":"筒井委員","kind":"質問","question":"公園ですから、どちらかというと重視した公園でいいのかという、この理解でよろしいのかということ。２カ所しかないのかと思うのですけれども、つながる入り口はどこなのかということを、以上３点お聞きしたいのですが。","respondent":"多並公園課長","answer":"Ｈマークですが、ここにちょっと今、抜けていましたけれども、入れる形で実際は入れてまいります。そういう考え方であります。","id":"exchange-018"},{"speaker":"筒井委員","kind":"質問","question":"では、基本的には１カ所、抜ける道は。下はこれ、一番下の道路は、道路として往来できるということか尋ねました。","respondent":"多並公園課長","answer":"これについても連携して進めていまして、今検討しているという、検討しています。これがつながりますと既存の中央公園のほうまでつながって、区役所のほうまでそのまま行けるという形を想定しています。","id":"exchange-019"},{"speaker":"西本委員","kind":"質問","question":"結構、遊ぶにも遊べない状況にまでなってしまっていたような気がするのですが、それの対策はどうされるのかということが１点。多分すごく中心的な大切な公園になるのではないかと、そういう関係づくりもしていいのではないかと思うのですが、いかがか尋ねました。","respondent":"多並公園課長、鈴木（誠）防災課長","answer":"整備の説明会のときにも、住民の方にいろいろご説明したのですけれども、その段差は利用する形でやりたいと。地下倉庫というのを考えたのと、整備内容も検討してきて、こういうものになったのです。近隣区も含めたエリアの拠点ということについてのお尋ねですが、既に東京都と自衛隊と２３区の防災課長会で、協議する会議体が設置されております。","id":"exchange-020"},{"speaker":"西本委員","kind":"質問・要望","question":"それは、どれだけ皆さまの要望があるのかというところの熱意の問題だと思うのですけれども、ちょっと聞く耳を持ってほしいというのがあるので。住民説明会のときに説明してほしいのですが、なぜこのヘリポートをつくって、こういう場所にあると。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-021"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"いい形でつくってほしいと求めました。せっかく緑をやったのに、ちょっと違う方向に行ってしまうと、その辺の考え方として、もう１回ちょっと聞きたいと思ったので。","respondent":"多並公園課長","answer":"説明会だけのご意見ではないですけれども、どういうふうにするかというのは、我々が最後決めなければいけないことと思います。ご懸念されたことについて、我々も十分承知した上の、今後の管理のあり方はもちろんしっかり検討していきたいと思っているところです。","id":"exchange-022"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"いい公園にしていただきたいと、その辺の管理も、その辺の管理もしっかりやってもらいたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-023"},{"speaker":"つる委員","kind":"確認","question":"細かいところで、ちょっと事前に確認できなかったので、先ほど質疑の中であった地下倉庫の位置が、ちょうどこの中央の四角破線のこのあたりでいいのかということを１つ説明を求めました。","respondent":"多並公園課長","answer":"破線のところは３００平米あるのですけれども、あと１００平米ほど、合わせて４００平米の地下と地上を合わせた倉庫になると。三角形の印が２つ書いてありますけれども、そういう位置、配置になっているところです。","id":"exchange-024"},{"speaker":"つる委員","kind":"質問・要望","question":"そうすると、少し注意的なことで言うと、逆にスロープ状というか、段差みたいになっているのですか。当然、形状のあれがあると思うのですけれども、もしそういうのがあるのだったら、それをちょっと説明を求めました。","respondent":"多並公園課長","answer":"遊べるような形状になっていると、逆にこういう形状を利用した整備内容としたのが、先ほどの説明です。ヘリコプターが下りてくる方向をいろいろ検討した結果、かえって見にくいということで、あえてこういう方向にしたところです。","id":"exchange-025"},{"speaker":"つる委員","kind":"質問","question":"倉庫の件、また今のサインの件も、非常に勉強になりました。これまでもあったかどうか、そうした災害関係の訓練とかというのは、今後の中で考えがあるのかどうかというのを参考までに説明を求めました。","respondent":"鈴木（誠）防災課長","answer":"実は３年ほど前まで、実際に離発着で、物資の搬送訓練というのをやっておりました。重要な災害時の対応の１つの手法になりますので、ほかにも区内４カ所は、検討していきたいというふうに考えております。","id":"exchange-026"},{"speaker":"つる委員","kind":"質問・要望","question":"済みません。先ほど近隣住民とのいろいろなご協力とかご要望とかある中で、適時適切なタイミングを選んで、そういう訓練も考えていってほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-027"}]},{"id":"topic-02","title":"の平成２７年度区内一斉防災訓練（避難所・災害対策本部）の実施","agenda":"の平成２７年度区内一斉防災訓練（避難所・災害対策本部）の実施","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"概括的なことからお伺いしますけれども、今回一斉防災訓練が何回目になるのかということと、あと開催を積み重ねていって改善や工夫してきた点、そして今回の訓練で一番強化したい重要ポイントとなるというのは、どこと考えていらっしゃるのかを、まずお伺いします。","respondent":"黒崎防災安全担当課長","answer":"もう１つですけれども、区内で災害が発生したときには、さまざまな状況とか、あとは避難所からの物資の応援の、そういう連絡が来る。区の災害対策本部にその情報を集めてみると、このような通信訓練を今年度の訓練の目玉、強化した部分として企画してまいりました。","id":"exchange-028"},{"speaker":"安藤委員","kind":"質問","question":"具体的にお伺いしたいのは、Ｅメールというのですか、１日たってから届くというような状況もありました。その参集の仕方というのですか、これも１つの訓練ではないかと思うのですが、今回はどのようにしていくつもりなのかというのをお伺いします。","respondent":"鈴木（誠）防災課長、黒崎防災安全担当課長","answer":"１点目の、先ほど委員のお話にあったような民間の携帯とかの通信会社の回線とは別ですので、そういったアクセス制限がかかりにくいというのが１つ。いわゆる区で独自の放送局を設置している防災無線それからここに書いてある移動通信… 参加していない町会関係の課題と必要な支援につきましては、やっと、少しずつ広まってきたというような状況もあります。","id":"exchange-029"},{"speaker":"西本委員","kind":"質問","question":"幾つかあるのですが、まず今の３２カ所になりますけれども、徐々にというお話ですが、徐々にでいいのですかというところがあります。それは、今回参加されないところは、その運営会議もやっていないということの理解でよろしいでしょうかというのが１つ目です。","respondent":"鈴木（誠）防災課長、黒崎防災安全担当課長","answer":"防災課は、地区ごとに係長と職員の２人１組で地区担当を設置しておりまして、その担当者がしっかりとフォローするという形をとっているところです。それから避難所ごとに約１０名程度指定をしております職員が、その取り組みも今… どのくらいの町会が参加していないのかですが、今年度予定されている１２月５日の訓練につきましては、１３１町会が参加予定です。","id":"exchange-030"},{"speaker":"西本委員","kind":"質問","question":"ただ、品川区全体の中で、統一性というにはどうなのでしょうか。３.１１の時から、もう４年過ぎて５年になろうとしているところで、これからの取り組みというのをどう考えられているのかをお聞きしたいと思います。","respondent":"鈴木（誠）防災課長","answer":"ただし、徐々に拡大をしているというのが現状ですので、それをできるだけ短い期間で全体実施に向けて努力はしたいというふうに考えております。","id":"exchange-031"},{"speaker":"西本委員","kind":"質問","question":"地域センターでもいいのですけれども、フィードバックというのは、今後どう考えられるのですか。共通の課題という形で、全体的に広げていかなければいけないと思うのですが、それについてのお考えをお聞きしておきたいと思います。","respondent":"黒崎防災安全担当課長","answer":"前年度実施していただいた各避難所につきましては、反省点を踏まえた作業方法などの見直しが主なのですが、そのようなものをしております。区で実施した結果の情報が、少しずつ訓練の中のブラッシュアップといいますか、レベルアップを図っているという状況です。","id":"exchange-032"},{"speaker":"西本委員","kind":"質問","question":"そうしないと、忘れてしまいます。なので、終わった後にすぐ振り返りというのは必要だと思うのですが、それはいかがか尋ねました。","respondent":"黒崎防災安全担当課長","answer":"ちょっと委員からのご質問の趣旨を勘違いいたしまして。反省点を出し合って、来年はというような話を持つ会議体は、それぞれ設置してやっております。","id":"exchange-033"},{"speaker":"鈴木（真）委員","kind":"提案","question":"１０年ぐらい前に、一斉にやりましょうよ」という話を提案させていただいて、今回４回目。こういう実施できなかったところにあるのかというのが１点、教えてもらいたいのと、ちょっとどうかとの意見を述べました。","respondent":"鈴木（誠）防災課長","answer":"それともう１つは、現在のところは学校が授業のある日とない日、それぞれやってみようということで交互に実施をしたりということで。","id":"exchange-034"},{"speaker":"鈴木（真）委員","kind":"意見","question":"先ほど言った職員の方も、そうやって訓練に出るのは大変でしょうけれども、ぜひいい形で進めてもらいたいと思っていますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-035"},{"speaker":"安藤委員","kind":"確認","question":"空き家が確認されたということですけれども、これは１,６７４戸について登記簿調査の上、このうち何戸あったのかというのをお伺いします。こちら特定空家と認定するタイミングのところ、もう少しちょっとわからなかったので、お伺いします。","respondent":"矢木住宅担当課長","answer":"第１点、登記簿調査で所有者が判明した物件につきましては、アンケートを送付した件数ということで、１,３８０件ございました。４番の下の対応、こちらの対応のほうを各所管でした後に、２番左下の措置のところに移行するものです。","id":"exchange-036"},{"speaker":"安藤委員","kind":"質問","question":"措置の前に、この認定をする。措置の対応をするということでよろしいのかというのが１点と、この審議会で特定空家と認定されている件数は何件なのか、お伺いします。","respondent":"矢木住宅担当課長","answer":"委員ご指摘のとおり、できる限り所管課での対応をした上での認定という形になるということと、あと、認定、既に済んでおりますものは、特定空家については１件あります。","id":"exchange-037"},{"speaker":"安藤委員","kind":"質問","question":"実際に産学官と地域によるアイデアというのもありますが、どんなアイデアや検討が出されているのか、現状をお伺いいたします。それと、区による活用も難しいというお話がありましたけれども、どういったところが課題になっているのか、もう少し尋ねました。","respondent":"矢木住宅担当課長","answer":"産学官におけるどんなアイデアが検討されているかですが、そういう複合的な施設みたいなことが、アイデアとしては出ているところです。なかなか、そもそも未登記なものが１０件近くございまして、なかなかマッチングがうまく進まなかったというようなこういう事情があります。","id":"exchange-038"},{"speaker":"安藤委員","kind":"提案","question":"地域の方からも伺ったのですけれども、実際に実施できないわけですから、私の提案ですが。そしてもう１つ言えば、どのように考えているのか、それぞれお伺いしたいと思いますとの意見を述べました。","respondent":"矢木住宅担当課長","answer":"町会会館につきましては、空き家の活用ということで、具体的に既に２つや３の検討はしております。子ども食堂につきましては、地域ニーズがあり適地があれば検討の余地があるというふうに考えてあります。","id":"exchange-039"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"ごみ屋敷についてお伺いしますけれども、旗の台４丁目の物件に関しましては、私も承っております。ちょっとわからない点が１つと、そういったことで、今現在の進捗状況を教えてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-040"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"あそこはまさに通学路、旗の台小学校もありますし、地域からの要望がすごい。本当の地域の強い要望なので、かかってくると思いますので、早急に条例にのっとって措置をしてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-041"},{"speaker":"西本委員","kind":"確認","question":"要対応が９９件というのが、密集しているのか、どんなふうになっているのでしょうか。おわかりでしたらちょっと教えてほしいのですけれども。","respondent":"矢木住宅担当課長","answer":"こちらの利活用、修繕利用と答えのあった１,５００件を超えるほとんどのところですが、こちらにつきましては、客観的に見て使えそうだという物件。ちょっと雑感、ざっくりで申しわけないのですけれども。","id":"exchange-042"},{"speaker":"西本委員","kind":"質問","question":"ここにも書いてある外観目視によるということなので、この後、結局その持ち主の意向を聞いていくという段階のものなのでしょうか。その、いろいろ国も挙げていろいろやろうとしているので、法的なところが変わりそうなところがあるのかどうかをお聞きしたいのですけれども。","respondent":"矢木住宅担当課長","answer":"例えば、相談窓口の設置でありますとかを検討いたしますとともに、啓発のパンフレットを送付するといったことで対策を考えていきたいです。ただ、福祉的対応も必ず必要であるというふうに認識しています。","id":"exchange-043"},{"speaker":"西本委員","kind":"提案","question":"なかなか提案できないのですけれども、ほかの委員会とのさらなる議論というのを進めていく必要もあるのかというふうに感じました。ただ、最終的なところは、この1)のごみ屋敷というところが、一番の空き家対策については気になる部分なのかというふうに感じましたとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-044"},{"speaker":"鈴木（真）委員","kind":"質問","question":"今後こういうケースがまだ出てくる可能性もありますが、そのときの対応の、具体的には費用負担。今後どういうふうに考えていったらいいのかと、どこまで手を出していいのか、そこら辺の考え方というのはどういうふうに捉えたらいいのか尋ねました。","respondent":"藤田都市環境部長","answer":"どの段階から適用していくのがいいのか、これは、今やりながら考えているというような状況です。その辺の兼ね合いをよく考えながら、まずは所有者にしっかりやってというお話をしていくのが、一番最初だというふうに考えてあります。","id":"exchange-045"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"折衝は大変だと思うのですけれども、安全面ということでは、その辺のことも調整していただきたいというのが、これは要望します。９条あたりの段階でも、認定はしていないけれども認識した上で進めているという状態なのかどうか、そこをもう一度説明していただけますか尋ねました。","respondent":"矢木住宅担当課長","answer":"私の説明が不十分で申しわけございませんでした。審議会がよろしいというふうに答申していただくと、認定しますと区長が決定する、そういうような形になってあります。","id":"exchange-046"},{"speaker":"鈴木（真）委員","kind":"意見","question":"３番に、例えば区の場合ですと二方向避難とか耐震性の問題もあって、区として活用が難しいというお話があったと思う。３番で産学官協働活用モデルの場合にも、こういうときの避難という感覚でいくと、そこら辺はどういうように考えたらいいのかとの意見を述べました。","respondent":"矢木住宅担当課長、藤田都市環境部長","answer":"そういったところでは、町会会館や子ども食堂といったところは、ある程度そういった縛りがないと考えられるのが１点と。この程度古くても１階建ての利用しやすいところが、１階建ては少ないですけれども、事業を考えているところです。民間の場合いっぱいありますけれども、それは区の立場として、なるべくやりたくない立場です。","id":"exchange-047"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"活用してもらいたいという前提での話なので、産学官、それと同時に地域の声も生かしながら、ぜひ進めていってもらいたいと思います。これは要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-048"},{"speaker":"つる委員","kind":"確認","question":"ちょっと順を追って、確認も含めて教えてください。意向があるというお答えが２７件ですが、大体どういうものがあったのか、まずちょっと説明を求めました。","respondent":"矢木住宅担当課長","answer":"１番はその相続で、次は別の住まいへ転居した。そういった感じで、あと建物が古くてそのままでは使えないからそのままにしている、そういったところでございました。","id":"exchange-049"},{"speaker":"つる委員","kind":"質問","question":"そうすると、３番の区によるというところに関連すると、その２７件お返事があったということのものが分母になるということでいいのでしょうか。そういう課題、今の状況なのか、説明を求めました。","respondent":"矢木住宅担当課長","answer":"今年度につきましては、モデル事業ということで、２７件を主な対象として進めているところでございまして、その中で、なかなか活用が難しいという現時点での状況です。","id":"exchange-050"},{"speaker":"つる委員","kind":"質問","question":"それを１つの分母としてやっていただいているという中で、１,６７４という１つの分母がある中で、現在の案を説明するよう求めました。","respondent":"矢木住宅担当課長","answer":"こちらも来年度には活動するということで、少しずつ話を進めておりますので、これについても実現に取り組んでいきたいと考えています。いずれにいたしましても、なかなか困難な問題が山積しておりますが、頑張って対応していきたいと思います。","id":"exchange-051"},{"speaker":"つる委員","kind":"質問","question":"この条例、法律ももちろんそうですけれども、１つの目的だとは思うのです。どういう方向性を、１つ突破口と見ているのか、このあたりもわかれば説明を求めました。","respondent":"藤田都市環境部長","answer":"でも、それでも難しいとか、いろいろなご事情があるようなケースに、区のほうが手をお貸しするというような形で進めるのがいいのかと。いろいろ私どもとしても点検ができたりとか、そういうようなことも含めて、今後ちょっと研究をしていきたいというふうに考えております。","id":"exchange-052"},{"speaker":"つる委員","kind":"質問・要望","question":"なので、これは要望です。2)との関連性が出てくるのですが、このあたりを最後、ちょっと教えてほしいと求めました。","respondent":"藤田都市環境部長","answer":"通常、今行われています地域の力支援チーム、こちらのほうも地活のほう、それから都市のほうも含めたいろいろな形で対応してきているところです。","id":"exchange-053"},{"speaker":"安藤委員","kind":"質問","question":"１つの旧東海道地域の売りというか、しかもこれは一軒家ではないですか、私は問題意識があるのですけれども。ちょっと、そこら辺についてはどうなのかという私の問題意識がありますという、うまく言えないのですけれども。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-054"},{"speaker":"筒井委員","kind":"意見","question":"どうしても家賃とかコストがかかると、そういう商業、そうした起業家たちをサポートするための施設とかに活用できないのかと。本当、所有者の同意が必要だと思うのですけれども、そうしたビジネス拠点として使えないかとは思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-055"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"できる限りのことをやっていただけないかと、やっていただきたいというのが、我々の要望だと思う。区内の中で、区行政の中の連携というのを、もう１回改めてお願いしたいということが要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-056"},{"speaker":"木村副委員長","kind":"意見","question":"こういう所がありますよ」みたいな感じで、何か紹介をするようなことも、１つの手ではないかと思います。そういう意味では、もちろん安全でないのは困りますけれども、そういう点もクリアできるのであれば、そういうのも１つの手ではないかと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-057"},{"speaker":"西本委員","kind":"質問","question":"多少修繕すれば、それなりに稼いで、お金も集められるわけですから。これ、できるのではないですか、品川区に。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-058"}]},{"id":"topic-03","title":"の３、その他","agenda":"の３、その他","exchanges":[{"speaker":"安藤委員","kind":"質問・要望","question":"駅舎等のセーフティー化ということで、ハード対策として、駅のホームの整備推進の質問だったのですけれども。設置の動静については、品川区からも東急のほうに要請していただきたいと考えているところですが、区のお考えと現状について伺いたいという質問です。","respondent":"中村都市計画課長","answer":"相当の安全性の効果が見込まれるというふうには考えますけれども、しかしながら、さらに安全性は増すというところは否めないところです。６４駅に設置するに当たりまして、やはり優先順位として、順次整備する順番というのも仕方ないのかというふうに考えてあります。","id":"exchange-059"},{"speaker":"安藤委員","kind":"質問・要望","question":"ですから、さらなる安全確保を引き続き求めていくというお話でしたので、こちらにも設置をしていただきたいということを要請をしていただきたい。いかがでしょうかということと、こちら６４駅という紹介がありましたけれども、そこら辺のことをお伺いしたいと思います。","respondent":"中村都市計画課長","answer":"無理にホームドアを設置をしても、逆に効果が見込まれない、状況に応じて設置をしていただくように鉄道事業者のほうに求めているところです。池上線につきましても大井町線のホームの柵の設置に当たりまして、既にもう設置はしていただいているけれども、お願いをしています。","id":"exchange-060"},{"speaker":"安藤委員","kind":"質問・要望","question":"要請していただいているということだと思いますけれども、よろしくお願いします。さらなる１日も早い設置に向けて進めて行っていただきたいのと、終わったらここもやる予定があるのかどうかというのは、お伺いします。","respondent":"中村都市計画課長","answer":"結論から申しますと、東急のほうでは、具体的に池上線が、大井町線が終わった後に工事をやるというふうには明言はしておりません。区のほうで、粘り強くまたお願いしていくという形になると思います。","id":"exchange-061"},{"speaker":"安藤委員","kind":"確認","question":"それと、北品川地区にお住まいの皆様へということですが、これはどういった感じで周知をされているのかというのをお伺いします。仮囲いというのですか、解体するのでしょうか、確認したいと求めました。","respondent":"中村都市計画課長","answer":"建物の解体工事ですと、高さと同じ範囲の横の範囲について、周知をして説明を行っているというふうに聞いてあります。今後、上屋の工事がまた始まるに当たりましては、区のほうに届け出がある予定ですけれども、まだ具体的な計画についての相談等もないです。","id":"exchange-062"},{"speaker":"安藤委員","kind":"質問","question":"それともそれはどういうことなのでしょうかというのが１点と、情報把握に努めるということなのでしょうか、そこら辺をお伺いします。","respondent":"中村都市計画課長","answer":"今回のこの１件の事業者の公表ですとか、前回の工事の説明会に当たりましては、また引き続きお願いをしてまいりたいというふうに考えてあります。もう１つ、説明会の参加についてですけれども、区のほうも参加を予定しています。","id":"exchange-063"},{"speaker":"安藤委員","kind":"質問・要望","question":"わかれば教えていただきたいのと、この計画ができたことで区としてどんな動きにつながっていくのかというか、そこら辺をちょっとお願いしたいと思います。","respondent":"和田河川下水道課長","answer":"下の右側の写真のように例えば親水空間として活用したりとか、区民が水に親しめるような空間として整備することを東京都は考えているです。方向性として示されてありますので、区との関連としましては、そういうことなのかというふうに感じてあります。","id":"exchange-064"},{"speaker":"鈴木（真）委員","kind":"意見","question":"１点だけ、東京都の考え方から、ちょっとどうなのか、期限的には、どのぐらいのめどでやっているのか。暗渠区間が６.６６キロメートル、そこら辺、ちょっと含めてとの意見を述べました。","respondent":"和田河川下水道課長、松代防災まちづくり部長","answer":"この整備計画の整備期間ですけれども、計画の中では、概ね３０年間で整備というようなことで書かれているところです。ただ、それが毎秒１５立方メートルまでに抑えられるということで… そのときの対応が、まずご説明をするのですけれども、二級河川で東京都の管理ということになっています。ただし、もうご存じのように、今回のような形ができたというようにご理解いただければと思います。","id":"exchange-065"},{"speaker":"安藤委員","kind":"質問・要望","question":"済みません、ちょっと杭打ちの改ざん、改ざんをしたというところの企業のお名前を教えていただきたいと考えています。もしあれば、その内容について、どんな内容なのかというのを差し支えなければ教えていただきたいというふうに思います。","respondent":"鈴木（和）建築課長","answer":"杭の改ざんが、公表していますが、旭化成建材、それからジャパンパイル、それから、ちょっとお待ちください。失礼しました、杭の団体のほうで、一律公表しておりますが、済みません。","id":"exchange-066"},{"speaker":"安藤委員","kind":"確認","question":"いかがでしょうかということと、一部外構工事でデータの出ていないのが１件あったということでしたけれども、２点お伺いしたいのです。今、確認中と申されたと思うのですけれども、これは先ほどの説明だと人為的なミスだというような説明だったのか尋ねました。","respondent":"鈴木（和）建築課長、藤田都市環境部長","answer":"報告がおりてくるような形で最終的な流用があったものについては、各特定行政庁が、その基準法の範囲で対応していくというような形になってあります。ちょっと先ほど説明が非常にわかりにくくて申しわけなかったのですけれども２件… 補足を。先ほど、一番冒頭に申した２社プラス三谷セキサン、そちらの３社ということになっています。","id":"exchange-067"},{"speaker":"安藤委員","kind":"質問・要望","question":"どこに電話していいかというのがわからないと思うので、もう少し、そこら辺の周知が必要なのかという要望を出します。杭打ちを行ったという事実はあるのかどうかというのはわかるのでしょうかというか、調査したのでしょうかというか、お伺いいたしたいと思います。","respondent":"溝口都市開発課長","answer":"今後どういう対応をしていくかというのは、全体の建物を通した中での対応になってくるというふうに考えておりますので、区としても対応していきたいというふうに考えているものです。","id":"exchange-068"},{"speaker":"鈴木（真）委員","kind":"確認","question":"確認です。そこだけもう１回確認、きちっとしておいてもらいたいと思っています。","respondent":"鈴木（和）建築課長","answer":"先ほどの７社の中にジャパンパイルというところもあります。追加してご報告をします。","id":"exchange-069"},{"speaker":"鈴木（真）委員","kind":"質問","question":"先ほど言ったのは、全部が流用があったということですか、そこの判断がちょっとごっちゃになってしまっているから。","respondent":"藤田都市環境部長","answer":"調査を行っているものが、全体の数でございまして、その中で、不適切な流用があったというのが、旭化成建材とジャパンパイルと三谷セキサンの３社です。","id":"exchange-070"},{"speaker":"鈴木（真）委員","kind":"質問","question":"済みません。先ほど名前を言っていた残りの会社は、そこに入っていないということで、調査をしているということでいいわけか尋ねました。","respondent":"藤田都市環境部長、鈴木（和）建築課長","answer":"ちょっと微妙な表現でございまして、今、国のほうに、その協会のほうが調査の状況の報告をしているのが、調査をしているところまでしか報告をしていないという状況、済みません。 ちょっといろいろ説明が不足しまして申しわけございません。先ほど会社の名前を報告しました７社に流用があったということで、自主的に国のほうに報告をしています。","id":"exchange-071"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/557041?Template=document&Id=4158#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=8&TermStart=2015-01-01&TermEnd=2015-12-31"}],"sourceMeta":{"pages":0,"characters":71929,"voices":208}},{"id":"h27-20151201-9","meetingId":"h27-cm12","date":"2015年12月1日","dateIso":"2015-12-01","committee":"文教委員会","time":"午前１０時００分～午後 ３時５３分","status":"正式会議録","sourceType":"formal","overview":"文教委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を79件整理しています。","topics":[{"id":"topic-01","title":"品川区立義務教育学校通学区域の取扱い","agenda":"品川区立義務教育学校通学区域の取扱い","exchanges":[{"speaker":"飯沼委員","kind":"質問","question":"この辺はどういうふうに決められていて、不都合はないのかどうか、ちょっとそこをお伺いいたします。","respondent":"野呂瀬学務課長","answer":"基本的に不都合はありません。そのまま中学校はストレートで抽選なしに入れるということですので、ルール上は今までと全く変わりませんので影響はないと考えております。","id":"exchange-001"},{"speaker":"飯沼委員","kind":"質問・要望","question":"先ほど行った教育総合支援センターで、中学校と小学校の学区域のすごくわかりやすい地図が置いてあったのですけれども、あの地図というのは、学区域を把握する上でとてもいい地図だなと思ったのですが、あれをいただきたいなと思っているのですが、どうか尋ねました。","respondent":"野呂瀬学務課長","answer":"検討します。多分予備があると思います。","id":"exchange-002"},{"speaker":"浅野委員","kind":"質問","question":"そのようなデータというのでしょうか、そういう何か調査をされたのであれば、ちょっと教えてほしいと求めました。","respondent":"野呂瀬学務課長","answer":"その調査というのは、実際に何分かかるかという調査は学務課としても、教育委員会としてもしておりません。平均何分というのはちょっと調べていないですけれども、大体考えて５分か１０分、１５分の間でほとんどの子は通学しているものと考えております。","id":"exchange-003"},{"speaker":"浅野委員","kind":"質問","question":"そういう形で規定されているというのでしょうか、それだけで規定はできないところがあると思いますが、くれぐれも児童の安全ということに気をつけてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-004"},{"speaker":"石田（ち）委員","kind":"質問","question":"めくった２枚目の日野学園の米印のついているところは何なのか。フリーゾーン地域というのは、どういう意味なのか伺いたいと思います。","respondent":"野呂瀬学務課長","answer":"学区域は芳水小学校ですが、日野学園の学区域としても取り扱っていると、特殊だということでフリーゾーンとして扱っているです。","id":"exchange-005"}]},{"id":"topic-02","title":"平成２８年度入学希望申請の状況","agenda":"平成２８年度入学希望申請の状況","exchanges":[{"speaker":"飯沼委員","kind":"質問","question":"ぱっと見たところは、そんなに去年とかおととしとかと変わらないかなと思っているのですが、その辺の増減のところの要因とか何かがありましたら説明を求めました。","respondent":"野呂瀬学務課長","answer":"二年はおさまるけれども、それ以降は住民基本台帳の人数が多くなるだろうということで、これにつきましては今改築を進めているところです。","id":"exchange-006"},{"speaker":"飯沼委員","kind":"質問","question":"抽選のところが何校かあるのですけれども、受入枠の決め方をもう一回教えてほしい。その辺の理由も含めて、この受入枠、もともとのところが入り切れなくて抽選になってしまうところはどうしてかと思うので、そこを説明するよう求めました。","respondent":"野呂瀬学務課長","answer":"それは１００％抽選でなく入れるということで、ほかの学区域からの受け入れが難しいと、これが現状です。今改築中の芳水小学校だとか、城南小学校につきましては、教室が今後いっぱいになると足りなくなってくるというのが予想されるので改築しています。","id":"exchange-007"},{"speaker":"飯沼委員","kind":"質問","question":"芳水小学校はこれからで、これからも多分増えると思うのですけれども、改築しても結局は学区のほうは飲み込めないというふうになってしまうのですか。これというのは、結局最終的な精査をしていくと何とかなるのか尋ねました。","respondent":"野呂瀬学務課長","answer":"例えば今年生まれた０歳児は６年後に入学するだろう、来年生まれた子はそのまた６年後と、ずっと毎年シミュレーションをしております。仮に今の教室数で足りなくなるようでしたら、例えば教室をほかのところを転用するような形で処置をして、通学区域の子は全員入れていくです。","id":"exchange-008"},{"speaker":"鈴木（博）委員","kind":"質問","question":"第一日野小学校も９０人に対して９３人だけれども、この辺というのは受入枠プラス３人ぐらいなのだけれども、要するにこの辺はなぜ抽選なのか尋ねました。","respondent":"野呂瀬学務課長","answer":"受入枠が１４５人みたいなことで書いておりますけれども、これについても、例えば日野学園の昨年の入学者は２９８人中１３１人入学しているです。","id":"exchange-009"},{"speaker":"鈴木（博）委員","kind":"質問","question":"品川区の中の学校の地域格差みたいなものに関して、教育委員会としてはどのように捉えて、長期的にはどういう観点で考えているのでしょうか。それは、そのままでいいのか尋ねました。","respondent":"野呂瀬学務課長","answer":"この通学区域というのは、また学校選択をやっている上で、やはり３割ぐらいの方は必ず学校選択を希望されているというところがあります。ただ、ここ一、二年の場合は、何とかこの中でできているというふうな形で考えております。","id":"exchange-010"},{"speaker":"石田（ち）委員","kind":"質問","question":"中学校のほうは、先ほど３割近くが私立ということだったのですが、小学校のほうの平成２７年度の住民基本台帳の予定数２,６７１人、それで入学者数が２,４９３人、そうすると、それ以外の人は私立に行ったということでいいのか尋ねました。","respondent":"野呂瀬学務課長","answer":"ご説明が漏れてしまったかもしれません。今年度は２,８０８人ですので、例えば７％抜けたとしたら、来年の４月の小学生の人数は２,６００人ぐらいかなというふうに予想しています。","id":"exchange-011"},{"speaker":"浅野委員","kind":"質問・要望","question":"そういうものについてちょっと教えていただきたい。やはり中学校を見ると、この傾向は本当にこのままでいいのかなというのは気になっているところなのですけれども、この２点についてお伺いします。","respondent":"野呂瀬学務課長","answer":"私が冒頭でご説明しましたとおり、保幼小連携とかをいろいろ進めていく中で、２年前から２学級になってきた。ＰＲして、ぜひともうちの学校みたいな形で努力していますので、これについては今後とも積極的に努めてまいりたいと考えております。","id":"exchange-012"},{"speaker":"浅野委員","kind":"意見","question":"そういうことで随分変わってくる可能性も秘めているという、その可能性をぜひともこれからも追求していってほしいと求めました。これは小学校も中学校も同じですので、やはりしっかりと安全に心がけられるように、そのような取組みをお願いしたいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-013"},{"speaker":"伊藤副委員長","kind":"質問・要望","question":"増えているところはさまざまな理由があるのでしょうからいいのだけれども、具体的な手をどう打っているのかというのはなかなか見えてこないのですよ。そのことについて、もしお答えがあれば教えていただきたい。","respondent":"野呂瀬学務課長","answer":"それまで単学級だったのが２学級になったという効果も出ておりますし、それはそれで一つの教育委員会として側面からの支援かなと考えております。","id":"exchange-014"},{"speaker":"伊藤副委員長","kind":"質問","question":"それに対して、では現場の校長や、それからさまざまな人たちがどれだけＰＲしているのですかということを、ずっと私は見続けてきたわけです。それに対する対応を現場の校長を中心として活動していくということまで話を詰めていかないといけないと思うので、もう一言答弁をお願いいたします。","respondent":"野呂瀬学務課長","answer":"いろいろ学校のほうとしても地域に出て行って、例えば防災訓練とかに対しても、学校の先生が出ていくというのはほとんど日常的になってきております。昨日もご説明したように、大規模校に限らず、引き続き教育委員会も一緒になってやっていきたいと考えております。","id":"exchange-015"},{"speaker":"大倉委員","kind":"質問・要望","question":"支援をどのようにしていくかというのを教えていただきたいのと、学校のよさや校風とか、地域の人たちは非常に敏感に見ていると思うのです。学校のためにというところで、その辺の先生方の休みとかという部分はどういうふうになっているか説明を求めました。","respondent":"渋谷指導課長","answer":"何でもかんでも先生たちだけでやるのではなくて、学校を支援する組織をつくるために、学校支援地域本部などというものも考えているところであります。","id":"exchange-016"},{"speaker":"飯沼委員","kind":"質問・要望","question":"やはり小規模の学校のよさというのもどんどんアピールしていただきたいなと思うのは、日野学園のところは、もともと第二日野小学校だったのですよね。何とか１クラスの学級を少人数学級にこぎつけていただけると、その辺をぜひ進めていただきたいなと思うのですが、いかがか尋ねました。","respondent":"野呂瀬学務課長","answer":"ただ、いかんせん、３５人にならないどころか、十何人で１クラスというのがずっと続いている。実際それぞれの学校で取り組んで努力しているというところは伺えますけれども、学校が一丸となって取り組んでまいりたいと考えております。","id":"exchange-017"},{"speaker":"高橋（し）委員","kind":"質問","question":"学校の評価ということをお尋ねしたいのですけれども、学校の評価については幾つか評価があるうちのこれは一つなのだというふうに思うのですが、そのあたりについてどうお考えか尋ねました。","respondent":"渋谷指導課長","answer":"それは委員ご承知のとおり地域性もありますし、立地の問題もありますし、そういったことをさまざま総合的なもので一つの結果としてあらわれていると。","id":"exchange-018"},{"speaker":"高橋（し）委員","kind":"質問","question":"入学した児童・生徒が卒業したときに、そこの学校にいてよかったなというのも評価だと思うのです。ですから、地域のいろいろな考え方がまとまっていくのではないかと思う。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-019"}]},{"id":"topic-03","title":"区立保育園の今後の運営","agenda":"区立保育園の今後の運営","exchanges":[{"speaker":"鈴木（博）委員","kind":"質問","question":"区立の保育園というのは経費が年間大体８９億円かかって、人件費が５４億円で大体６０％だということなのですけれども、それはどのぐらいの割合なのか尋ねました。","respondent":"竹田保育課長","answer":"私立ですと都支出金が１１.０％、国庫支出金が運営費に占める割合が１６.６％という状況ですが、それ以外は全て区の一般財源での支出となっております。","id":"exchange-020"},{"speaker":"鈴木（博）委員","kind":"質問","question":"これは例えば目的の(2)で、例えば今現在の公立公営というのですか、要するに区立から外れると国および都から負担金というのは支給されるのか尋ねました。","respondent":"竹田保育課長","answer":"東京都から４分の１の補助が出ることから、区の持ち出しはおおむね４分の１というような状況になります。すみません、もう一度申し上げますが、国および都からの補助金は出まして、おおむね運営費の国が２分の１、都が４分の１です。","id":"exchange-021"},{"speaker":"鈴木（博）委員","kind":"意見","question":"そうすると、例えばここに書いてある公設民営の場合はどうなるのかとの意見を述べました。","respondent":"竹田保育課長","answer":"公設民営の場合は、まだ公立の種類に属しますので、国および都からは出ないという状況です。","id":"exchange-022"},{"speaker":"鈴木（博）委員","kind":"質問","question":"わかりました。こういうことを配慮しながら進めるとか、何かそういうポイントというか、そういうお考えというのはあるのか尋ねました。","respondent":"竹田保育課長","answer":"民営化で当面課題となっていく点ですが、公立から私立に運営の中心が移るということで、今までの保育環境あるいは保育の質が維持されるかどうかというのがポイントとなってきますので、行政としてしっかりチェックして責任を果たしていきたいと考えております。","id":"exchange-023"},{"speaker":"鈴木（博）委員","kind":"質問","question":"スケジュールとしては平成３１年以降ということは、今平成２７年ですから、だからあと４年ぐらい。今いる園児が卒業したぐらいを目安に考えているということなのか尋ねました。","respondent":"竹田保育課長","answer":"こちらにお示ししましたのは、最短のスケジュールを想定して書いたものですので、それぞれの施設の状況等によりまして、こちらのスケジュールのほうは変わっていくものです。","id":"exchange-024"},{"speaker":"石田（ち）委員","kind":"質問","question":"平成２７年度当初予算で８９億円、うち人件費が５４億円ということなのですけれども、民営化、それぞれ手法があるということですけれども、これは文章から、削減されていくということだと思うのですけれども、どれぐらい削減されると見込んでいるのか伺いたいと思います。","respondent":"竹田保育課長","answer":"先ほど申し上げたとおり民設民営になった場合は、国および都からの補助金が出ますので、その部分が削減されるというふうに考えております。区の持ち出しが不要になると考えております。","id":"exchange-025"},{"speaker":"石田（ち）委員","kind":"質問","question":"今現在８９億円で、人件費が５４億円、それで区の一般財源で負担しているということなのですけれども、もろもろほかにも一般財源で負担しているものがあると思うのですが、この区立保育園にかかる一般財源は、割合として全体のどれぐらいに当たるのか尋ねました。","respondent":"竹田保育課長","answer":"平成２７年度予算で申し上げますと、区立保育園、私立幼稚園の合計の運営費は１３２億７,０００万円余となっております。そのうち、区立保育園の占める割合が８９億８０３万円余となっている状況です。","id":"exchange-026"},{"speaker":"石田（ち）委員","kind":"質問","question":"すみません。全部の予算の中で、区立の保育園運営費はどれぐらいを占めているのでしょうかということです。","respondent":"竹田保育課長","answer":"区の一般財源に占める区立保育園の運営費ですが、おおむねですが、８.２％となっております。","id":"exchange-027"},{"speaker":"石田（ち）委員","kind":"質問","question":"これだけ頑張ってきた区立保育園の運営がとうとう民間委託かということで、国と都から補助が２分の１と４分の１が出ると。これだけ軽減させていかなければいけない原因というのは何なのかをちょっと具体的に伺いたいと思います。","respondent":"竹田保育課長","answer":"保育の現状の課題としまして、待機児童の解消あるいは老朽化した保育園の施設等、課題はたくさんあります。こちらで低減できた経費については、待機児童対策等に回していきたいと考えております。","id":"exchange-028"},{"speaker":"石田（ち）委員","kind":"質問","question":"そうすると、民間活力の活用をしないと、そういったことが果たせない、改善はできないというふうに考えられているということか尋ねました。","respondent":"竹田保育課長","answer":"ご存じのとおり保育需要は非常に高まりを見せておりまして、最新の人口推計におきましても、今後就学前人口、乳幼児人口の増加が予想されております。","id":"exchange-029"},{"speaker":"石田（ち）委員","kind":"質問","question":"それが民間になることでどうなっていくかわからないというところでは、基本方針の(2)のところに、相当数というのはどれくらいを言っているのか尋ねました。","respondent":"竹田保育課長","answer":"現在の基本方針としては、１年当たり１園、５園程度を当面の目標としていくわけですけれども、将来的に乳児人口が変動してまいりますので、そういった乳児人口も見極めながら区立保育園の数についてはその時代に合った数にしていきたいと考えております。","id":"exchange-030"},{"speaker":"石田（ち）委員","kind":"質問","question":"ちょっと今よくわからなかったのですけれども、要は区立のままとする保育園を相当数残していくわけですよね。これはどれぐらいか尋ねました。","respondent":"金子子ども未来事業部長","answer":"一定の答えは出ておりますけれども、５年間で１園ずつやっていきますけれども、これの蓄積というのは非常にハイレベルになっています。そういったところを中核として残したいという考えがありますので、全部が全部民営化していくというわけではないというのが今の考え方です。","id":"exchange-031"},{"speaker":"石田（ち）委員","kind":"質問","question":"すみません。対象園というのは、これから、平成２７年度ということですけれども、行動していくということですけれども、一定のめどはついているのか尋ねました。","respondent":"竹田保育課長","answer":"こちらに対象園を選ぶ基準を記載しておりますが、建物の状況、築年数が何年たっているのか、併設施設があるのか、設備の規模等、あるいは運営状況等を総合的に判断して今検討している最中です。","id":"exchange-032"},{"speaker":"浅野委員","kind":"質問・要望","question":"前例というのでしょうか、品川区では多分やっていないと思うのですが、やっていたら教えていただきたい。それとあと、ほかの地域でそういうような前例というのは今までにあったのか、もし調査をされているようでしたら教えてほしいと求めました。","respondent":"竹田保育課長","answer":"民設民営化が１１園ということで、今後さらに公設民営３園、民設民営１２園を予定しているというふうに聞いております。世田谷区におきましては、民設民営化を５園行ったというところと、あと目黒区につきましても今後４園を民設民営化するという予定と聞いております。","id":"exchange-033"},{"speaker":"浅野委員","kind":"質問","question":"そういう意味では、多分目的としてはコストダウンでしょうかね、それが目的となってやっているかというのを一つ教えてほしいと求めました。５年以降の話ですね、５年たった以降の計画というのは、今お考えがあれば教えてほしいと求めました。","respondent":"竹田保育課長","answer":"民営化によって、さまざまな事業を行っている保育園もあることから、選択肢を増やすという意味合いもあろうかと思います。それから、５年ぐらい先にピークが来るという推計が出ておりますので、そこから先の計画というのは立てていきたいと考えております。","id":"exchange-034"},{"speaker":"浅野委員","kind":"質問","question":"そんなに期間としては３か月、４か月ぐらいしかない中で、大ざっぱでも民営化基本方針の概略を教えていただければなと思います。非常に簡単なものかもしれませんけれども、ちょっと今の時点である程度考えておられるかと思って質問しております。","respondent":"竹田保育課長","answer":"今お示しさせていただいている基本方針が骨子ですので、こちらに肉づけしていくような形で作成していきたいと考えています。区民の方がご覧になってわかりやすいようなものにしていきたいと考えております。","id":"exchange-035"},{"speaker":"浅野委員","kind":"質問","question":"なぜ今さら民営化するのかとか、そういう意見も出てくるだろうし、中にはやはり民営化すべきだという方も多分おられると思います。そのようなご意見をしっかりと受けとめて、区民の方にわかりやすい説明、区の意図が通じるような説明をしっかりと行ってほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-036"},{"speaker":"飯沼委員","kind":"質問・要望","question":"民営化をするということ自体、一体何を期待して民営化するのか改めて伺うのと、保育園はこのことによって、よくなるのでしょうか。その点をお伺いしたいと思います。","respondent":"竹田保育課長","answer":"区民ニーズに対応した多様な保育サービスを将来にわたって安定的に提供していくことが必要だと思います。区立保育園の今後の建替え、利用者にとって快適で安全な保育環境を整備していくという目的のもとにその手段として民営化があると考えております。","id":"exchange-037"},{"speaker":"飯沼委員","kind":"質問","question":"将来にわたって安定的に保育を提供していくということですが、今の状況からすると、安定的な保育の見通しが立たないということなのですか。ちょっとそこが１点と、今よりも保育の環境がよくなるということで、きちんと受けとめてよろしいのか尋ねました。","respondent":"竹田保育課長","answer":"そういったものに対応していくためには、一定の経費削減も必要だと考えております。それから先ほど私が申し上げたのは、そういったことを実現していきたいと考えております。","id":"exchange-038"},{"speaker":"飯沼委員","kind":"質問","question":"そこも１回聞きしたいのと、財調人員というのはどうなっているのか、財調で保育園の職員のところの財源は入っていないのでしょうか。そこを改めてお伺いしたいと思います。","respondent":"金子子ども未来事業部長","answer":"先ほど来課長が説明しておりますのは、これについての国の負担、都の負担というのが出てくる。そういう意味で、安定的に保育施策を継続して展開していくためには、行政をつかさどる人間にとっては当たり前のことかなというふうに思っています。","id":"exchange-039"},{"speaker":"飯沼委員","kind":"質問","question":"人件費約５４億円、６０.７％と書いてあって、財調人員でお金が来ているのですよ。当たり前の保育園のところの財調のところが含まれているという受けとめ方も、ちゃんとしていかないとまずいのではないか尋ねました。","respondent":"金子子ども未来事業部長","answer":"同じ規模でも民設民営の保育園を５０園運営しているとしたら、財調の場合には、基本的には同じ金額が入ってくるだけなのですね。だから、大ざっぱに言って５,０００万円ほど違うというふうになりますと、そういうところが大きな狙いだということでご理解いただければと思います。","id":"exchange-040"},{"speaker":"飯沼委員","kind":"意見","question":"経費削減のところはわかりました。でも、もっともっと大事なところがあるなというところで、ちょっと聞きたいことがいっぱいあるのでどんどん聞いていきますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-041"},{"speaker":"飯沼委員","kind":"質問・要望","question":"今日お示しいただいた６のところの今後のスケジュールのところなのですが、どういったメンバーの方を立てていらっしゃるのかというところを一つ。いつからどこで検討を進めているのかというところを一つお伺いしたいのと、ここのちょっと充実を図っていただきたいのですが、いかがか尋ねました。","respondent":"金子子ども未来事業部長、竹田保育課長","answer":"先ほど来課長が申し上げたとおり、公設民営化あるいは民設民営化というのは、２３区だけに限ってもほとんどの区が実施しているものです。当然のことながら… 基本方針のお尋ねですが、こちらにお示しした資料全てがある意味では基本方針ですので、こういった考え方に沿って今後検討してまいりたいと思います。","id":"exchange-042"},{"speaker":"飯沼委員","kind":"質問・要望","question":"ゼロからではないということなのですけれども、始めてからごたごたするよりも、先に問題点をきちんと話し合っておくほうが大事だと思います。保護者の方の意見を聞く場を設けたりといった形で意見を聞いていくという姿勢をぜひ持っていただきたいのですが、この点はいかがか尋ねました。","respondent":"金子子ども未来事業部長","answer":"私どもとしましては、問題の解決というのは探っていくつもりですけれども、必要に応じて外部の方を含めた検討というのも必要だと思います。こういったものを活用していくのも一つの方法かなというふうに考えているところです。","id":"exchange-043"},{"speaker":"飯沼委員","kind":"質問・要望","question":"ぜひそういう場を設けてほしいのと、パブリックコメントをとるとか、そういった姿勢もぜひ持ってほしいと求めました。公立保育園の役割についてどう考えているのかをちょっとお聞きしたいのと、育むために何が必要なのか、行政の姿勢をぜひお伺いしたいと思います。","respondent":"竹田保育課長","answer":"保護者の方、事業者の方と十分協議しながら新たに出てきた問題や課題については対応していきたいと考えております。一定数民営化した後も公立は相当数残してまいりますので、その中で保育をリードをする、そういった役割は今後も継続していきたいと考えています。","id":"exchange-044"},{"speaker":"飯沼委員","kind":"質問・要望","question":"その点を一つお答えいただきたいのと、公設公営の、区の施設の重要な役割であると思っているのですね。保育園のところは絶対握って離さないでほしいので、しっかり握っていただきたいのですけれども、最後にお願いいたします。","respondent":"金子子ども未来事業部長","answer":"介護のほうでも、ちょっと認識が違うかもしれませんけれども、それほど多くはなかったのではないかなというふうに思います。民設民営に関しては、それをきちっと運営することによって区民に対しての良質な保育の提供が実現できていくのではないかというふうに考えております。","id":"exchange-045"},{"speaker":"飯沼委員","kind":"質問・要望","question":"やはり公設公営で、やはり民間の保育士の方が豊かに仕事ができるようなところに対しても行政としてはしっかり目を向けていかなくてはいけない。保育の質を守ることはとても重要なので、コストのところと天秤にはかけないでいただきたいなということを言って終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-046"},{"speaker":"大倉委員","kind":"質問・要望","question":"１園５,０００万円ぐらい経費を、１点だけ教えていただきたいのですが、そういった中での話とかという部分は何かされたのでしょうか。子ども・子育て会議がそもそもどういったものだったかという確認と、する必要があるのかないのかということも含めて説明を求めました。","respondent":"伊崎子ども育成課長","answer":"その中で、一つには子ども・子育て支援法の関係ですけれども、それぞれの保育のさまざまな需要を見込みまして。そちらの計画について子ども・子育て会議の中で検討し、案としていただいたものを今子ども・子育て会議で計画をして成立したわけなのですけれども。","id":"exchange-047"},{"speaker":"大倉委員","kind":"質問・要望","question":"そもそも求めるものが違うので、こういった平成２２年から研究しだしたというか、そういったところで意見を聞くというのはできなかったのかなというところはどうか尋ねました。","respondent":"伊崎子ども育成課長","answer":"これは意見を聞いたほうがいいということで、そちらからそういったご意見がございましたらば、意見聴取をするという方向になるかと思います。今後検討してまいりたいと思います。","id":"exchange-048"},{"speaker":"高橋（し）委員","kind":"質問","question":"話し合いの決定事項ではないので意見を伺うという形になるのかもしれませんけれども、ぜひ会議も何らかの形で議題にしてほしいと求めました。１年間だけ民営化になるのかもという計算なのですが、その引き継ぎがやはり一番、そこのところをもう少し言っていただくよう求めました。","respondent":"竹田保育課長、伊崎子ども育成課長","answer":"仮に１８人だとしますと、５園で９０人ということですので、その程度の人数が削減になるです。それから、０歳児園かどうか、在園児に対する影響ですが、今後それも含めて検討しています。 子ども・子育て会議の一定の議論につきましては、いただいたご意見を踏まえまして会長、副会長とご相談してまいります。","id":"exchange-049"},{"speaker":"高橋（し）委員","kind":"質問","question":"つまり今年募集は始まるわけですから、その辺はどうなのかという感じなのですけれども、その辺の年度の関係とどこまでその辺を計画されているのか。","respondent":"竹田保育課長","answer":"こちらの運営業務委託も平成３１年度以降というふうに記載させていただいておりまして、これは平成３１年度に実施するということではございませんので、ちょっと実施時期も踏まえながら、在園児の影響も考えながら今検討しています。","id":"exchange-050"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"今お話があった影響等をよく考えていただいて、説明や手続などは丁寧にしっかりと行って、円滑に制度の変更ができるように注意を払ってほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-051"},{"speaker":"伊藤副委員長","kind":"質問・要望","question":"だけれども最近のＪＲはどうですか、さまざまな多角的経営をして企業としても優秀になっているし、それから値上げだってほとんどないわけですよ。改めて品川区のお考えをお聞かせいただきたいのと、二つの質問ですが、いかがか尋ねました。","respondent":"竹田保育課長","answer":"保育を実施していく中で、公立でも私立でも大変大事なことだと考えています。行政としてしっかりチェックして、行政としての責任を果たすことによって品川区での適切な保育環境を維持していきたいと考えております。","id":"exchange-052"},{"speaker":"伊藤副委員長","kind":"意見","question":"さまざまな部署で行革、コスト削減、それからサービス低下がないような対応をぜひとっていただきますようにお願いしておきますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-053"}]},{"id":"topic-04","title":"認証保育所の新規開設について","agenda":"認証保育所の新規開設について","exchanges":[{"speaker":"飯沼委員","kind":"質問","question":"この設置者の長谷川キッズライフ株式会社というのは、品川区で初めてですかね。そう思っているのですが、どのような会社なのか説明を求めました。","respondent":"今井待機児童対策担当課長","answer":"長谷川キッズライフ株式会社につきましては、会社が名称変更いたしまして、今年の４月１日に南品川で認可保育園、太陽の子南品川を開設したところと同じ事業者です。","id":"exchange-054"}]},{"id":"topic-05","title":"都市公園内における認可保育園の開設について","agenda":"都市公園内における認可保育園の開設について","exchanges":[{"speaker":"鈴木（博）委員","kind":"質問","question":"一つは、開設から１０年間と書いてあるのですが、なぜ１０年間と区切られるのでしょうか。実際にこれをつくったときに、例えば駐輪場だとか、それはこの計画地の中につくるのか尋ねました。","respondent":"今井待機児童対策担当課長","answer":"初めに、都市公園法の緩和によりまして、今回特区として占用期間として、開設ではなくて、占用期間として認められる期間は１０年間、更新を妨げないとなっております。","id":"exchange-055"},{"speaker":"鈴木（博）委員","kind":"質問","question":"この地図を見ると、ニコンと公園の間に細い道があるのですが、自転車だとかバギーで送迎する場合、まさか公園の中を通るというわけにはいきませんのでここのところを通ることになるのか尋ねました。","respondent":"今井待機児童対策担当課長","answer":"地域住民の方の要望で、計画地と道路のところに少しスペースがあいているのですが、ここが３ｍほどある予定です。前々から自転車や歩く方の安全性ということで住民要望が出ていましたので、公園課の計画ではここを歩道という形にする予定です。","id":"exchange-056"},{"speaker":"飯沼委員","kind":"質問・要望","question":"開設から１０年間、私立というところをぜひ私立でなく、お願いしたいなと思っているのですけれども。ここの箇所というのは別に有害な何かが出たとかではなくて、土壌改良というのはどういう立場でしたのか、ちょっと説明を求めました。","respondent":"今井待機児童対策担当課長","answer":"初めに、施設種別にありますように、こちらは児童福祉法に定める認可保育所を私立で考えております。土壌改良というふうに入っておりますが、ちょうどタイミングが合いまして、それでしたら保育園の設置計画も同時にという形になったと聞いております。","id":"exchange-057"},{"speaker":"飯沼委員","kind":"質問","question":"私立の認可保育所ということなのですけれども、これというのは東京都が土地を貸すということになるのですか。ちょっとごめんなさい、そこがわからないので説明を求めました。","respondent":"今井待機児童対策担当課長","answer":"西大井広場公園は区立の西大井広場公園ですので、区が占用許可を出す立場にあります。","id":"exchange-058"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"子ども・子育て会議で１０年というのが聞き取れなかったので、このプロポーザル、そのほかに求める条件があれば教えていただきたい。建設委員会の話になるかもわかりませんが、東京都のルールで使用していいよというのが出たのでこの話になったという理解でよろしいか尋ねました。","respondent":"今井待機児童対策担当課長","answer":"ただし、先ほどの駐輪場ですとかいろいろなお声をいただくと思いますので、今後区民説明会の中で十分丁寧にお聞き取りしてまいります。この鉛に関しては、保育園の敷地でいただくときには、鉛が取り去られて更地になっているというような認識でおります。","id":"exchange-059"}]},{"id":"topic-06","title":"所管事務調査","agenda":"所管事務調査","exchanges":[{"speaker":"鈴木（博）委員","kind":"質問","question":"ちょっと１点だけお伺いしたい。その３番目の人口比率はほとんど同じぐらいなのですけれども、何で品川区のほうが待機児童数が多いのか。","respondent":"今井待機児童対策担当課長","answer":"ご案内のとおり、例えばその下の近隣の目黒区は品川区より１０％ポイントが低くても、そんなに倍にはならないわけですよね。入園の申込みの状況だと思います。","id":"exchange-060"},{"speaker":"鈴木（博）委員","kind":"質問","question":"では、あまり待機児童数の数だけを絶対値にして評価しても、それほど重みはないということでよろしいのか尋ねました。","respondent":"今井待機児童対策担当課長","answer":"ご案内のとおりいろいろな保育の、その辺を分析した雑誌が出ておりますけれども、委員ご指摘のとおりやはりどのくらいの希望者の方がこのように人口比率で利用されているかという、いわゆる整備率ですね、これも大きな指標になるというふうに認識しております。","id":"exchange-061"},{"speaker":"石田（ち）委員","kind":"質問","question":"全体的な表にして出していただいたのですけれども、これを進めていったというところでの区としての評価と課題は何かを伺いたいと思います。","respondent":"今井待機児童対策担当課長","answer":"平成２２年度、もちろんその前から進めてきたところではありますけれども、区民の方の需要に応えられているというふうに考えております。このようなさまざまな手法をとりながら開設を進めていかないとなかなか課題の解決には至らないという認識でおります。","id":"exchange-062"},{"speaker":"石田（ち）委員","kind":"質問","question":"以前から品川区が皆さんからの質問などでも答えていただいているように、保育園はどんどん建てても財政負担になっていくというようなお話も多々あったのですけれども、この考えはまだあるのか尋ねました。","respondent":"今井待機児童対策担当課長","answer":"その考えに変わりはございません。その経費がかさむのは当然のことですので、その経費の負担をいかに少なくして運営していくかというのは、一つの課題です。","id":"exchange-063"},{"speaker":"石田（ち）委員","kind":"意見","question":"やっぱりまだまだそうはいっても必要だと、さっき新規開設に頼っていくということもおっしゃっていましたけれども、これからもまだまだ開設が必要だというお考えということですねとの意見を述べました。","respondent":"今井待機児童対策担当課長","answer":"先ほど申しましたとおり総合的待機児童対策で進めていく考えで、認証、小規模を含めて開設していくという考えに変わりはございません。子ども・子育て計画の策定の中でまたご意見を伺うところですので、ただ今後も開設、必要な量を確保していくという考えに変わりはございません。","id":"exchange-064"},{"speaker":"浅野委員","kind":"提案","question":"その中で何点かお伺いしたいのですが、誘致をしてつくる場合とそれぞれの事業者のほうからこういうのをやりたいのだけれどもというような提案というのでしょうか、きっかけというのはどのようなものがあるのか説明を求めました。","respondent":"今井待機児童対策担当課長","answer":"あいのもり保育園なんかはそうなのですけれども、土地をいただいた、そこのエリアで公募するという形は一つあります。もう一つは、基本的には品川区のほうは企画提案型という形で進めておりますので、それを随時審査しているという形が一番です。","id":"exchange-065"},{"speaker":"浅野委員","kind":"質問","question":"こちらの場合も似たようなというのでしょうか、あえて認証で保育所としてとかないのか、そのような動きというのは同じようにやっているのでしょうか。その場合、都との関係とか、そういうものはどうなるのか説明を求めました。","respondent":"今井待機児童対策担当課長","answer":"先ほどもご報告のとおり認可と違いまして東京都のほうに事前に資料をご説明して、ほぼ認可保育園と開設のスキームといいますか、それは同じです。企画提案型で進めております。","id":"exchange-066"},{"speaker":"浅野委員","kind":"質問","question":"区としてはいろいろなパターンがあって、さまざまな手を尽くして、事業者と話をしながら進めているということがよくわかりました。反対もあったというような話も伺っておりますけれども、その経過を踏まえながら最近はどのような状況なのかというのを教えてほしいと求めました。","respondent":"今井待機児童対策担当課長","answer":"基本的には今まで住民の方に事前にご説明する中で反対の声をいただくということはございませんでした。私立を含めて平成２５年度頃から、子ども・子育て支援制度の中で、事業者が対応させていただいている事例はあります。","id":"exchange-067"},{"speaker":"浅野委員","kind":"質問","question":"もう一点なのですけれども、ほかでもよく質問しますけれども、荏原地域は保育園が少ないということを何度もここで話をさせていただいています。入りにくいとか、そういう差があるかと思うのですけれども、そこら辺の分布について認識されている中で教えてほしいと求めました。","respondent":"今井待機児童対策担当課長","answer":"五反田地区もまだ多い状況になっておりますので、荏原は人口も多いですし、開設数も少ない中では解決がちょっと難しいかなと考えています。では、やはり品川区の利便性の高さを活かしながら開設については進めていく必要があるというふうに思っております。","id":"exchange-068"},{"speaker":"浅野委員","kind":"意見","question":"電車で例えば大井町まで行って預けられるという方が多分これから出てくるでしょうし、さまざまな選び方というのも出てくるかなと思います。１件でも多くそういう声を、事業者の声を聞きながら適切な場所を選んで建設をしてほしいと求めました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-069"},{"speaker":"飯沼委員","kind":"質問","question":"前にも伺ったりしたのですが、５年以内に何とかするということなのですが、この辺は目処がたつのかどうかというのが１点。その辺を聞いているかどうかというか、やはりそういう株式会社のところの突然の閉園といった中身をどう捉えていらっしゃるのか説明するよう求めました。","respondent":"今井待機児童対策担当課長","answer":"幼保一体施設の計画的な開設につきましては、今現在幼稚園とこれは一体化してつくっているものですので、現在の計画のところで変更はございません。","id":"exchange-070"},{"speaker":"飯沼委員","kind":"質問・要望","question":"そういった意味では認可保育園をきちんと計画的につくっていくことがこの小規模の受け皿をつくっていく責任にもなると思うのですね。だから、そういった意味で、ぜひ公設の区立の認可保育園をこの中に位置づけていっていただきたいなというお願いなのですけれども、いかがか尋ねました。","respondent":"今井待機児童対策担当課長","answer":"基本的には民設民営で進めるところですが、今回のひろまち保育園の公設民営のようにどうしても緊急という場合に公設民営という手法をとりました。今後も公設公営だけにこだわらず、公設民営、民設民営、幅広い視点から認可保育園については開設を進めるものです。","id":"exchange-071"},{"speaker":"飯沼委員","kind":"質問・要望","question":"委員長にお伺いしたいのですが、待機児対策というのはまだこのほかにも、これでおしまいですか。そういった意味では、こういうところもぜひ掘り下げてやっていただきたいなと思うのですが、１回で終わりなのか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-072"},{"speaker":"飯沼委員","kind":"質問","question":"でも、旺盛に所管事務調査が行われていることはとても重要だと思うので、またどこかで質問したときに、事前に委員長にお断りして、その他のところとかで若干取り上げするというのは構いませんか。","respondent":"塚本委員長","answer":"そのときの状況によってなので、その折に検討させていただきたいと思います。","id":"exchange-073"},{"speaker":"大倉委員","kind":"質問・要望","question":"いろいろな取組みをされている中で、待機児童解消を図っておられるのだなということを改めて感じさせてもらいました。どのような考え方をしているのか、しているか、していないかも含めて教えてほしいと求めました。","respondent":"今井待機児童対策担当課長","answer":"屋内階段が避難路として認められなかったのが、高層マンションの中でも保育園が設置できるようになったという事例はあります。私どももそこは十分研究検討しながら２３区合同で検討していかないと、十分その辺を踏まえて区として進めていきたいというふうに思っております。","id":"exchange-074"},{"speaker":"大倉委員","kind":"質問・要望","question":"ぜひいろいろなところでそういった多くの施設がつくれるように、またクリアできるようにしていっていただきたいのですが、東京都でやらなければいけないということで、２３区の中でどういった連携がとられていて、どういったお話になっているのかわかれば説明を求めました。","respondent":"今井待機児童対策担当課長","answer":"これは規制緩和だけのお話ではありませんけれども、十分ご意見を都や国のほうに上げていただいていると、応援していただいているというふうに認識しております。","id":"exchange-075"},{"speaker":"高橋（し）委員","kind":"確認","question":"幼保一体施設の話で、少し伺ったのですが、その方向性というところが一つ。それと、ここの幼保一体施設の拡大はそういった形で進んできている部分も今年度もあると思うのですが、そういったところはどうなのか尋ねました。","respondent":"今井待機児童対策担当課長","answer":"３号の受入枠を確保しながら１号の拡大を含めるなどの提案などの協議をしていきたい、もし提案があればしていきたいというふうに考えております。そういうものをもう一回再検討しながら、他区の事例を見ながら、また民間保育施設の誘致に進めていきたいと考えています。","id":"exchange-076"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"２点目の幼保連携認定こども園、城南小学校のところはわかりました。やはり、新たな仕組みをできるだけ、少しずつでもいいので取り入れていただきたいという要望があります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-077"},{"speaker":"塚本委員長","kind":"質問・要望","question":"私のほうからも少し伺いたいのですが、やはりちょっと近隣の反応でここは無理だなと、こういったことというのは結構あったりしているのでしょうか。計画になって潰れるとかというのではなくて、実態をお聞かせいただきたいと思うのですけれども、いかがか尋ねました。","respondent":"今井待機児童対策担当課長","answer":"はっきりと私どものほうに届いておりませんので、開設にあたって、その企画提案の段階でここの地域はということで除外するということはございません。","id":"exchange-078"}]},{"id":"topic-07","title":"所管質問","agenda":"所管質問","exchanges":[{"speaker":"石田（ち）委員","kind":"質問","question":"この定時制高校廃止に反対をという質問だったのですけれども、定時制高校存続という考えが区にあるのかどうかということをお聞きしたいと思います。","respondent":"村尾教育総合支援センター長","answer":"第４回定例会でもご答弁いたしましたとおりなのですけれども、現在区内の生徒にとって進路先の一つであるということは事実です。都立の小山台高等学校定時制の存続等につきましては、この辺につきましては、情報収集に努めてまいりたいというふうに考えているところです。","id":"exchange-079"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/184577?Template=document&Id=4872#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=9&TermStart=2015-01-01&TermEnd=2015-12-31"}],"sourceMeta":{"pages":0,"characters":59112,"voices":210}},{"id":"h27-20151201-5","meetingId":"h27-cm12","date":"2015年12月1日","dateIso":"2015-12-01","committee":"総務委員会","time":"午前１０時００分～午後 ２時０４分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を57件整理しています。","topics":[{"id":"topic-01","title":"第８４号議案 平成２７年度品川区一般会計補正予算","agenda":"第８４号議案 平成２７年度品川区一般会計補正予算","exchanges":[{"speaker":"中塚委員","kind":"質問","question":"第４回定例会の補正なので、補正には載っていませんけれども、どういうふうに判断されたのか伺いたい。３月末まで予算が足りなくて、必要な手立てをとっているということなのか、伺いたいと思います。","respondent":"秋山財政課長","answer":"実際の当初予算、今回のタイミングでは出ておりませんが、そういう予算の中で着実に進めているというふうに考えているものです。条件の中には、当初の予算の範囲内で補助を行うという条件をつけてやっておりますので、その辺で対応をとっているです。","id":"exchange-001"},{"speaker":"中塚委員","kind":"質問・要望","question":"その中身を伺いたいというのが１点と、とりわけ民間の保育園で働いている方の賃金について大変だというお話をよく伺うのですけれども、背景だったり。それに対する手立てということだと思いますけれども、そこの関係を伺いたいと思います。","respondent":"工藤選挙管理委員会事務局長、秋山財政課長、柏原企画調整課長","answer":"私のほうから、選挙人名簿システムの改修費の件につきましてお答えをいたします。例えば選挙人名簿を年に４回作成するわけですけれども… 品川区においても、保育の需要を満たすだけの人材を確保していくという面で必要なことだということで、今回はそういうことになっております。それからまた… 初期費用が１万５,０００円ほどかかるのですけれども、その半分を区のほうで補助しますといった事業ということで、今年から始めたというものです。","id":"exchange-002"},{"speaker":"中塚委員","kind":"質問・要望","question":"設計委託ということを早めていきたいというご説明がありましたけれども、リバーステーションなので、川の駅ですか。今後、この公園だったり、川沿いを使って、どういう展開を展望されているのか、事業展開を含めてご説明ほしいと求めました。","respondent":"柏原企画調整課長、秋山財政課長","answer":"今後の展開です。検討を今していますが、情報として、広がっていくような形で検討を進めていきたいというふうに思ってあります。舟運につきましては、２０２０年のオリンピック・パラリンピックを目指して、いろいろなところが舟運の検討を進めてあります。","id":"exchange-003"},{"speaker":"あべ委員","kind":"質問","question":"今、２０２０年を目指してというお答えがあったのですけれども、ちょうど半年のスケジュールの違いということになってくるのですか。これがあるからこのときにやる、これまでに間に合わせたいのか、そういうスケジュール感というのはあるのか尋ねました。","respondent":"秋山財政課長","answer":"リバーステーションですけれども、オリンピックが平成３２年の夏に開催をされます。今のところの予定では、前年の１２月の開港を目指して、補正予算で出させていただいたです。","id":"exchange-004"},{"speaker":"あべ委員","kind":"質問・要望","question":"それは１点、確認です。要望なのですけれども、先ほどの話ですと、ぜひご希望がある限りは継続してほしいと求めました。","respondent":"秋山財政課長","answer":"工事になりますと、いろいろな要素が絡まってくるので、これだけでということではないのかもしれませんけれども、一応、平成３２年の１２月開港を目指して、今回、出させていただきました。","id":"exchange-005"},{"speaker":"須貝委員","kind":"質問","question":"これはやはり何かの方法で、実際どれだけの人が見ているのだろうというようなものは、数字的にあるのでしょうか。そうすると、相当の数が、区のほうとしても正確な把握はされていないというふうに我々は思っていないといけないのか尋ねました。","respondent":"柏原企画調整課長、工藤選挙管理委員会事務局長","answer":"２０万８,０００余の世帯数に対して、区民チャンネルの視聴可能でいいますと１６万５,０００世帯ということですので、７９.２％の視聴可能世帯数。概ね８０％程度といった状況です。 私ども、選挙人名簿につきましては、年に４回、３月、６月、９月、１２月に、１日を基準日として確定しているものです。そういった部分では、先ほどのマイナンバーとは違うということではないかというふうに考えてあります。","id":"exchange-006"},{"speaker":"須貝委員","kind":"質問・要望","question":"確認したかったのは、やはりきちんとやらなければいけないというふうに思ったので、質問させていただきました。何か倒壊だというときは、やはりその辺の普段の視聴率というところも確認をしていただきたいし、普及啓発ということに努めてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-007"},{"speaker":"あべ委員","kind":"質問","question":"朝７時になると、何か教えてくれたりとか、このＣＡＴＶ事業という括りでよろしいのでしょうか。どうなのか尋ねました。","respondent":"秋山財政課長","answer":"こちらは今年の４月から始まった事業ですので、現在、ケーブルテレビという事業の中に入れているというふうに理解しているものです。","id":"exchange-008"},{"speaker":"本多委員","kind":"質問","question":"１０ページ、１１ページの歳入、国庫補助金のところなのですけれども、選挙人名簿システム改修費補助金なのですが、１９４万４,０００円の２分の１ということでわかるのですけれども、１９４万４,０００円の算出根拠だけ説明を求めました。","respondent":"工藤選挙管理委員会事務局長","answer":"システムの改修の費用というものがございまして、こちらのほうが約１００万円ほどです。そういった部分の人件費分というのがありまして、これが約九十数万円というのが大きな算出の根拠です。","id":"exchange-009"},{"speaker":"大沢委員","kind":"質問","question":"待機児童対策は当初からの話、数年来の懸案ですので、ここら辺のところをなぜ当初予算に持ってこないのか。気がついていないということはないと思うのですけれども、そこら辺の事情が知りたいので、おわかりになる程度で説明を求めました。","respondent":"秋山財政課長","answer":"今回の保育園関係の賃金改善等の補正ですけれども、これは９月の補正にも同様なものを出しています。今回メインは東京都ですけれども、東京都がこの時期に支出が確実になるという情報がありましたので、今回入れさせていただいたという状況です。","id":"exchange-010"},{"speaker":"あくつ副委員長","kind":"質問・要望","question":"先ほどもご答弁がありましたけれども、これについてもう一度、将来的な展望を教えてほしいと求めました。結局３人しか、という言い方はご自身の判断ですから、この辺についてのご見解を伺いたいと思います。","respondent":"柏原企画調整課長","answer":"この事業の今後の展開をどう広げていくのかというのは、まさに今、検討しているといったところです。そういったところを見ながら、どういった展開ができるのかというのは検討を進めていきたいというふうに思います。","id":"exchange-011"},{"speaker":"あくつ副委員長","kind":"確認","question":"検討を進められるということで、質問の順番を間違えてしまったのですが、これも確認をさせてください。その確認を、わかる範囲で教えていただけたらと思います。","respondent":"柏原企画調整課長","answer":"当初の予算では４００件ということで進めておりました。２３区共通というよりは、今、品川ケーブルテレビで使っているという状況です。","id":"exchange-012"}]},{"id":"topic-02","title":"新地方公会計制度に基づく財務４表","agenda":"新地方公会計制度に基づく財務４表","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"幾つか伺いたいと思うのですけれども、1)の行政コスト計算書で経常行政コストというところがありますけれども、２番目に高いということなのか。区の非常勤職員というのが、ここでいう経常行政コストの分類だとどこに入るのか、解説も含めてご説明ほしいと求めました。","respondent":"秋山財政課長","answer":"それから、非常勤、指定管理等については、費としては物件費等に入って、委託費等は物件費等に算入されているです。この辺は、区の普通の決算でも、同じような振り分けをしているものと同じものです。","id":"exchange-013"},{"speaker":"中塚委員","kind":"質問・要望","question":"実際は、議会は６億何がしですけれども、こういうものというのは、どういう意図なのかというところを伺いたいと思います。指定管理は後から伺ったにしても、同じようなものにしないと比較はできないのかと思うのだけれども、物件費かというように思うのです。","respondent":"秋山財政課長、中山企画部長","answer":"他団体との比較のために、人件費ではなく物件費にそういう委託料については集計をして、振り分けて計算をするということになってあります。ただ、それは通常の直接した雇用人件費ではなくて… 指定管理の部分というのは、物件費の中で、各分野に応じてなされているというのが今の説明かと。繰り返しになりますけれども、基本的に全国的な表記の中でやっているということはご理解いただきたいと思います。","id":"exchange-014"},{"speaker":"中塚委員","kind":"質問・要望","question":"整理していただきたいのですが、まさに人の部分がその中では大きくなってくるわけですから、説明するよう求めました。","respondent":"秋山財政課長","answer":"直接の非常勤については人件費に入っているところです。","id":"exchange-015"},{"speaker":"吉田委員","kind":"質問","question":"伺いたいことはいっぱいあるのですけれども、割とそういうものが推奨された時期にいち早く取り組まれたと思うのです。そのときにどう変わられてきていて、これからは複式簿記と発生主義の記帳が義務付けられるというふうに伺ったのですが、今後どう変わっていくのか。","respondent":"秋山財政課長","answer":"したがいまして、詳細なものというのは、その中身を見るというのは、かなり難しいというものです。平成２６年に推進に関する研究会報告ということで、平成３０年度以降、導入するという形で検討を進めているという状況です。","id":"exchange-016"},{"speaker":"吉田委員","kind":"質問","question":"では、今後は発生主義・複式簿記によるバランスシートになるというふうに理解してよろしいのか尋ねました。","respondent":"秋山財政課長","answer":"一応、この補正のときにもお話をさせていただいているのですけれども、今後、システムの更新等、かなり手間もかかりますので、発生主義・複式簿記の会計に変わっていくという形です。","id":"exchange-017"},{"speaker":"吉田委員","kind":"質問","question":"今現在の品川区の中に、この項目ではこれだけ減価償却していますというものが、どこかで見える形になっているのでしょうか。もっと具体的に言うと、決算の表の中に、どこに減価償却された分が出てきているのか、私には見えなかったので、それを説明するよう求めました。","respondent":"秋山財政課長","answer":"バランスシートをつくるために減価償却という考え方を入れていきますので、要するに、つくったお金だけを積み上げていくと。建物とか資産のフルコストというものが正確に見えて、評価もできていくという流れになっていくというふうに考えております。","id":"exchange-018"},{"speaker":"吉田委員","kind":"質問","question":"何か私たちの感覚だと、減価償却として累計されているものが別にあり、さらに基金があるのかというふうに読めてしまったのです。ある意味、一般の会計を見慣れている区民の皆さんには、品川区の財政状況がよりよくわかるようになるというふうに理解してよろしいのか尋ねました。","respondent":"秋山財政課長","answer":"今やっている財務４表につきましては、バランスシートには税収は載ってきませんし、企業でのバランスシートというものと若干考え方が違います。","id":"exchange-019"},{"speaker":"吉田委員","kind":"質問","question":"どれくらい引き当てしているのですかと言ったら、いや、それこそバランスシートには貸倒引当金がきちんと計上されているのです。ぜひ、いい形で新公会計制度が進んでほしいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-020"},{"speaker":"あべ委員","kind":"質問・要望","question":"私も全体を把握できていない部分があるのですけれども、今回、これから平成３０年度を目途に発生主義の複式簿記に変えていく。あるいはどうやって役立てることが期待されていて、どう区の政策判断に利用できるようになるのかという部分を教えていただきたいのです。","respondent":"秋山財政課長","answer":"その自治体の持っている、連結できるということで、その全体の評価ができるというところが大きなメリットではないかというふうに考えてあります。それは、その施設の存続であるとか、そういう政策判断に活用できるのではないかというふうに考えております。","id":"exchange-021"},{"speaker":"あべ委員","kind":"質問","question":"今後、新しい方式を入れることによって、ある年から数字が変わっていって縦の比較ができなくなるとか、そういうことはあるのでしょうか。こういうものは、他の自治体と比較しながら、品川区の位置を確かめるという面もあると思うのですけれども、どんな感じなのか尋ねました。","respondent":"中山企画部長","answer":"例えば今財政課長が説明した中で、場合によっては複合化を図るとかというふうな指標も出てくるというのは、運用上の部分があります。そういう中、できるだけ品川区に合った、メリットを活かせるような有効活用をやっていこうというふうに考えているところです。","id":"exchange-022"},{"speaker":"あくつ副委員長","kind":"質問","question":"個別のことからまず伺いたいのですけれども、別紙１の普通会計の行政コスト計算書の１で、人件費の中の消防で２億円近い、１億９,９１９万８,０００円とあるのですが、これは消防団の関係なのか尋ねました。","respondent":"秋山財政課長","answer":"これは防災がこの振り分けの中に、消防の部分の中に入ってきますので、防災費の一部がここに入ってきているです。","id":"exchange-023"},{"speaker":"あくつ副委員長","kind":"質問・要望","question":"再三、我が会派からも一般質問、代表質問等でも、予算、決算でも、何度もこの新公会計システムについてはご要望させていただいてきました。現状は動いているのかどうかとか、どういうものをイメージすればいいのか、その辺を教えてほしいと求めました。","respondent":"立川経理課長","answer":"簿価の台帳の開始の価格というものをどう決めるかというのは、例えば道路につきましては、実際は取得価格イコール簿価というふうな考え方になります。そのまま１円でいいということになりますと、区としましても、資産の算定ということを進めていくところです。","id":"exchange-024"},{"speaker":"あくつ副委員長","kind":"質問","question":"非常に計算の仕方が難しい、確かに道路は売れないというのもわかるのです。公共施設として、こういうご質問をすると、全体像としては今この公共施設というのはどれぐらいの数になられるのか尋ねました。","respondent":"立川経理課長","answer":"手元に資料を今日は持ってきていないのですけれども、実際、施設に関しましては、現在、公有資産の台帳がありますので、そちらのほうに土地とか建物等の台帳を整備していますので、そのベースの数が、まず開始時の財産の数というふうにおよそなってくるかというところです。","id":"exchange-025"},{"speaker":"あくつ副委員長","kind":"質問","question":"もちろん減価償却の計算ができないという考え方ができるようにならなければいけないわけなので、そういったものが一覧になるというものが来年できるということで、これは公開になるということでよろしいのか尋ねました。","respondent":"立川経理課長","answer":"どのように公開するかというのは、これから詰めていくところですけれども、現在の公有資産台帳などは公開をしていますので、同様な取扱いになるというふうには考えております。","id":"exchange-026"},{"speaker":"あくつ副委員長","kind":"質問","question":"この公会計制度、発生主義・複式簿記に移行をする。自治体職員の研修とかソフトウエアの提供等も行っているとあるのですが、その辺について、現状どのように進められているのか説明を求めました。","respondent":"秋山財政課長","answer":"その辺でお金がかかったりとかということで、この辺はどう取り組んでいくかというのは、私どもの会計システムの公開とあわせて検討をしています。それから財政支援なのですけれども、財政支援に関しては、交付金対応ということで。","id":"exchange-027"},{"speaker":"あくつ副委員長","kind":"質問","question":"一昨年の財務４表の総務委員会の質疑を読ませてもらったのですが、あと議会でのこの資料の活用をどうしていくのだというところがありまして、詳細な複式簿記・発生主義でつくったものが我々にも提供されるということでよろしいのか尋ねました。","respondent":"福島会計管理者","answer":"先ほどから言っていますように、新公会計制度を導入するのは、区民への説明責任が一番大きいものですので、そういった意味では、議会のほうに提出できるようなものに変えていきたいというふうに思っております。","id":"exchange-028"},{"speaker":"あくつ副委員長","kind":"意見","question":"行政は行政で活用されて、議会は議会でまた活用する能力をつけなければいけないと思いますので、しっかり取り組んでいきたいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-029"}]},{"id":"topic-03","title":"特定個人情報保護評価","agenda":"特定個人情報保護評価","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"今日のこの場では１点だけ、ここがどういう意味だったり、スケジュールなのかというのを伺いたいと思います。スケジュールも含めて伺いたいのと、その辺がよくわからないので、ご説明ほしいと求めました。","respondent":"仁平情報推進課長","answer":"実施時期のほうは、システム的には、個人情報の連携テストとかをする前には必ず評価を行うという形になってあります。この２件がありますが、こちらのほうは全項目評価ということで、それに基づいた後でなければ国のほうへの提出ができないという形になっております。","id":"exchange-030"},{"speaker":"中塚委員","kind":"質問","question":"国のほうの保護委員会で、今メンバーが５人ということですけれども、そこで監視する委員会というか、チェックする委員会ということなのでしょうか。５人でどうやってチェックするのかというのが、まず一つ伺いたいのと、中身をもう少し伺いたいと思います。","respondent":"仁平情報推進課長","answer":"大別しますと２つの扱いになっておりまして、まず、その内容を特定個人情報保護委員会が直接評価するというような形になっております。","id":"exchange-031"},{"speaker":"中塚委員","kind":"質問・要望","question":"つまり、実際に上がってくるものを一件一件審査をするのではなくて、何らかの事件があったときにここの保護委員会の権限で調査に入るということなのでしょうかという確認と、その調査に入るというのがどういう作業になってくるのか、最後にそこをご説明いただきたい。","respondent":"仁平情報推進課長","answer":"これはあくまでも各自治体で評価をした上で制度に取り組んでいるという形になっておりますけれども、まず、これから運用が始まります。手順等につきましては、報告の形が見えてこないところはありますけれども、委員会の規則上はそういう形になっております。","id":"exchange-032"},{"speaker":"あべ委員","kind":"質問・要望","question":"ちょっと全体像を確認させていただきたいのですけれども、つまり地方税と住民基本台帳については既に終わっていると。それから基礎項目については、対象となる１０万人未満が２３件あって、その２３件全てを実施したということでよろしいのか尋ねました。","respondent":"仁平情報推進課長","answer":"現在、例えば９万５,０００人ぐらいのデータになるということで、今現在は基礎だということの評価になっているものです。例えば件数が１０件だったり１００件だったり、特定個人情報に該当しますので、全庁的にきちんと個人情報は管理していくということになります。","id":"exchange-033"},{"speaker":"あべ委員","kind":"質問","question":"ということは、重点項目と比べて少ないのは、リスク対策について評価をしていないということなのでしょうか。それだけ聞くと、リスク対策評価はすごく意味があると思うのですけれども、それはどういう考え方になるのか尋ねました。","respondent":"仁平情報推進課長","answer":"まずは全項目、重点項目と言いましても、基礎項目から開始します。区のほうはきっちりと事務別にリスク対策の評価をして、運用上、今後問題ないというような判断のもとに行っているものです。","id":"exchange-034"},{"speaker":"あべ委員","kind":"質問","question":"それからしきい値が、それこそ９万５,０００人ぐらいのものがもうあるとおっしゃったのですけれども、どういう感じになっているのでしょうか。例えばこの時期に年１回必ずやるとか、物によって違うとか、そういう対象人数のとり方を説明するよう求めました。","respondent":"仁平情報推進課長","answer":"その時点で、例えば重点項目のしきい値より上がったというのであれば、重点項目評価を実施するという手順になっております。こういう部分の変更に入った場合には、先ほど申し上げましたような第三者評価をもう一回受けて国へ報告するという手順になっております。","id":"exchange-035"}]},{"id":"topic-04","title":"伊藤学園大空間落下防止対策その他工事請負契約","agenda":"伊藤学園大空間落下防止対策その他工事請負契約","exchanges":[{"speaker":"あべ委員","kind":"意見","question":"一応、やはり言っておきたいのですけれども、この５社が入札をしていて、落札をした１社以外が全て辞退している。これは形としては入札なのかもしれないのですけれども、この状況というのをどう解釈されていますかとの意見を述べました。","respondent":"立川経理課長","answer":"こうした中、新規受注の抑制や選別受注などをして対応して、そういった対応をとらざるを得ないような状況にあるというふうに認識するところです。１社でも実際に札を入れてくれたということは、予定価格も含め、適正な工事請負契約ができたというふうに考えているところです。","id":"exchange-036"},{"speaker":"あべ委員","kind":"質問","question":"どうしても手いっぱいになってしまって、１社ずつ回していくような形で、意図的なものかどうかは別として。これでは入札制度という面では、ちょっと骨抜きになっているように見えるのですが、その辺に対してはどうお考えか尋ねました。","respondent":"立川経理課長","answer":"間口を広げるといったご質問だと思うのですけれども、２３区の各区の経理課長が年数回集まって、経理課長会を実施しています。近隣区も含めて指名競争してみようかといったような取組みというのは、若干ですが、今年度はやったです。","id":"exchange-037"},{"speaker":"あべ委員","kind":"質問","question":"飛び込みで１回だけというのではなくて、例えば東京なり品川あたりで、もう少し間口を広げてみる仕組みをとってみる。もう少し小さいところから入っていくということも含めて、そういったことも検討してみてはいかがかと思いますが、いかがか尋ねました。","respondent":"立川経理課長","answer":"区内事業者の育成支援ということを主眼として、入札の制度につきましては基本としていきたいというふうに考えておりますので、またこれについて検討が必要な場合は考えていきたいというふうに考えているところです。","id":"exchange-038"},{"speaker":"吉田委員","kind":"質問","question":"すごく素朴な質問なのですけれども、どこでも慢性的な人手不足というふうに、こういう業界では聞いております。その育成のつもりが、そういうことが起きはしないかとちょっと心配になるのですけれども、その辺のことというのはどうなのか尋ねました。","respondent":"立川経理課長","answer":"実際に札を入れるか入れないかということを各事業者は考えているというふうに思いますので、概ね予定どおり執行できているという状況ですので、その辺は各事業者が積極的に人材の確保というところに努めていくべきものというふうに考えるところです。","id":"exchange-039"},{"speaker":"須貝委員","kind":"質問・要望","question":"やはり企業共同体としてやっているわけですから、それは本当に区内業者の支援、育成とちょっとかけ離れているのではないかというのは私も思うのです。意見だけです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-040"},{"speaker":"あくつ副委員長","kind":"質問","question":"あれだけさんざん騒がれた体育館の工事ということですから、多分、今の考え方だと思うのです。その辺についてのお考えを伺いたいと思います。","respondent":"立川経理課長","answer":"いざ震災等があったときに、実際に頼りになるのは、地域の建設業者に初期の対応をしてもらうとか。支援していくかということを各地方自治体のほうにも要請していますので、地元区内業者中心に入札、発注をかけていくという考えではあります。","id":"exchange-041"}]},{"id":"topic-05","title":"日野学園大空間落下防止対策その他工事請負契約","agenda":"日野学園大空間落下防止対策その他工事請負契約","exchanges":[{"speaker":"あべ委員","kind":"確認","question":"確認のためにお伺いしたいのですけれども、１.５倍近く違うのですけれども、これは工事の金額のままの違いということで考えてよろしいのでしょうか。それぞれ現状に合わせて適切な工法をとっていらっしゃると思うのですけれども、一応ご説明ほしいと求めました。","respondent":"立川経理課長","answer":"施工場所と、その面積と、積算した結果がこの金額の差となっているところです。","id":"exchange-042"}]},{"id":"topic-06","title":"所管事務調査","agenda":"所管事務調査","exchanges":[{"speaker":"あべ委員","kind":"質問・要望","question":"ざっくりとでも、大まかにつかんでいらっしゃるか、あるいはそういう視点があるかどうかというのを伺いたいのが１点。今は３７万人ぐらいですか、私も登録をしているのですけれども、あまり来ないという印象があります。","respondent":"中元広報広聴課長、仁平情報推進課長","answer":"申し訳ございません、数字のところの数値を今すぐには用意をしてございませんで、この場ではお答えができない状況です。どのようにネットワークを組んでいけるかというのは、研究、検討をしていきたいと思っているところです。 私のほうから、Ｗｉ-Ｆｉのご質問についてお答えします。いかんせん、先ほどご説明しましたように、相互乗り入れみたいな形がとれないかというようなことで動いているというような話は伺っております。","id":"exchange-043"},{"speaker":"あべ委員","kind":"提案","question":"その他の、双方向のＳＮＳというのは、今のところお考えはないのでしょうか。時々提案もしているのですがとの意見を述べました。","respondent":"中元広報広聴課長","answer":"双方向のところについては、現在のところではまだ予定はしてございません。他区で実施されているところも、フェイスブックをやられていても書き込みは受けていなかったりというところで運営されていると聞いてあります。","id":"exchange-044"},{"speaker":"あべ委員","kind":"意見","question":"一旦はここまでといたしますけれども、こういったツールを広報だけじゃなくて、広聴のほうにどう活かせるかというのも、今後は課題かと考えています。私ばかりしゃべっているので、一旦、ここで切りますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-045"},{"speaker":"中塚委員","kind":"質問","question":"広報広聴課といいますか、区のＰＲの目的、主眼をどう考えているのかを伺いたいと思います。伺っていますが、その検討状況と、例えばＡ４判というのはどういうふうに捉えていらっしゃるのか伺いたいと思います。","respondent":"中元広報広聴課長","answer":"知っていただかなければ、そのサービスを利用していただくことができませんので、そこの周知に努めてまいりたいということで行っているところです。現段階では、Ａ４サイズ化というところは、特にまだ検討等もしていないところです。","id":"exchange-046"},{"speaker":"中塚委員","kind":"質問","question":"その点改めて伺いたいのと、今の月３回とは別に年何回か、そういう視点はあってもいいかと思うのです。よりツールとして効果のある情報というのを、区はどんなふうに今は考えていらっしゃるのか、そこの視点をあわせて伺いたいと思います。","respondent":"中元広報広聴課長","answer":"メールでもご意見をいただき、主管課と連絡を取り合いながら、丁寧な回答に努めているところです。情報拡散の上では大変有効な手段と考えているところですので、今後、前向きに取り組んでまいりたいと思っているところです。","id":"exchange-047"},{"speaker":"中塚委員","kind":"質問","question":"イベント情報も、すごくおもしろいとは思うのですけれども、そういうのは、正直に言うと、へーという感じなのです。そういうところの層を、反応を見ながら積み上げていくといいのかというふうに思うのですけれども、最後はそこの考えだけ伺いたいと思います。","respondent":"中元広報広聴課長","answer":"所管のほうでも、そのような相談の事業をやっているというところを、まずツイッターのほうで情報発信をしていくところに努めたいと思います。そちらとも連携を図りながら、なかなか通常業務ですので、そこのところは今後ほかの所管にも啓発をしてまいりたいと思ってあります。","id":"exchange-048"},{"speaker":"須貝委員","kind":"質問・要望","question":"わがままなご意見やご苦労もあると思いますが、慌てずに、慎重に、私はこの事業を進めてほしいと求めました。みんなそれぞれが違う情報を欲しがって、そうすると結局、膨大な量になってしまうと思いますから、慎重にこれからもやってほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-049"},{"speaker":"吉田委員","kind":"質問","question":"オープンデータのことについて伺いたいのですけれども、では、もっとこういう活用もできるのではないかというイメージの広がりとかもあるのです。今後どうなるのかは不確定ですけれども、そこの活用というところを考えている、何か具体的な検討とかはされているのか伺いたいと思います。","respondent":"仁平情報推進課長","answer":"それと我々、つくっておりまして課題となっておりますのは、この先どういうふうに使われていくのかという評価がなかなか難しいところがあります。連携といいますか、検討課題にはなっておりますので、オープンデータの活用に向けて取り組んでいきたいと考えているところです。","id":"exchange-050"},{"speaker":"吉田委員","kind":"質問","question":"品川区の動きを察知して、こういうことが可能ではないかとか、何かそういうような働きかけみたいなものはないのでしょうか。そういうところで、そういう研究とかを進めているような方たちとかを少し探ってみるとか、そういう働きかけは今のところどうなのか尋ねました。","respondent":"仁平情報推進課長","answer":"どういう取組みといいますか、きっかけをどうやって持ってくるかとか、担当の間では検討をしています。具体的に協働して何か動きがとれればとは考えるところでありますけれども、まだ、そういう方向性で検討をしていきたいとは考えております。","id":"exchange-051"},{"speaker":"吉田委員","kind":"質問・要望","question":"そういう問題意識を持っていらっしゃるということなので、ぜひその方向で進めていただけたらいいなというふうに思います。有効活用への突破口が開けると、後は割と広がっていくということもあるのではないかと思いますので、ぜひ進めてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-052"},{"speaker":"本多委員","kind":"質問","question":"例えば事業者から見て重要なデータが欲しいとか、情報が欲しいというような視点というのは、どういう感じになっているのでしょうか。今は一般の方が、観光だったり災害時だったり生活に直結したことの情報入手ですけれども、その辺までというのは難しいのか尋ねました。","respondent":"中元広報広聴課長","answer":"ただ、あと所管のほうで、それをデジタルデータの形で持っているかどうかというところが大きな課題かと思います。もともと持っている、もちろん、出すべき情報というものはホームページのほうで公開をしていきたいと考えているところです。","id":"exchange-053"},{"speaker":"あくつ副委員長","kind":"質問・要望","question":"桑村副区長が情報統括責任者ですか、いわゆるセキュリティですとかハード、主にセキュリティのところで総務委員会でよくご説明を受けるのです。今はそういう役割も実は含んでいるのかどうかとか、一応、そこについての今後の展望と役割について教えてほしいと求めました。","respondent":"桑村副区長","answer":"いわゆる情報管理の面は、あるいは情報の事故が起きたときにどういう対応をするかとか、そういうようなものが強いというのが事実であります。今日、むしろある程度電子化を進めていく上で新しいものにどう対応していって、情報をお伝えするか。","id":"exchange-054"},{"speaker":"あくつ副委員長","kind":"質問・要望","question":"これはご答弁は別にいいのですけれども、また、各委員からも出ていますので、進めていただきたいというのが一つ。非常に大事になってくるのではないかと思うのですが、そこについてのお考えをちょっとお聞かせほしいと求めました。","respondent":"中元広報広聴課長","answer":"区民ということではなくて、品川区の区域に、そのときその携帯電話会社のキャリアを持っていればその方のところに災害情報が届くというサービスの災害協定を結んでいるところです。","id":"exchange-055"},{"speaker":"あくつ副委員長","kind":"質問・要望","question":"そういったものを今後ぜひ品川区も取り入れていただきたい。絶対に聞き漏らしたり、見漏らしたりすることがないようなものをという意味で質問をさせていただきましたが、いかがか尋ねました。","respondent":"中元広報広聴課長","answer":"今後とも、そのようなプッシュ型のものを、メーカーからの提案等も来てありますので、ありました際には積極的に取り組んでまいりたいと考えているところです。","id":"exchange-056"},{"speaker":"あべ委員","kind":"質問・要望","question":"例えば意見を伺うときに電子アンケートを使ってみたり、大勢の方、いろいろな立場の方からお話を伺えるようにしてほしいと求めました。これもできれば、少しお考えを伺えればと思います。","respondent":"中元広報広聴課長","answer":"１点目の全体像の把握のところですが、漏れがないように、今後の課題として検討を進めていきたいと思います。電子アンケートの活用についても、今後の課題として検討してまいりたいと思っているところです。","id":"exchange-057"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/858739?Template=document&Id=2034#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2015-01-01&TermEnd=2015-12-31"}],"sourceMeta":{"pages":0,"characters":57260,"voices":157}},{"id":"h27-20151202-14","meetingId":"h27-cm12","date":"2015年12月2日","dateIso":"2015-12-02","committee":"行財政改革特別委員会","time":"午前１０時００分～午後 ２時５１分","status":"正式会議録","sourceType":"formal","overview":"行財政改革特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を91件整理しています。","topics":[{"id":"topic-01","title":"国家戦略特区に関すること","agenda":"国家戦略特区に関すること","exchanges":[{"speaker":"安藤委員","kind":"質問・要望","question":"７月３１日の内閣府・厚労省通知について説明がありましたが、国がどういう問題意識でこういう通知を出したのか、もう少し詳しく伺いたいと思います。テロや感染症対策等も書かれておりますが、具体的にどのようなことを求めているのか、通知の中身を伺いたいと思います。","respondent":"柏原企画調整課長","answer":"こういった不安を除去する観点といったところから、苦情等に対しては適切に対応する、苦情相談の窓口を設置するであるとか。違法行為に対する対応をするようにしなさいということで、それを条例の中に謳うことができますというところを通知として出したというものです。","id":"exchange-001"},{"speaker":"安藤委員","kind":"質問","question":"ちょっと伺いたいのですけれども、オリンピックまでの期間限定にするという考えなのか、伺いたいと思います。それと先ほど通知の話を質問させていただいたのですが、通知を受けて区としては何を実施するのかということもあわせてお伺いしたいと思います。","respondent":"柏原企画調整課長","answer":"こういったところへの対応というのは１つあります。そういったものを見ながら、品川区の場合どういった形の、品川区版の条例というのができ得るのかというものを検討しているといったものです。","id":"exchange-002"},{"speaker":"安藤委員","kind":"質問","question":"国としては別組織という話ですが、特区とは別に法改正を考えているということなのでしょうか、そこら辺をちょっとお伺いします。一定旅館業としての安全の確保ですとか、簡易宿泊所を整備していくということでは不十分だというふうに考えていらっしゃるのか、そこもお伺いします。","respondent":"柏原企画調整課長","answer":"法令関係の規制緩和に対する全体の部分の考え方を検討していますので、全く同一のものではないのですけれども、関連は当然していると認識しています。","id":"exchange-003"},{"speaker":"安藤委員","kind":"質問","question":"責務、こうした近隣住民への安全・安心の確保・担保についてはどう考えるかというのを、２つ目にお伺いします。３つ目としてはこの既存産業への調整ですとか、話し合いのところ、ここを伺います。","respondent":"柏原企画調整課長","answer":"仮に条例をつくるといったところになったとしても、どこまで書き込むかというのは、中身については今後の検討だろうと思ってあります。中身のスキームについても、旅館業法の特例について検討していきますというお話をしている段階ですので、今後の検討だということで。","id":"exchange-004"},{"speaker":"安藤委員","kind":"質問","question":"やはり条例化には慎重であるべきだと思いますし、きちんとした宿泊者や区民への安全・安心を担保して、それができるのかと。それを設けない限りは条例化すべきではないし、あと特例ですか、特区活用というのも慎重であるべきだという意見を述べします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-005"},{"speaker":"伊藤委員","kind":"質問・要望","question":"つまり民泊の問題は、もう既に明らかになっているわけであって、ここに書かれている認定事業者というのはそういう方々を指すのでしょうかという確認。報告を求めていくとか、そんなことも求めていくべきと思うのですが、お考えを説明するよう求めました。","respondent":"柏原企画調整課長","answer":"ちょっと説明が足りなくて申し訳ございませんでした。諸々ありますので、様々な宿泊のためのいろいろな手法といいますか、手続き等々はとっていくべきなのだろうと思ってあります。","id":"exchange-006"},{"speaker":"伊藤委員","kind":"確認","question":"ここで認定事業者になっていくということなのでしょうかという確認と、それから、それを誰が認定をして承諾をしていくのか。なので、認定事業者をどこに登録していくか、それからその指導監督はどこかということについて説明を求めました。","respondent":"柏原企画調整課長","answer":"ただし、後段にご質問ございましたように、これは条例事項になってきますので、条例で決め事をします。さらに詳細については区のほうの規則なり何なりということで決めてまいりますので、区でいいますと区長という形になってまいります。","id":"exchange-007"},{"speaker":"伊藤委員","kind":"意見","question":"だから、やはりそれは認定外のものについては法律は難しいと思いながら言うのだけれども、そこにより多くのものが集中する気がするのです。なので、今条例を検討していくということを聞いたので、その中でもそういうことについてのお考えを説明するよう求めました。","respondent":"柏原企画調整課長","answer":"そのトラブルに対してどう防止していくのだというのは、これはこの適用除外というところを超えたところでの課題でもあるのだろうと思ってあります。","id":"exchange-008"},{"speaker":"伊藤委員","kind":"質問","question":"やはりこの委員会も含めた様々な議論をぜひ参考にしていただいて、私たちとしては民泊は当然進めるべきだと思っています。ですから、私たちの指摘させていただいた様々な内容を十分に対処しきれるような仕組みをつくっていただいて進めていってください、お願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-009"},{"speaker":"たけうち委員","kind":"質問・要望","question":"それともよく条例で上書きして、ちょっとこれと外れるような場合のものまでできるのかどうかということですね、それが２点目です。このオリンピック・パラリンピックまでに何か動きというのですか、そういうのはどの辺まであるのかというのを教えてほしいと求めました。","respondent":"柏原企画調整課長、高山生活衛生課長","answer":"主にはその期間の部分であるとか、それから手数料の部分ですね、それはこの部分で謳っておくというのは原則的なところであると認識しています。ここで書き込むべきものなのか、もっと上のレベルでやるべき話なのかというのは… 宿泊稼働率に絡みまして、区内の旅館等の申請の関係で少しお話をしますと、先ほど他の委員からもお話がございました簡易宿泊所ですね。","id":"exchange-010"},{"speaker":"たけうち委員","kind":"確認","question":"ですからこの条例、例えば居室が床面積２５m2以上だけれども２０m2にしようとか、そういうことは基本的にはちょっと認められないと。だから普通に考えると、そういう需要が当然見込まれるわけだから、現実には今のところ動きはあまりないということなのか尋ねました。","respondent":"柏原企画調整課長、高山生活衛生課長","answer":"条例の部分です。もう少し別の手続き、諮問会議等々まで通した形で提案し直していくというような段取りを踏みますので、条例ではそこまで踏み込めないというものです。建設可能な立地条件でありますとか、あるいは近隣住民への周知などが必要になってまいりますので、事前に保健所に相談があります。","id":"exchange-011"},{"speaker":"藤原委員","kind":"質問","question":"そもそも論で伺いたいのですけれども、これからですから、そのときの区民の不利益というのはどういうものになるのでしょうかということを伺いたい。その担当の課長としてですね、衛生ということを含めて、その辺を伺いたいと思います。","respondent":"柏原企画調整課長、高山生活衛生課長","answer":"アピールができるというところがありますので、こちらの条例のほうに呼び込むといいますか、そういう動きはとれるのだろうとは思ってあります。ちょっと不利益とは違う視点になりますけれども、そういったところでの展開… そうしたものについては反復継続して営業されるものということであれば、全て保健所で把握しているものであるということが言えます。","id":"exchange-012"},{"speaker":"藤原委員","kind":"質問","question":"不利益のことを伺ってよくわかりました。それが利益なのですよという、改めてそこだけ答弁していただけますか。","respondent":"柏原企画調整課長","answer":"様々な趣旨で、この旅館業法の特例、今動こうとしています。そのうちの１つということで、そういった意味では、そういったところでの不利益をなるべく払拭していきたいと思ってあります。","id":"exchange-013"},{"speaker":"松永委員","kind":"質問","question":"私からは１点だけちょっと伺いたいと思うのですけれども、７日から１０日以上ということで決まっているということだったのですが。旅館では１泊いくらとかになっているのですけれども、こうした場合に宿泊料金については一律いくらともう決まっているのかなと思って、今質問します。","respondent":"柏原企画調整課長","answer":"そこを単純に割り返しますと、２泊ぐらいという数字は出てきます。実の数字としてどのぐらい延べの日数で泊まっているかというのは、ちょっと申し訳ございません、数字としては押さえていないといったところです。","id":"exchange-014"},{"speaker":"松永委員","kind":"質問・要望","question":"先ほど宿泊料金についてちょっと伺ったのですけれども、国家戦略特別区域施行令の中で７日から１０日以上ということ等いろいろと規制がある中で、それとも決められているものなのか教えてほしいと求めました。","respondent":"柏原企画調整課長","answer":"外国人の旅行客の方が、これはちょっと業界の方たちとお話をした時なのですが、すみ分けはしてくるのではないかということですね。一定程度の泊まれる金額を見ながら、どちらのホテルを使うかというすみ分けをしてくるのではないかという話を聞いてあります。","id":"exchange-015"},{"speaker":"塚本委員","kind":"質問","question":"どういう形かで泊まろうとしていくという動きが現実の社会の中で起こっていく中での、大変にそのとおりだなと思っているのですけれども。１点だけ質問したいのですが、例えば大阪の条例とか、そういうところではどういうものがあるのかないのかというところでお伺いしたいと思います。","respondent":"柏原企画調整課長","answer":"例えば大田区が今検討していますのは、実施の可能なエリアということで、何といいますか。仮に品川区で想定する場合も、そういったところは考慮しながらということになるのだろうと思ってあります。","id":"exchange-016"},{"speaker":"大倉委員","kind":"質問・要望","question":"トラブルの防止、区民の生活に影響が出ないようにしていただきたいと思って、進めていってほしいと求めました。実際そういった声がある際に、まだわからないですが、どこまで監督して指導ができるのかというのは検討されているのか尋ねました。","respondent":"柏原企画調整課長","answer":"仮に旅館業法の特例を使った条例をつくった後ということでよろしいですかね。それが対応できるような部局といいますか、区としてもそういう対応をできる部分は必要だとは思ってありますが、検討中です。","id":"exchange-017"},{"speaker":"大倉委員","kind":"質問・要望","question":"ぜひ対応できるようにはして、その使途改善が求められるようにはしていってほしいと求めましたので、よろしくお願いします。今後見込みはないということでしたけれども、国家戦略特区とは若干違ってしまうのですが、何か考えがあればお話を聞かせてほしいと求めました。","respondent":"柏原企画調整課長","answer":"そういったところを考えながらの事業展開というところであると思いますので、その民間事業者の動きを見ながらいうところではあります。","id":"exchange-018"},{"speaker":"新妻委員","kind":"質問・要望","question":"やはり宿泊施設が少ないということになってくるわけなのですが、その上で今でももう簡易宿泊所ができているところもあります。どれだけ民泊を進めていくのかといいますか、今後どれだけ区としてこれを進めていきたいとお考えなのか、お聞かせほしいと求めました。","respondent":"柏原企画調整課長","answer":"そういったところからも数字をとるというのはいくつか手法があるようには聞いてありますので、その辺はちょっと検討していきたいと思ってあります。","id":"exchange-019"},{"speaker":"新妻委員","kind":"質問・要望","question":"どういう会社がやっているのかとか、そういうことをまた周知を徹底していただければなというところを１つ要望をします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-020"},{"speaker":"沢田委員","kind":"質問","question":"すみません、ちょっと１点だけ、先ほどエリア指定という話が出たかと思うのですけれども、大阪の条例は特にそういったことは書かれていなくて、大田区の条例のほうではある程度地域を限定されたという話でしたが、エリア指定の考え方をちょっとお伺いしたいのですけれども。","respondent":"柏原企画調整課長","answer":"先ほども若干議論はあったところですが、今国のほうから聞いてありますのは、エリアを条例では指定をできないと聞いてあります。恐らく大阪府の場合は、現行の旅館業法ででき得るところを全部想定をしているといったところではないかと思ってあります。","id":"exchange-021"},{"speaker":"沢田委員","kind":"質問","question":"具体的に、品川の中で旅館業法の適用されているところとか、地域とか、何か決まっているのですか。ちょっと私もわからないのですけれども、その辺の地域的な部分の指定があるのか説明を求めました。","respondent":"高山生活衛生課長","answer":"商業地域ですね、それから準工業地域などは、用途制限上は建てられるということになってまいります。概ね１００ｍの距離をおいて建てることが望ましいといいますか、そんな衛生法規上の要請もありますが、両面があろうかと思います。","id":"exchange-022"},{"speaker":"沢田委員","kind":"意見","question":"この２０２０年のオリンピック・パラリンピックに向けて民泊をということであれば、そのあたりのお考えというのは、どういった方向性で考えられているのか説明を求めました。","respondent":"柏原企画調整課長","answer":"今、委員おっしゃっていただいたように、利用者の方からの利便性という意味でいえば、全区的な展開というところは１つの考え方であろうかと思います。","id":"exchange-023"},{"speaker":"伊藤委員","kind":"質問","question":"１つだけ、今ふと思ったのですけれども、内閣府・厚生労働省通知が平成２７年７月３１日に出た中で、認定事業者という言葉が出てきたわけですよね。どうこう言うことはできないのだけれども、恐らくこの方向で規制改革を進めていく中で規制をかけていくのでしょうから、いかがか尋ねました。","respondent":"柏原企画調整課長","answer":"ですので、仮に区が条例をつくっていくということであれば、その大もとの考え方として国が示していますので、そういったところが中心になってくると。","id":"exchange-024"},{"speaker":"伊藤委員","kind":"意見","question":"規制緩和の中の規制になってしまうのかもしれないけれども、認定事業者を出してきたというのは、やはりそういう意図が多分あると思うのですよ。その仕掛けを国で決めてきたわけだから、やはりそのこと自体十分条例上も謳ってほしいなと思うのですが、考え方だけ説明を求めました。","respondent":"柏原企画調整課長","answer":"条例のテクニカルな部分は出てこようかと思いますけれども、趣旨としては踏まえた形で、つくるかどうかもこれからですが、検討させていただきたいと思います。","id":"exchange-025"},{"speaker":"たけうち委員","kind":"質問","question":"こういうところからのお話も伺っていると思うのですが、たしか言っていたような気がしたのですね、エリアのことを。それから先ほど私質問したこの施行令で定められたところで２５m2とあるのですが、そこは原則ということなので、もしわかればその辺を。","respondent":"柏原企画調整課長","answer":"基本的なところは、基本的なスキームを考えていく上では、この２５m2というのはまずベースになってくる数字であろうと思ってあります。もう少し調査をかけないといけないと思いますが、基本的にはスキームはこの２５m2というのをベースに持っているです。","id":"exchange-026"},{"speaker":"たけうち委員","kind":"質問・要望","question":"わかりました。認定されやすいやり方がどうなのかというのはちょっとわからないのですが、また今後の、何か動きがあったらご報告ほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-027"},{"speaker":"横山委員","kind":"質問・要望","question":"エリア指定に関しては広く、海側だけではなくて全域から調査をとっていただきながら進めていただきたいというところ、要望だけします。こちらもし万が一拒否の場合には、罰則等は設けられているのか尋ねました。","respondent":"高山生活衛生課長","answer":"そこはやはり今、他の先行する市や区がまさに検討しているような状況かと思います。実質的にはといいますか、現状では、認定を取り消すに当たっての立ち入りというような形での条例上の表記というふうに捉えているところです。","id":"exchange-028"},{"speaker":"横山委員","kind":"確認","question":"認定事業者の認定を取り消さなければならないかどうかということを調査するための立入調査ということでよろしいでしょうか。すみません、もう一度確認だけします。","respondent":"高山生活衛生課長","answer":"その他の附帯する契約というものになっていまして、旅館業の範疇以外のいわゆる賃貸借契約を結ぶというようなスキームになっているところです。","id":"exchange-029"},{"speaker":"横山委員","kind":"質問","question":"この自治体の役割として、どういうふうに捉えていらっしゃるのかというところだけ、最後にお聞かせいただけたらと思います。この立入調査だったり、そういった規制を設けていくという部分に対しての、品川区としての役割を現在どのように捉えられていますか尋ねました。","respondent":"柏原企画調整課長","answer":"立ち入りのところでの区の役割です。そういったところを収める、抑えるといった視点での役割は、区にもあるだろうと思ってあります。","id":"exchange-030"},{"speaker":"のだて委員","kind":"質問・要望","question":"確認なのですけれども、品川区の客室稼働率、出ておりますが、これはこの中で外国人の方が何割かというのがわかれば教えてほしいと求めました。その後のことも見ていかなければならないということで、今現在検討中ということでいいのか、確認です。","respondent":"柏原企画調整課長","answer":"それから後段の部分のご質問は、この旅館業法の特例の部分はオリンピック・パラリンピックに向けてという意味合いでよろしかったですかね。これは外国人旅行者の方が増えるというのが想定されますので、それに向けてというのは１つ大きな理由です。","id":"exchange-031"},{"speaker":"のだて委員","kind":"質問・要望","question":"やはり今いろいろ皆さんから意見出されまして、この規制緩和していくに当たってはやはりルールづくりが必要だと私も考えています。深夜の度を過ぎた騒ぎですとか、あとは火災などのときに安全面の問題、そういったことをしっかりしていってほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-032"},{"speaker":"安藤委員","kind":"質問・要望","question":"もう少し説明ほしいと求めましたし、あとこれからどう、実際には行われている違法な民泊というのを把握していこうとしているのかもお伺いします。２０２０年までの期間限定という考えについては、区はどういうふうに考えているのか、もう少しそこら辺もお伺いします。","respondent":"中山企画部長","answer":"これはさまざま国際化への対応、それからまた品川区への来訪者への対応、これは避けて通れず検討していくという中でのご議論です。先行自治体でもそのような議論があるですので、いろいろな動きの中で現状の分析も含めて考えていきたい、このように考えているものです。","id":"exchange-033"},{"speaker":"安藤委員","kind":"質問","question":"調査していくということなのでしょうか。結果としてそういう可能性になるということなのですが、どう把握しているかということについて伺ったので、ちょっともう一度お願いします。","respondent":"中山企画部長","answer":"原則としてそういう考え方はとれないということですので、この議論の中でもご説明しているのは背景として、大きな１つの検討する余地がある。","id":"exchange-034"},{"speaker":"石田（秀）副委員長","kind":"質問・要望","question":"３部屋は寝る部屋という判断をするのであれば、２５m2はないではないですか、それでもいいのか。それを７日とか１０日限定にして、７日以上泊めればあれもやり方としてオーケーなのかという、それを教えてほしいと求めました。","respondent":"高山生活衛生課長、柏原企画調整課長","answer":"確かに１居室の床面積２５m2以上ということにはなっておりますが、基本的には１部屋というふうに認識しております。いわゆる旅館業法の違反というふうな形で聞いておりますので… そういった意味で国家戦略特区、報道等をみている範囲でありますと、条件的には多分そういったことが可能であろうとは捉えてあります。","id":"exchange-035"},{"speaker":"石田（秀）副委員長","kind":"確認","question":"１つだけ確認。だから、今の１部屋という、寝る部屋なのか、そこをちょっと教えてもらえますか。","respondent":"柏原企画調整課長","answer":"こちらのほうで認識といいますか、今回のこの旅館業法の特例の部分につきましては、居室という考え方でとっているです。１つの部屋、全体での考え方として２５m2というところの考え方と捉えているのではないかとは思ってありますけれども、ちょっとすみません。","id":"exchange-036"},{"speaker":"石田（秀）副委員長","kind":"質問","question":"だからそういう定数みたいなものもこれから出てくるのだろうと思いますので、ひとつそれはこれから伺うようにします。２５m2というと規制緩和するけれども厳しくするというと、何か矛盾があるなとちょっと思っているのですが、そこら辺の考えを説明するよう求めました。","respondent":"柏原企画調整課長","answer":"例えば検討する中でこの台所の関係、どういうつくり込みが、もう少し詳細を調べていかなくてはいけないと思います。先ほども若干ご議論ございましたけれども、２５m2以下の部分でどう対応するのだというのは… １１月の終わりに東京圏の区域会議が実は開かれておりまして、それが申請をして議論され、通ったやには聞いてあります。ちょっと資料が間に合わなくて申し訳ございませんでしたが、状況は以上です。","id":"exchange-037"},{"speaker":"安藤委員","kind":"質問","question":"現在では公道での飲食を規制しているわけですけれども、その理由は何なのか、ちょっと具体的に説明ほしいと求めました。そういったところは規制しているわけですが、そういった例などもあわせて伺いながら、現在の規制の理由を伺いたいと思います。","respondent":"溝口都市開発課長","answer":"そういったものを使ってそういった営業をやっていただくというのが基本的な考え方になりますので、そういったもので規制をしている。周遊とか、そういったものに資するような形になれば、一定国家戦略特区の中で規制緩和できるというのが今回の考え方ということになるものです。","id":"exchange-038"},{"speaker":"安藤委員","kind":"質問","question":"そういったところもちょっと心配される点ではあると思うのですが、そういった点での現在の公道での飲食規制の理由という点では何かあるのでしょうか。わかればお伺いします。","respondent":"溝口都市開発課長","answer":"条件を通らなくてはいけないとか、届け出が必要なものはありますので、それはそれとしてしっかりやった形でイベントを開催していくことになります。","id":"exchange-039"},{"speaker":"安藤委員","kind":"質問","question":"あるいは何でしょうか、そのできない理由というのをお伺いしたので、そこはちょっとお伺いしたいと思います。今回特区を活用するとなると、そういった点で、私はそういったところも心配はやはりあるのかなという思いもありまして質問させていただいています。","respondent":"柏原企画調整課長","answer":"大きなイベントで人を呼び込めるであるとか、そういったところの大きな視点があるといったところが国家戦略特区を今回使っていくところです。","id":"exchange-040"},{"speaker":"安藤委員","kind":"意見","question":"これはないとは思いますけれども、２４時間もずっとやってもいいのだというふうなことになっては、よろしくお願いいたします。これは意見ですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-041"},{"speaker":"横山委員","kind":"質問・要望","question":"すみません、要望だけになってしまうかもしれないのですけれども、ちょっと確認していただきたい点だけお伝えさせていただけたらと思います。これからということでしたらご要望だけという形で結構です。","respondent":"柏原企画調整課長","answer":"我々も夢さん橋をやったときに、国家戦略特区という形でスキームを持っていきましたので、自治体との関係というのは密接なものと考えています。詳細はちょっと後ほど確認させていただければと思います。 ３番目に当たるところでございまして、都市公園内に保育所の設置を可能とするといったものです。品川区もこれに続く形で、今検討を進めているといったところです。","id":"exchange-042"},{"speaker":"たけうち委員","kind":"質問・要望","question":"今荒川区というお話で、この都市公園法に何か関わってくるのかなと思うのですが、そこの認識がちょっとわからないので教えてほしいと求めました。世田谷も何か動きがあるようなことも聞いているのですけれども、そこもあわせて教えていただきたい。","respondent":"柏原企画調整課長","answer":"品川も検討を進めていって、スケジュール感としてはまだ調整中ですけれども、区域会議にかけて認定を受けて進めていくという内容になってくるです。やはり先日の区域会議で話が出て、具体的などこをやるかというよりは、動きが出始めたというのが報告されていると聞いてあります。","id":"exchange-043"},{"speaker":"たけうち委員","kind":"質問","question":"そうしたら西大井広場の、これは次の区域会議のスケジュールとか、どのあたりで決まっていくか。もう何かプレスにも出ていたので、今さら区域会議でだめと言われてだめだったということになっては困るのですけれども、その辺はどうなのか尋ねました。","respondent":"柏原企画調整課長","answer":"ここに至るまでには国、東京都と打ち合わせといいますか、詳細は詰めてきているところです。はもう手続き的なところをどう詰めるかというところで、区域会議にかけて、恐らくひっくり返るということはないと信じてあります。","id":"exchange-044"},{"speaker":"安藤委員","kind":"質問","question":"もう一つ、しながわ中央公園の拡張部分も検討したのですかと伺ったのですが、ヘリポートがあるので難しいという話があったのですね。そこら辺ちょっとお伺いします。","respondent":"多並公園課長、今井待機児童対策担当課長","answer":"基本的にはそういうところは今回は考えずに、広場をつくる整備ということで工事を進めているという説明をさせていただいたところです。昨日の建設委員会の中でもご説明させていただきましたが、今約３ｍぐらいある築山を… １点目のその他の公園の検討ですけれども、これはその他の公園についても検討は順次進めていきたいと考えております。運営事業者を決めていくのが３月中旬頃と考えておりますので、来年度以降の提案になってくるかと思います。","id":"exchange-045"},{"speaker":"のだて委員","kind":"質問・要望","question":"具体的に検討していなくても、この公園なら保育園が設置できそうだと考えている公園があれば、幾つか数を教えてほしいと求めました。どれくらいまで拡大していくのか、考えがあれば説明を求めました。","respondent":"今井待機児童対策担当課長","answer":"今委員ご指摘のとおり、様々な課題がありますので、今のところは検討中です。適切な時期に進めないと解消には結びつきませんので、検討、ここは対応していきたいと考えております。","id":"exchange-046"},{"speaker":"のだて委員","kind":"質問・要望","question":"ぜひテンポよく進めていってほしいと求めました。前回の話の中で、この更新の考え方や仕組みについてわかったことがあれば教えてほしいと求めました。","respondent":"多並公園課長","answer":"今回の区域法の改正によって、国のほうで示されているのが１０年間、占有期間が１０年間ということで示されているので、そういう考え方と。更新の考え方ですけれども、そこら辺を含めた形で今後も運用していくべきと考えているところです。","id":"exchange-047"},{"speaker":"安藤委員","kind":"質問","question":"一定の不定期航路事業を行う際の制限を設けているということの理由といいますか、そうした歴史的経緯もあるのでしょうか。そういったところについて、区はどのようにお考えかお伺いします。","respondent":"柏原企画調整課長","answer":"そういったところの事業もありますので、それは定期航路を基本としながらも、そういった特例的なところで不定期航路も認めるといったというものです。","id":"exchange-048"},{"speaker":"安藤委員","kind":"質問","question":"そういう生活に必要な定期航路ができなくなってしまうというか、採算がとれなくなってしまうというような不安もあるのではないかと思うのですけれども、そこら辺がいかがかということをお伺いします。","respondent":"柏原企画調整課長","answer":"そこまでの投資ができない、もしくは規模としては小さい船を持っている事業者ということを考えますと、なかなか考えづらいかなという部分はあります。ただ可能性としては不定期航路が定期航路に与える影響というのはないことはないとは思います。","id":"exchange-049"},{"speaker":"安藤委員","kind":"意見","question":"さらなる超高層ビルの再開発をどんどん誘導していくという使い方をするのであれば、それは私は間違いだと思っていまして、これは意見として述べしますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-050"},{"speaker":"伊藤委員","kind":"質問","question":"どういうふうに交渉されていらっしゃって、この不定期航路事業のほうだと思いますが、どういう感触を持っていらっしゃるのでしょうかということを説明するよう求めました。","respondent":"柏原企画調整課長","answer":"国のほうから帰ってきた答えは、そちらでご検討願えないかというような趣旨の回答が返ってきたというのが、その次の段階です。それに対しての回答は、その前段階ということで、今そこまでの状況に来ているといったところです。","id":"exchange-051"},{"speaker":"伊藤委員","kind":"提案","question":"そういう規制を変えていくために担当の部署と会うことは間違っていないと思うのだけれども、いきなりやったら国交省だってそうは言うでしょうね。もう一度確認したいのですけれども、東京都全体で提案していくための素地として、その調整をとるためだったのか尋ねました。","respondent":"柏原企画調整課長","answer":"１つの考え方であろうということでは東京都も認識はしているのですが、実はアジアヘッドクォーターのところで１航路だけ。ほかの区、自治体も交えながら、東京都と話をして動いているといったところです。","id":"exchange-052"},{"speaker":"伊藤委員","kind":"質問","question":"そうしたらまとめで、これからのスケジュールの感覚でお伺いしたいのですけれども、これに書いてあるように国交省と協議をしていると。今お話あったようにそれをまとめて、東京圏として意見集約をして会議にかけていくということになっていくのでしょうかね。","respondent":"柏原企画調整課長","answer":"区の思いといたしましては、できる限り早くと。今の国とのやりとり等々は、動き出すにしても年という単位での動きにはなってくるのではないかというような感触は持っているところです。","id":"exchange-053"},{"speaker":"藤原委員","kind":"質問","question":"今安藤委員の質問で定期航路の歴史的背景みたいなものを伺ったときに、それが安全でした、それを伺ったら聞かなくてはいけない。それが担保されていなければ、どちらを優先的に考えるのだということが出てくると思うのですけれども、その１点だけ説明を求めました。","respondent":"柏原企画調整課長","answer":"そういうことではありませんので、それをきちんと届け出をして、常に自由に動くということではないというところがあります。先ほど申し上げたのは、確かに定期航路に対する影響というのは考えなくてはいけないだろう、そういった意味でご答弁申し上げました。","id":"exchange-054"},{"speaker":"たけうち委員","kind":"質問・要望","question":"一応確認なのですが、今この規制緩和の策が区の要望どおり通ったとして、区として今考えている不定期の区間というのですか、それがどこかということと、そこについては今定期航路が走っているのかどうか、この２点をお聞きしたいと思います。","respondent":"柏原企画調整課長","answer":"まだ検討段階ではあるのですけれども、１つ想定できますのは、羽田空港のところの桟橋を使うという動きがあります。具体的にどことどこかというのは、今まだ具体的な場所はあれなのですけれども、そういったイメージを持ちながら検討しています。","id":"exchange-055"},{"speaker":"たけうち委員","kind":"確認","question":"そうしますと、墨田とか、あちらのほうなどは、定期航路のは今あるということなのでしょうか、それがもう１回確認。そこはそこで別の許可というか、交渉が必要なのかという、その辺を説明するよう求めました。","respondent":"柏原企画調整課長","answer":"航路が使えるようになるという考え方ですので、現在使っているところが航路として受け入れられるかどうかというところですね。次のステップになるのですけれども、これは都の港湾局との話もありますし、桟橋を持っている持ち主のところの考え方とすり合わせが今度出てくるです。","id":"exchange-056"},{"speaker":"たけうち委員","kind":"質問・要望","question":"わかりました。しっかり頑張ってほしいと求めましたが、いずれにしてもまずはその交渉をしっかり成果を出してほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-057"},{"speaker":"のだて委員","kind":"確認","question":"この航路ですね、オリンピック前後、これは午前中もありましたけれども、限定のものになるのかどうかという確認です。やはりこの２点間不定期航路の規制緩和によって、既にある公共交通、その辺どう考えているのかお伺いしたいと思います。","respondent":"柏原企画調整課長","answer":"定期航路を妨げてまで不定期航路をするということではありませんで、産業であるとか、今あるものを否定しながら動くということではありません。東京都もそうですけれども、舟運ということでいろいろ検討を始めているところでありますので、その１つの考え方です。","id":"exchange-058"},{"speaker":"のだて委員","kind":"質問","question":"この航路の選定に当たって、周辺住民のプライバシーに配慮したものにするべきだと思うのですが、お考えはどうかお伺いしたいと思います。","respondent":"柏原企画調整課長","answer":"桟橋等々ありますので、そういったところがどういう形で活用できるかというのを踏まえながら、当然安全・安心というところは守りながらの事業ということであるというふうに考えてあります。","id":"exchange-059"},{"speaker":"のだて委員","kind":"意見","question":"しっかりとプライバシーの保たれた、それで既存等の航路とはお互い調整しながらやっていくということで、そこの調整をしっかりやって、既存航路に影響を及ぼさないようにやっていっていただく必要があると思いますので、今意見だけ言わせていただきますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-060"},{"speaker":"石田（秀）副委員長","kind":"質問・要望","question":"それからもう１つ、そういうときはどこかの駅の桟橋の近いところからそこのホールへ直接運びますよということをやっているではないですか。それは不定期航路として、そういうことも特区で可能になるのかなと思っているのだけれども、そういうことというのは可能になるのか尋ねました。","respondent":"柏原企画調整課長","answer":"ちょっと申し訳ございません、恐らくこの航路の話と桟橋の位置づけの話というのはまたちょっと別の考え方があるのではないかなとは思います。区で今考えているのは、して使っていこうという考え方をとっていますので、改めて確認をさせていただきたいと思っています。","id":"exchange-061"},{"speaker":"新妻委員","kind":"質問・要望","question":"推進していただきたいと思うのですが、ちょっと一般論で、可能性があるのかというところをちょっと確認させてほしいと求めました。桟橋の所有者にそこが使えるかどうかの確認も必要だということがありましたが、今現状、ちょっと教えてほしいと求めました。","respondent":"柏原企画調整課長","answer":"考え方に対しては積極的に取り組んでいこうという前提がありますので、いろいろな舟運の考え方というのは進めていきたいというところが。そういった意味でも、その手続き論のところでは、そのくらいのスケジュール感は持たないといけないだろうと思ってあります。","id":"exchange-062"},{"speaker":"新妻委員","kind":"質問・要望","question":"いずれにしてもすぐにはできないというご判断かと思いますが、大きくまた推進をしてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-063"}]},{"id":"topic-02","title":"羽田空港の機能強化に関すること","agenda":"羽田空港の機能強化に関すること","exchanges":[{"speaker":"安藤委員","kind":"確認","question":"区はこの意見に対してどう思いますでしょうか。改めて確認したいのですが、国として策定するということなのかどうか、そこの確認もお願いします。","respondent":"中村都市計画課長","answer":"第２フェーズにおきましてオープンハウス型の説明会を行うに当たりまして、こういったものを国としてどのような対応策として打ち出してくるか。したがいまして、今後国の対策といたしましても、こういったところを柱に対応策が示されるのではないかと考えています。","id":"exchange-064"},{"speaker":"安藤委員","kind":"提案","question":"区としてはどんな説明を受けているのでしょうか、改めてお伺いします。できることは区としてもやるべきだと思いますし、提案していく必要があると思うのですけれども、いかがか尋ねました。","respondent":"中村都市計画課長","answer":"国はこちら、国としてはまだ案として、地域の皆様の理解を得ながら進めていくというふうに区としても説明を受けているところです。それから説明会の周知方法ですけれども、現在のところそういった周知方法で、引き続き国と調整しながらやっていくというふうに考えてあります。","id":"exchange-065"},{"speaker":"安藤委員","kind":"提案","question":"やはり６,０００人ですから、このままの推移でいったら、先ほどさまざま提案させていただいたのですけれども。だからそういった、私もう１つは宣伝カーとかも言いましたが、もう少しこうした工夫が必要だという意味で聞いたので、区のお考えをお伺いしますとの意見を述べました。","respondent":"中村都市計画課長","answer":"今この説明会のお知らせを聞いて、その中で一定程度要望もまとまってきたのかなと考えております。あるいは安全性について、これから国に対してその中身に対してしっかりと対応策を出していっていただくように要望してまいりたいと考えております。","id":"exchange-066"},{"speaker":"安藤委員","kind":"質問・要望","question":"フェーズ２についてですけれども、かねがね第１フェーズではこうした要望が寄せられましたと、やはり私も。それを強く国に求めてほしいと求めましたが、いかがか尋ねました。","respondent":"中村都市計画課長","answer":"これは区もこういったものに対して必要な情報をしっかり出すように求めているところです。委員ご指摘のようにしっかりと求めてまいります。","id":"exchange-067"},{"speaker":"安藤委員","kind":"質問・要望","question":"地域から求められた場合、求められなくても、区はどうお考えでしょうか。それと、それを国に求めている現状はあるのかどうか伺います。","respondent":"中村都市計画課長","answer":"今このフェーズ１でも、品川区役所あるいはアトレ大井町で説明会を国に開催していただきました。したがいまして、これからワークショップ等の説明会等もまた区民から要望がありましたときには、そして国のほうに極力対応していただくような。","id":"exchange-068"},{"speaker":"安藤委員","kind":"質問・要望","question":"要望があればということですけれども、そういったワークショップ型の説明会を国に開催を求めているという事実はないということなのでしょうか。そこだけちょっとわからなかったのでお伺いします。","respondent":"中村都市計画課長","answer":"国に対しては、品川区民に対してくまなく十分な説明をしていただくように求めているところです。そういったところからしますと、そういったレベルの説明もしていただくようには、常にお願いをしております。","id":"exchange-069"},{"speaker":"伊藤委員","kind":"質問・要望","question":"そういうところと連携をとりながら、次のステップの物事を考えていかなければいけない時期にもしかしたら入ってくるかもしれないわけではないですか。私はむしろそちらの方向に話を展開すべきだと思いますが、今の時点の品川区のお考えを説明するよう求めました。","respondent":"中村都市計画課長","answer":"１つは説明会等に来ていただいた個人の区民の方に対して国が一人ひとりに対応して説明をしていく、１つ双方向の対話だと考えています。今後国の対策についてフェーズ２でどのような形で出されていくか、これは区としても非常に重大な関心を持って注視していきたいと考えています。","id":"exchange-070"},{"speaker":"伊藤委員","kind":"提案","question":"大田区役所でやるものに参加していただいて、新たな提案がもしかしたらあるかもしれないわけではないですか、そこで。全庁を挙げての対応をとりながら、それから場合によっては国土交通省なり、東京都との調整事項が出てくるかもしれないわけではないか尋ねました。","respondent":"中村都市計画課長","answer":"今大田区を１つ例に出していただきましたけれども、他区の開催の状況ですね、こういったものも十分に情報交換をいたしまして、そして今後の対策に生かしていきたいと考えております。","id":"exchange-071"},{"speaker":"新妻委員","kind":"質問・要望","question":"私もこの場で要望させていただきました、１２月に行われます八潮での第２回の説明会を全戸配付を、ありがとうございました。今度第２フェーズになるのですが、わかる範囲でちょっと教えていただきたいのですけれども、そこら辺を少し教えてほしいと求めました。","respondent":"中村都市計画課長","answer":"八潮での説明会につきましては、そして個々の方々に対しての質疑応答を行うというオープンハウス型の説明会、討議を重ねていくというふうに２段階で行うと聞いてあります。","id":"exchange-072"},{"speaker":"新妻委員","kind":"質問","question":"申し訳ありません、ちょっと私の説明が、質問の仕方が悪かったです。その八潮ではなく、これから行われる第２フェーズの説明会の内容が第１フェーズとどのように違うかという点をちょっと教えてほしいと求めました。","respondent":"中村都市計画課長","answer":"それから第２フェーズにおきましては、そういったものに対する対応策を考えていくために、深く掘り下げていくというふうに聞いております。","id":"exchange-073"},{"speaker":"のだて委員","kind":"質問","question":"フェーズ２の説明会が発表されまして、区の広報にカラフルで大きな記事で掲載されてうれしく思います。しかし、この説明会、区内では５日間で２カ所しか行われないということについて、私は不十分だと考えていますが、区の考えをお聞きします。","respondent":"中村都市計画課長","answer":"この国の一連の説明会ですけれども、その中では地域ごとにくまなく説明をしていただいたりですとか、あるいは教室型の説明会をしていただくですとか。","id":"exchange-074"},{"speaker":"のだて委員","kind":"質問・要望","question":"これが具体的に明らかにされていくべきだと思いますので、その点についても引き続き求めていってほしいと求めました。緊急退避ルート、あるいは微粒子のＰＭ２.５の関係等、こういったこともしっかり影響を示していくように求めていってほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-075"},{"speaker":"たけうち委員","kind":"確認","question":"すみません、１点確認なのですが、第２フェーズで説明会に区役所が入っていないのは、マイナンバーの関係で使うからということなのか尋ねました。","respondent":"三ツ橋環境課長","answer":"少し住民の方に近い部分も、今回大井町の部分がちょっと区役所だと大井町から少し離れているというご意見もあったようですので、そちらにつきましては大崎ということになりました。","id":"exchange-076"},{"speaker":"石田（秀）副委員長","kind":"意見","question":"ぜひ１月１１日、成人式が終わったら行ってくださいぐらいの広報をやってくれたらいいかなと思うのだけれども、せっかく若い人が来るわけだから。そのお願いだけしておきますとの意見を述べました。","respondent":"中村都市計画課長","answer":"国のほうへしっかり伝えていきたいと思います。国も可能な限り周知のほうに努めたいと申しておりますので、強く要望してまいります。","id":"exchange-077"}]},{"id":"topic-03","title":"基金に関すること","agenda":"基金に関すること","exchanges":[{"speaker":"のだて委員","kind":"質問","question":"決算特別委員会でも基金に必要な額ということで、積み上げると１,０００億円という答弁があったのですが、その中で義務教育施設整備基金３００億円と公共施設整備基金３５０億円についてはこれだけ必要だということでしたけれども、ほかの基金についてはどれがいくら必要だと考えているのか伺います。","respondent":"秋山財政課長","answer":"決算特別委員会のときにご説明させていただきました、細かく言いますと合計が１,０２７億円という形になっていますけれども、区として判断しているものの積み上げたものです。","id":"exchange-078"},{"speaker":"のだて委員","kind":"質問","question":"他区よりも基金が多いことをよいと考えているのか伺います。やはりこの基金は積み上げるのではなくて、区民の苦しい暮らしを助けるために使うべきだと思いますが、いかがか尋ねました。","respondent":"秋山財政課長","answer":"基金の額としては２３区の中では７番目か、ちょっと決算の具合をまだ見ておりませんが、８番目ぐらいだったと記憶はしています。それぞれの目標を決めてやっていることですので、品川区としては今のところ、先ほど述べたような金額でやっているです。","id":"exchange-079"},{"speaker":"のだて委員","kind":"質問・要望","question":"やはり私は、これは積み上げ過ぎだと思います。福祉を充実させていくために使っていくべきだと思いますので、しっかりそういった方向で使っていっていただくように求めたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-080"},{"speaker":"安藤委員","kind":"質問・要望","question":"学校建替えですから、将来的に返還されるというような仕組みがあるというふうな話も伺っているのですけれども、今の区としてのお考えをお伺いします。それとこれがどうやって、なぜ年々これが増えていっているのか、そこら辺についてもお伺いします。","respondent":"中山企画部長","answer":"積算するとたまたま合計額が１,０００億円ぐらいになるであろうということを答弁いたしたですので、今後の施設の規模であったりから望ましいというものを大枠で考えている、そのようにご理解いただきたいと思います。","id":"exchange-081"},{"speaker":"安藤委員","kind":"質問","question":"積み上げた場合のというところの考え方をもう少しお伺いしたいのと、ちょっと伺ったのですがお答えがなかったので、伺いたいと思います。その手法といいますか、財源になるのか手法なのかわからないのですけれども、そこら辺についても答弁が欲しいです。","respondent":"秋山財政課長","answer":"一般家庭で見ても、区としましては、こういう基金というのを活用して安定的に行政を進めていくというのが基本的なスタンスです。当面の２０年間である程度の改築を、それはm2単価でいくと大体の金額が出ますので、それを賄える額ということでその目標額を設定しているものです。","id":"exchange-082"},{"speaker":"安藤委員","kind":"質問・要望","question":"考え方の基本というのは伺いましたが、私が伺ったのは、実際にこの財調基金が増えているわけではないですか。そこら辺の財政調整基金を増やしていくというところにおいて何か関連性があるのか、そこら辺、ちょっとうまく言えないのですけれどもお伺いします。","respondent":"秋山財政課長","answer":"その辺をプラスして１９２億円ということで、１９２億円きっちりを目標としているわけではありませんけれども、この金額を出しているものです。決して積み立てるために何かをしているということではございません。","id":"exchange-083"},{"speaker":"安藤委員","kind":"質問","question":"財調の積立ての手法については私も引き続き研究して、いろいろ具体的に、然るべ場でまたお伺いしたいと思います。１点だけ、どれぐらい返ってくるのか、全部返ってこないというとどれぐらい返ってくるか、逆にちょっとわからなかったので、その点だけお願いします。","respondent":"秋山財政課長","answer":"ごめんなさい、１割が返ってくる額。これについては財調基金をいくら持っているから財調を減らすとか増やすとかということは全くありませんので、これは全く関係がないです。","id":"exchange-084"},{"speaker":"たけうち委員","kind":"質問","question":"いくつか伺いたいのですけれども、今のやりとりを整理しますと、この基金を当初予算から充てた時期があったのですよね。恐らく７、８、あと１０とか、この辺は充てられると思うのですけれども、それ以外に何か充てていけるのかというのを一応説明を求めました。","respondent":"秋山財政課長","answer":"そのときに基金があれば、歳入に基金の繰り入れをつけて歳出の予算が組めるということでございまして、そういう考えでやっているところです。震災等になれば国のほうの地方への支援というか、まずないと困るというようなことにはならないかと考えているところです。","id":"exchange-085"},{"speaker":"たけうち委員","kind":"提案","question":"後段のほうですけれども、実は七、八年ぐらい前か、もっと前ですかね。我々が本当はそれをやって提案できれば一番いいのですけれども、その辺もしっかり見てもらいたいなと思うのですが、一言との意見を述べました。","respondent":"秋山財政課長","answer":"スパンで見れば国からの支援が入りますよということでございまして、やはりこうした基金ですとか、いわゆる現金に代わるようなものを多分利用して。危機時の対応というためにも必要という考えで、基金の運用、積立て等をしているということでご理解いただければと思います。","id":"exchange-086"},{"speaker":"伊藤委員","kind":"質問","question":"この金額をやはりしっかり担保して、ほかの委員がおっしゃったように、いつ起こってもおかしくないと言われる大震災があるわけではないですか。そのことについては、もう少し答弁をいただければありがたいのですけれども、いかがか尋ねました。","respondent":"中山企画部長","answer":"災害対策基本法に基づく対応であるとか、国の支援ももちろんあるわけですけれども、歳出の中で相当な負担になっているというお話があって。","id":"exchange-087"},{"speaker":"石田（秀）副委員長","kind":"質問・要望","question":"私もちょっと不勉強な部分があって教えていただきたいのですけれども、当初予算を組むではないですか、これは出てこないという感覚でいいのですか。それが載ってきていないではないですか、平成２６年度、例えば南品川とか。","respondent":"秋山財政課長","answer":"やはりそれなりに基金から繰り入れるということで予定を立てておいて、そこの部分が入ってくるので、この積立額のところに出てこないと。当初は出てきているけれども出てこないというのは、そういう事情があるということです。","id":"exchange-088"}]},{"id":"topic-04","title":"旧参議院会議等施設","agenda":"旧参議院会議等施設","exchanges":[{"speaker":"安藤委員","kind":"質問・要望","question":"どんな住民要望がそこにあるのかとか、伺いたいのは、もう少しここら辺をお伺いしたいと思います。","respondent":"柏原企画調整課長","answer":"ニーズに対してどう応えられるのかといったところを検討する中で、そういった、一定程度の容積を確保するのは厳しいだろうということ。それから行政需要に対して、それを担うだけの建物といいますか、ボリューム感ができないといったところがございました。","id":"exchange-089"},{"speaker":"安藤委員","kind":"質問","question":"国のホームページに、今、自治体に照会していますよという情報が出ていると。今のところどのようなところから何件ぐらい問い合わせがあるのか、もしわかればお伺いしたいと思います。","respondent":"柏原企画調整課長","answer":"前回の本委員会で、委員のおっしゃるとおりそういった形での動きになるだろうというお話をさせていただきました。これは具体的には国の物件ですので、これは表に出ていない部分ですので、ちょっと現段階では区としてはわかりかねるといったところです。","id":"exchange-090"},{"speaker":"安藤委員","kind":"質問・要望","question":"住民のほうからはやはり池田山の環境協定にそぐわないような建物が建ってしまうことというような心配も根底にあるわけですね。ですから、そういった情報も取得していっていただきたいと思うのですけれども、いかがか尋ねました。","respondent":"柏原企画調整課長","answer":"そういったところも全て含めて、どういった意見が出ているかということについては、国のほうには我々のほうから伝えさせていただいてあります。それから陳情等も出ておりますので、そういった中身については国のほうには伝えさせていただいてあります。","id":"exchange-091"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/842551?Template=document&Id=5998#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=14&TermStart=2015-01-01&TermEnd=2015-12-31"}],"sourceMeta":{"pages":0,"characters":76106,"voices":211}},{"id":"h27-20151203-18","meetingId":"h27-cm12","date":"2015年12月3日","dateIso":"2015-12-03","committee":"オリンピック・パラリンピック推進特別委員会","time":"午前１０時００分～午後 ２時３７分","status":"正式会議録","sourceType":"formal","overview":"オリンピック・パラリンピック推進特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を24件整理しています。","topics":[{"id":"topic-01","title":"特定事件調査","agenda":"特定事件調査","exchanges":[{"speaker":"南委員","kind":"質問","question":"どういうふうに質問しようかと、質問の角度はまだわからないのですけれども、例えばどんなことなのか。このオリンピックがあるのだということを改めて実感したのですが、その辺についての見解、区の思いもご紹介していただければいいかと思います。","respondent":"小川オリンピック・パラリンピック準備課長","answer":"区としても検討をしていくべきことではありますが、十分、遜色なくやっていけるという自信はあります。せっかくのオリンピックですので、それにあわせて、できる限り、組織委員会の協力の要請等については、前向きにやっていきたいという思いです。","id":"exchange-001"},{"speaker":"南委員","kind":"質問・要望","question":"どういうことを意味しているのかわからなかったので、その辺を教えていただきたいというのがあります。その辺の動き、どういうふうになるのかがわからないので、イメージを説明するよう求めました。","respondent":"小川オリンピック・パラリンピック準備課長","answer":"オリンピック憲章のところの規則３９に定められておりますとおり、あくまでも、まずは組織委員会のほうが認定をすることになっております。その認定をされた後に、ＩＯＣに正式に承認を得るというような作業が生まれるということになってあります。","id":"exchange-002"},{"speaker":"あくつ委員","kind":"質問・要望","question":"ですから、一つの東京の中の拠点として、ぜひ名乗りを上げていただきたいというような思いがあります。このような思いがあるのですけれども、その点に関してのご見解を伺いたいと思います。","respondent":"小川オリンピック・パラリンピック準備課長","answer":"それがおそらく今年度末になるか、それ以降になるかというふうに言われております。当然、積極的に、品川区としては前のめりにやっていきたいというふうに考えているところです。","id":"exchange-003"},{"speaker":"あくつ委員","kind":"質問","question":"先ほどの立川市の展覧会にも東京都の職員が来たなんていう話も、私も現場に行って、伺ったところです。ですから、やはり成功の秘訣ではないのかというように考えているのですが、その辺のご見解を伺いたいと思います。","respondent":"小川オリンピック・パラリンピック準備課長","answer":"今まさにアクション＆レガシープランを検討しているのですけれども、その中に文化教育委員会という部門があります。そうした中で文化プログラムについては具体的に検討され、いろいろな方向が今後、示されるのであろうというふうに推測しているわけです。","id":"exchange-004"},{"speaker":"あくつ委員","kind":"質問","question":"これは本当に区の財産でもあるし、武器になると私自身はすごく感じたのです。文化観光課長にもお尋ねをしたのですけれども、また改めての質問になってしまいますけれども、お伺いをしたいと思います。","respondent":"間部文化観光課長","answer":"高齢者地域支援課では高齢者作品展と、作品展をさまざま実施しているわけですけれども、区としてはやってきたというふうに思っています。","id":"exchange-005"},{"speaker":"あくつ委員","kind":"質問・要望","question":"どっちがいいとか悪いとかというのは、もちろんないと思うのですけれども、それに対しての疎外感を覚えていらっしゃる方もいらっしゃいました。別の角度の話なのですけれども、そのことについて何かご意見があれば教えてほしいと求めました。","respondent":"間部文化観光課長","answer":"２０２０年に向けてということであれば、できる限り、同じような土俵で開催ができるのが望ましい形だと考えています。次年度に向けて、この辺はやっていきたいと考えています。","id":"exchange-006"},{"speaker":"あくつ委員","kind":"質問・要望","question":"２点ほど、お伺いさせてほしいと求めました。そもそも芸術というものは多様性があるものですから、一つの大きな芸術という中でやっていただきたいという希望でしたので、ありがとうあります。","respondent":"間部文化観光課長","answer":"広く皆様が認識されるところでは、今、実施する方向でも考えています。まだ品川区は取り組んでいない部分ですので、演劇も含めて、手広く開催をしていきたいというように考えてあります。","id":"exchange-007"},{"speaker":"あくつ委員","kind":"質問・要望","question":"前回の委員会のときにも伺ったのですが、また、そういったお子さんたちが非常に生き生きと踊っていられる。何か今、考えていることがあれば、教えてほしいと求めました。","respondent":"中山障害者福祉課長","answer":"今、特別支援学校であったり、あるいは、それぞれの通所の施設で、そういったクラブ活動の中でやっているところです。地域活動支援センター逢の中でのパフォーマンスであったり、描く、そういうような形で広げていけるような取組みを考えてまいりたいと考えています。","id":"exchange-008"},{"speaker":"あくつ委員","kind":"質問","question":"最後になりますけれども、それに関連して、今日はオリンピック・パラリンピックの特別委員会ですので、何かオリンピックを見据えてというところでのお考えがあれば、あわせて教えてほしいと求めました。","respondent":"中山障害者福祉課長","answer":"いろいろな形で多目的に使う予定なのですが、障害者の方に、少しそういった活動も新たに始められるのではないかというふうに思っております。ちょうどオリンピックが始まる２年前ぐらいのタイミングにはなりますので、ぜひ積極的に行ってまいりたいと考えています。","id":"exchange-009"},{"speaker":"あくつ委員","kind":"意見","question":"２年前、平成３０年に総合支援施設がオープンするということで、ぜひ、オリンピックに障害者の方のダンスというのを、どういう流れになるかわかりませんけれども、品川区においては展開できるような流れでお願いをしたいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-010"},{"speaker":"吉田委員","kind":"質問・要望","question":"そこが境なのでしょうか、教えていただきたいのと、例えばどういうことかということを教えていただきたいです。東京都の話ですけれども、もし何かつかんでいらっしゃるようなことがあったら教えてほしいと求めました。","respondent":"小川オリンピック・パラリンピック準備課長","answer":"２点目、大変厳しいところがありますが、そういった商業主義をできるだけ緩めたいというのがアジェンダ２０２０で示された考え方です。３点目、具体的に何かということをこちらのほうでは、現段階ではつかんではおりません。","id":"exchange-011"},{"speaker":"吉田委員","kind":"確認","question":"いろいろなパフォーマンスとか身体的に表現するとか、そういうふうに、この辺から変わっていったという感じに捉えてよろしいのでしょうか。それは確認です。","respondent":"小川オリンピック・パラリンピック準備課長","answer":"委員ご指摘のとおりですが、あわせてつけ加えしますと、そうした関係者、アスリートだけでなく、全国民的にそういった気運を盛り上げて参加をするというような形に変わっていったですが、そういった文化プログラムが本当に花開いたのはロンドン大会と言われているところです。","id":"exchange-012"},{"speaker":"吉田委員","kind":"意見","question":"ぜひ、こういう機会にいろいろな表現の機会ができるように、特に品川区ではそういうことを進めていっていただけたらいいというふうに思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-013"},{"speaker":"高橋（伸）委員","kind":"質問","question":"今の吉田委員に関連した話なのですけれども、文化プログラムなのですが、来年の夏にブラジルでリオデジャネイロ大会があります。もう公開されていると思うのですけれども、わかっている範囲でよろしいのですが、教えてほしいと求めました。","respondent":"小川オリンピック・パラリンピック準備課長","answer":"ロンドンよりも、もう今年の９月１０日から来年の２月に向けて、そういったイベント関係について公募をしているというふうに聞いてあります。実際に開催が行われるのが来年、２０１６年４月１日から２０１６年９月３０日というようなことで、今は概要をつかんでいるところです。","id":"exchange-014"},{"speaker":"石田（ち）委員","kind":"質問","question":"７割を超える方が関心があるというふうに答えている一方で、テレビやビデオで鑑賞や観戦を楽しむという人も多いと。これは平成２２年につくられているので、区民の文化芸術、どういうふうに捉えているのかというのをお聞きしたいのですが。","respondent":"間部文化観光課長","answer":"どうしても区の役割というのは総合調整だとか支援ということなので、どうしても町場の前線で、そういう部分の意見を上げてもらう。一年一年、前進をしていくというのが基本的なスタンスだと考えておりますので、このような考え方で今後も進めていきたいと考えています。","id":"exchange-015"},{"speaker":"石田（ち）委員","kind":"質問","question":"少しでも区内でどのように、どんなものが、こういう時期にというのがわかる資料があったらよかったというふうには思ったのです。オリンピックを機に、こういった区民意識の調査や団体への声聞きなどをしたらいいのではないかと思うのですけれども、その辺の考えはどうか尋ねました。","respondent":"小川オリンピック・パラリンピック準備課長","answer":"実は昨年も行いましたけれども、２年に１回の世論調査がございまして、いろいろさまざま調査をさせていただいているところです。オリンピック・パラリンピックを契機に昨年も実施いたしましたので、来年の世論調査に向けましても、引き続きやっていきたいと考えています。","id":"exchange-016"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"先ほど課長も、そういった環境整備をどうやってしていったらできるのかというものの参考として、改めて調査をしていただけたらと思います。要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-017"},{"speaker":"筒井委員","kind":"確認","question":"確認なのですけれども、この素案の６ページにもありますとおり、自治体以外でも大丈夫ということでよろしいのでしょうか。既存の事業だけではなくて、新しい文化プログラムを品川区でまた考え出していくということもあり得るのかということをお聞きしたいと思います。","respondent":"小川オリンピック・パラリンピック準備課長","answer":"それは組織委員会のほうで考えることではありますが、いろいろな要件を備えて、そういったことも認定をされるのではないかと。区としても、いろいろさまざま検討した上で、新しい試みも十分考えていきたいと考えているところです。","id":"exchange-018"},{"speaker":"渡辺委員","kind":"質問","question":"幾つかあるので、それぞれで分けて伺っていきます。数値なのか、あるいはキーワードなのか、この辺を説明するよう求めました。","respondent":"小川オリンピック・パラリンピック準備課長","answer":"一人一人、オリンピック・パラリンピックがまさにいろいろな、次に向かってのステップにつながるということが一番理想的なことだと考えております。レガシーとしても、そういった気運が残って、品川区が持続的に発展していくということを目指していきたいと考えております。","id":"exchange-019"},{"speaker":"渡辺委員","kind":"質問","question":"真面目に、真剣に検討すべき課題かという思いがありますので、その辺のご見解を一つ。教えてほしいと求めました。","respondent":"小川オリンピック・パラリンピック準備課長","answer":"１点目なのですけれども、それは早速、来年度以降ぐらいには何らかの形で青写真を描いていきたいというふうに考えているところです。来年の後半から再来年にかけては、本当に右肩上がりで、いろいろな部分で進めなければいけないということを区としては十分認識しています。","id":"exchange-020"},{"speaker":"渡辺委員","kind":"質問","question":"そういう意味では、一つの例として、例えばストリートダンス系、ストリートミュージックというのですか、シンガーが駅前で歌っているとか。これも抽象的になってしまって、やむを得ないのですが、仕組みとかがあるべきだと思いますが、その辺を説明するよう求めました。","respondent":"小川オリンピック・パラリンピック準備課長","answer":"区内３競技がありますので、この３競技について、具体的に区として計画をつくっているところです。それにつきましては、しかるべきときに公表してまいりたいと考えています。","id":"exchange-021"},{"speaker":"渡辺委員","kind":"質問・要望","question":"では、適地はどうだ、何だとなったときに、これも言葉遊びではないのですが、これから区有施設の改修がある。座って見られるとか、そういう作りはぜひとも取り入れていただきたいと思うのですが、いかがでしょうかということで終わりたいと思います。","respondent":"柏原企画調整課長","answer":"それは、施設の形態だとか、そういったところもありますので、個々のものを判断しながらという部分は出てこようかと思います。検討していますのは、そういった兼ね合いを見ながら、そういったご意見も参考にさせていただきながら検討を深めたいというふうに思ってあります。","id":"exchange-022"},{"speaker":"南委員","kind":"質問・要望","question":"その辺の掘り起こしも含めて取り組んでいただくことが、そのあたりの考え方、調査も含めてやっていただきたいということで伺いたいと思います。出るべき記録が出ないみたいなこともあり得るのではないかと、そういうところの意見というのは、その辺についてはどういうふうになっているのか。","respondent":"間部文化観光課長、安藤文化スポーツ振興部長、小川オリンピック・パラリンピック準備課長","answer":"そういう支援の仕方を今、太鼓が一番難しいのは、太鼓をたたける施設が非常に少ないというのがあります。その範囲での支援になりますけれども… おととしあたり、区民芸術祭の一つのプログラムとして組み込んで、区民の皆様にご紹介させていただきました。それはスクエア荏原でやって… ２０２０年のオリンピック・パラリンピックの日程についてですが、都が設定したものですので、区としての見解は差し控えさせていただきたいと思います。","id":"exchange-023"},{"speaker":"南委員","kind":"質問・要望","question":"質問したのですけれども、ぜひ、いろいろな機会を捉えて言っていただけないかと。ぜひ育成を進めていただきたいということと、さっきお願いしたつもりなのですけれども、。","respondent":"間部文化観光課長","answer":"伝統文化の育成、掘り起こしについては、文化振興事業団とも協力しまして、地道に行っていきたいと思います。","id":"exchange-024"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/515238?Template=document&Id=6484#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=18&TermStart=2015-01-01&TermEnd=2015-12-31"}],"sourceMeta":{"pages":0,"characters":28146,"voices":60}},{"id":"h27-20151208-10","meetingId":"h27-cm12","date":"2015年12月8日","dateIso":"2015-12-08","committee":"議会運営委員会","time":"午前１０時３０分～午後 １時２８分","status":"正式会議録","sourceType":"formal","overview":"議会運営委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を52件整理しています。","topics":[{"id":"topic-01","title":"平成２７年請願第３０号、区民参画を促進するための品川区議会改革を求める請願","agenda":"平成２７年請願第３０号、区民参画を促進するための品川区議会改革を求める請願","exchanges":[{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"意見陳述についてですけれども、３月のときにもそうだったのですけれども、地域の住民の方からの、ここでは言い切れない部分をもっと皆さんにわかっていただきたいという思いでの意見陳述ということだと思いますので、ぜひ、審査の前に意見陳述を聞く場をつくってほしいと求めました。","respondent":"渡辺委員長","answer":"その補助として、現状についての事務局長の説明を聞くという考え方でいます。請願者の意見陳述、ましてやその取扱いは、今、イエス、ノーではなく、先ほど説明したように、その後にしっかりと話していただこうと思います。","id":"exchange-001"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"意見陳述をしているところの話もさまざま伺ったのですが、意見陳述を受けることで、大変議論が深まると聞いてきました。皆さんからの意見も聞いてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-002"},{"speaker":"本多委員","kind":"意見","question":"今の申し入れについては、内容はわかりましたけれども、取扱いとしては、やはり議会運営委員会に付託された請願ですので、議会運営に関することですので、まずは委員同士の議論をしてから、陳述をほしいと求めました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-003"},{"speaker":"塚本委員","kind":"意見","question":"タイミングは、先ほど委員長が述べられたとおり、結論を出す段階の中で図っていただければいいと思います。委員で議論をする前に聞くべき必要性よりも、委員会と認識しておりますので、そのように諮ってほしいと求めました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-004"},{"speaker":"鈴木（ひ）委員","kind":"意見","question":"ちょっと一言なんですけれども、なぜ、委員同士でやる前に意見陳述を受けるのがだめなのか、その理由が、私は理解できないのですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-005"},{"speaker":"あべ委員","kind":"質問","question":"こちらから質問というのは具体的にイメージできないのですけれども、今回は、そぐわないかなという気がしております。これまでも、こういう話を出していただいているのに恐縮ではありますけれども、ある程度整えてからのほうがよいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-006"},{"speaker":"須貝委員","kind":"質問・要望","question":"それをもう少し見ていてほしいという気がしますし、区民にはあるかもしれないですが、もう少し待ってほしいと求めました。ですから、別の手順を踏んで、どうするか皆さんで議論をして考えたほうがいいのではないかと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-007"},{"speaker":"須貝委員","kind":"質問","question":"意見陳述を聞くかどうかということではなくて、どこのタイミングかか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-008"},{"speaker":"飯沼副委員長","kind":"確認","question":"今、議論の中に、陳述に対する整理ということがあったので、申し合わせ確認事項の２１ページに基本的なことは書かれているのです。一つは、どこのタイミングでするかというのは、あくまでも委員会で諮ってするという中身なので、それはそうなのでしょうけれども。","respondent":"渡辺委員長","answer":"そのとおりに諮らせていただいています。","id":"exchange-009"},{"speaker":"飯沼副委員長","kind":"質問・要望","question":"放射２号線の白紙撤回を求める住民委員会の方と地域が同じで、意見も述べていきたいと思いますので、よろしくお願いいたします。ぜひ、本当に請願者の思いを酌み取るというところで、発言をお願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-010"},{"speaker":"あべ委員","kind":"提案","question":"ですから、今ご提案のある形とは全く違うので、運用するにしても、ある程度詰めていかないといけないかとは感じております。それは議会改革検討会のほうでも議題として取り扱うように提案もしておりますし、実際に、検討項目の一つとして入っていたと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-011"},{"speaker":"鈴木（ひ）委員","kind":"提案","question":"なぜ選ばれたかということで言えば、やはり濱野区長がこの３本をやってほしいと東京都に提案をしたというところから始まっているということが一つ。なぜ議員同士の議論をする前に、ちょっと聞かせていただけたらと思うのですけれども、いかがか尋ねました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-012"},{"speaker":"塚本委員","kind":"意見","question":"区民の方の意見陳述を受けることが、結論を出すことに関して効率的で意味があるのではないかと、私は思います。最後に必要性があれば意見陳述を聞くというのが、結論の出し方として効率的であると、私は思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-013"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"こういうことを求めるという請願の審査なので、全てこの住民の思いを受けとめて、そして審議をするのが請願審査だと思うのです。住民がもっと補足して言いたい、もっとわかってほしいというところを全て受けとめて審査に入るほうが、私は思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-014"},{"speaker":"塚本委員","kind":"意見","question":"ここはどういうことなのか確かめたいところも、私はよりよいやり方、結論の出し方ではないかと思っていますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-015"},{"speaker":"たけうち副委員長","kind":"意見","question":"そこを変える意味で、意見陳述を後にやるほうが、陳述人にとっていい場合もある。そこをどう判断するかということで、やはりその都度諮っていくほうが、私はいいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-016"},{"speaker":"本多委員","kind":"質問・要望","question":"無所属の議員はお一人ですから、全部が各会派の事前協議ということには当てはまらないのです、議会というものは。4)にも書いてありますように、議会改革検討会を設置することを求めます、ちょっと意見を述べて終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-017"},{"speaker":"須貝委員","kind":"質問・要望","question":"住民が２年ごとに交代してボランティアとして議会に参加していくというような、今の現状では、私はなかなかここまで酌み取ることは難しいと思います。監視とは言いませんが、今後について、区議会の変わりようを見てほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-018"},{"speaker":"あべ委員","kind":"意見","question":"だから、やってはいけないということではないのですけれども、その辺も踏まえてと考えています。あまり階層が違うところで、同じ議論をしてしまうと、後で整合性の問題が出てくるので、ちょっとそれだけとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-019"},{"speaker":"飯沼副委員長","kind":"質問","question":"最初の冒頭の1)のところ、現状で返しているのかどうか、そこをちょっと一つお伺いしたい。結果がどうなるかは、議会はきちんと聞く耳があるんだというような思いが持てるようなプロセスを踏んでいかなければいけないと思っています。","respondent":"原区議会事務局長","answer":"先ほどご説明した部分につきましては、今年３月２６日以降のものについては、採択、不採択も含めて、同じような形でご案内をしています。","id":"exchange-020"},{"speaker":"塚本委員","kind":"質問","question":"これまでの議論の中で、特段こちらから伺うという必要性は、今のところ感じておりません。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-021"},{"speaker":"鈴木（ひ）委員","kind":"意見","question":"それを議会で聞かないと一方的にしてしまって、本当にいいのだろうかと、そういう思いが本当にしています。ぜひとも意見陳述は受けていきたいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-022"},{"speaker":"あべ委員","kind":"質問・要望","question":"今回は見送っていただいて、きちんと議会の中で手続を整えたうえで前向きに、議会としては仕組みを整えてほしいと考えています。若干の事実確認などもできるような形になるといいとは思っているのですが、これも皆さんの合意のうえですから、本日については見送ります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-023"},{"speaker":"須貝委員","kind":"質問・要望","question":"もしどうしてももっと話したい、聞いてほしいということならば、誤解のないようにしてほしいと求めました。今回に関しては、私は、必要ないと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-024"},{"speaker":"沢田委員","kind":"意見","question":"2)、3)、4)に関しましては、議会改革検討会で、現在、検討中ということもあります。議会改革をしっかりと進めていかなくてはいけないという思いでありますので、この項目については、今回は不採択ということでお願いしますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-025"},{"speaker":"塚本委員","kind":"質問・要望","question":"１枚目につきましては、それはしてほしいと求めましたけれども、これ以上のものが実現することは難しいかと考えています。いずれにしても、2)、3)、4)は、議会改革検討会とか、今やっておりますので、こちらを見守るということが、今の態度としては適切かです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-026"},{"speaker":"鈴木（ひ）委員","kind":"提案","question":"2)は、できる限りなくす方向で検討すべきだと思いますので、オープン化は改めて検討が必要だと思っています。このテーマでやっているわけですから、区民の要望や提案を直接聴聞する機会をつくるというところがありますので、私はとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-027"},{"speaker":"あべ委員","kind":"提案","question":"イエスかノーかというだけではなくて、何かお互いに提案し合うようなコミュニケーションの場が別にあると、より建設的なのかと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-028"},{"speaker":"須貝委員","kind":"意見","question":"ですが、現段階では、皆さんの意向を酌むということはできません。現段階では、申しわけありませんが、不採択としますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-029"}]},{"id":"topic-02","title":"平成２７年請願第３１号、品川区内特定整備路線計画に関する特別委員会設置の請願","agenda":"平成２７年請願第３１号、品川区内特定整備路線計画に関する特別委員会設置の請願","exchanges":[{"speaker":"飯沼副委員長","kind":"提案","question":"補助２８号線、補助２９号線に関してということで、特別委員会設置というのはとてもいい提案であると思って受けとめました。アンケートも取ったのですが、紹介してよろしいか尋ねました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-030"},{"speaker":"飯沼副委員長","kind":"質問","question":"ですから、そういうことで特別委員会設置はとても意義深いことであると思うので、そこの意見をまずお伺いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-031"},{"speaker":"あべ委員","kind":"質問","question":"そういった意味では、これを特別委員会として扱うというのは、いろいろと他の常任委員会との不整合などもあるので、どうかなと思います。議論の枠組みとしては、常任委員会が適当ではないかと思うのですが、いかがか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-032"},{"speaker":"本多委員","kind":"質問・要望","question":"私は認識しているのですが、そういった場で投げかけるとか、そういう思いを請願者にお伝えする方はいらっしゃらないのでしょうか。できなければ結構ですが。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-033"},{"speaker":"飯沼副委員長","kind":"質問","question":"これが出てきたのは１１月１９日です。うちの会派がお話を伺って、お返しをするだけではなくて、皆さんに知っていただくという意味で重要であると思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-034"},{"speaker":"鈴木（ひ）委員","kind":"意見","question":"集中的に議会として委員会をつくってほしいという、こういうふうな特別委員会でもっと集中してやってほしいという住民からの請願なので、それはそれで住民の意見としてとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-035"},{"speaker":"本多委員","kind":"意見","question":"ただやはり、議会運営委員会では、特別委員会の設置ついては、単年度で、どうするかと真剣に議論しているのです。わからないなら、わからないで結構ですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-036"},{"speaker":"飯沼副委員長","kind":"質問","question":"今のご質問からすれば、伝えていません。でも、伝えていないからといって、問題ではありません。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-037"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"私たちがかわりに伝えますよ、議会運営委員会の中で、私たちが住民の方々のかわりにそれを主張しますというのではなくて、これは請願として、ここの中で、みんなで議論してほしいということで出されたので、その質問そのものがおかしいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-038"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"中身のたくさんある委員会ですから、特定整備路線を特別委員会でやって、審議を深めることは矛盾しないでできるのではないかと思っています。そういうところをしっかりと受けとめて、議会として深めていく特別委員会をつくることには、私ばぜひ応えていきたいと思っています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-039"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"本当にここにもあるように、生きる権利にかかわる重大問題と言われるくらいの中身を、皆さん訴えたいということですから、そこのところはぜひとも意見陳述を受けていきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-040"},{"speaker":"須貝委員","kind":"意見","question":"よくその内容もわかりまして、住民の意見、またすぐにやってくださいという意見もありました。だから、そこで十分理解できたので、意見陳述については、私は必要ないと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-041"},{"speaker":"沢田委員","kind":"質問","question":"もう既に特定整備路線の話は出てきてから３年たちますけれども、建設委員会の中でも、その都度議論はされてきました。当然、常任委員会で、そういった議論がされているので、あえて特別委員会を設置する必要はないと考えます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-042"},{"speaker":"塚本委員","kind":"意見","question":"毎年５月に特別委員会の設置を議論していく中で、皆さんの議論の中で、その手続にのっとってやっていくのが妥当であるということです。内容云々というよりも、特別委員会設置の手続として、今の手順を踏んでいくのが妥当であろうと考えていますので、不採択ですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-043"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"この道路そのものが、６９年前に決定されたことをもって進めているという、本当に理不尽なやり方での道路の進め方なわけです。多くの住民が犠牲にされようとしているわけですから、６点にわたりさまざま議会に求めていることに対して、調査なり。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-044"},{"speaker":"あべ委員","kind":"意見","question":"理由は、先ほどと繰り返しになりますけれども、手続的に、特別委員会の内容を決めるのは５月の年度はじめということになります。その他の場所で議論されるにしても、その内容がここになるかどうかというのは、またそのときの議会運営委員会に任されると考えておりますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-045"},{"speaker":"須貝委員","kind":"質問","question":"東京都が都市計画ということで実行するわけですから、特定整備路線の計画に関しては、一切変更しないという話も聞いています。建設委員会で議論しているということなので、さらに特別委員会を設置することは問題があるかということで、私は不採択とします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-046"}]},{"id":"topic-03","title":"東京都後期高齢者医療広域連合議会の報告","agenda":"東京都後期高齢者医療広域連合議会の報告","exchanges":[{"speaker":"本多委員","kind":"意見","question":"平成２８・２９年度の保険料がどうなるのかということは、１２月に入って、このような保険料の考え方について示しがありました。簡単ですけれども、報告を終わりますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-047"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"ここの中には、この先、財政安定化基金拠出金などがさらに増額されるという可能性があるのか、どうなのかということ。今までの特例軽減は２０１７年度からなくすということは、これは算定の中に入っているのかどうかというところを教えてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-048"},{"speaker":"本多委員","kind":"意見","question":"申しわけないのですけれども、当然、特例軽減等を考慮したうえでの算定だと思います。それから、最初のほうのことにつきましては、ここの説明文のとおりだと思うのですけれどもとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-049"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"特例軽減の部分については、多分議長会とか、区長会とか、区のほうとしても軽減を継続するようにということで、政府のほうに上げているという答弁だったのですけれども、そこら辺のところの方向のようなものは、特に説明はされなかったか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-050"},{"speaker":"本多委員","kind":"意見","question":"(10)の、国からの激変緩和措置の内容が示されてないので、現行通りということですので、おそらく、今後、考慮していくと思うのですが、現時点では(10)に書かれているとおりかと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-051"},{"speaker":"あべ委員","kind":"確認","question":"確認ですけれども、防災訓練アンケートについて、これは本部員の拡大、それから本部に行ったものについて、１枚目と２枚目、両方書くのか尋ねました。","respondent":"原区議会事務局長","answer":"今回、幹事長の拡大訓練ということでさせていただきました。そういった意味では、大変恐縮ですけれども、２枚にわたって記載をいただければと思います。","id":"exchange-052"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/993740?Template=document&Id=5164#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=10&TermStart=2015-01-01&TermEnd=2015-12-31"}],"sourceMeta":{"pages":0,"characters":35481,"voices":155}}]);
